/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20120820-9","meetingId":"h24-cm08","date":"2012年8月20日","dateIso":"2012-08-20","committee":"文教委員会","time":"午後１時００分～午後６時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の順番では２の報告事項でありますが、先に予定表の３ 所管事務調査","agenda":"の順番では２の報告事項でありますが、先に予定表の３ 所管事務調査","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"済みません。今、制度的にこの私立保育所だけを取り出してこれだけ増えましたということから、これをベースに話したいことというのは一体何なんでしょうかと、ちょっと実は戸惑いがあるんですけれども。どうなんでしょう。これは、要は何の目的で、どういう発想の中からそこをくみ取られたか、ちょっとそこを合わせておかないと所管事務調査の調査・研究ができないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-001"},{"speaker":"阿部委員","kind":"質問","question":"すみません。何かちょっとぶしつけな質問で大変恐縮なんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-002"},{"speaker":"阿部委員","kind":"意見","question":"そうすると、私立保育所としての運営の特性について、私立の保育所はこうあるべきだという、そういうテーマですね。ちょっとそれには材料が足りないかなと。さらにほかに。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-003"},{"speaker":"金野委員長","kind":"提案","question":"逆に申し上げますが、今回のこのテーマは、阿部委員のほうからもご提案いただいたものでありまして、その中で対公立保育園との運営の違い、私立保育所の運営の特色を見ていくかというところで、所管事務調査の中で年間計画として挙げてきたものですので、そのようなご質問をいただくということが、私としては逆に不思議に思っております。いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"率直に言って、要はその問題意識がどこにあるのでしょうか。逆にここからスタートライン。皆さんから、これから出るのかもしれないですけれども、実施のテーマが。どうするんですかね。そうですね。増えましたね、で、ここは終わり。ごめんなさい。何か、どういう話が、私立と公立。すごく戸惑いが。ほかの委員の方、どうですか。どうなんでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"今日拝見した中では、保育内容を見るというような見方ではなかったようなと考えていますし、今日の視察をもとに品川区の私立保育所の運営について議論をして、今後の方向性というのをちょっと、何ていったらいいんですか、今見てきたことを論じようとするテーマのバランスがとれていない気がしますけれども。言いたいこと、わかりますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"すみません。それで右のほうが私立なので、私立のほうが増えているのは８２１人ですか、５年間に。私たち今までやってきた、詰め込み保育みたいな、そういうことであってはならないというふうに思うんですが、そのあたりの区としての物差しというんですかね、基本ラインというのをどういうふうに考えているのか、そのあたりをちょっと伺いたいんですがよろしいですか。その２点です。","respondent":"伊崎待機児童対策担当課長","answer":"今日ご覧いただきましたところも、定員よりも多く入っているというご指摘ございましたが、施設の状況をご覧いただきまして、定員より多く、受け入れが可能であるからそのように弾力的に対応しているということで、環境のほうは子どもたちの生活、お互い最善の利益を確保しながら。","voiceIndex":22,"id":"exchange-007"},{"speaker":"南委員","kind":"確認","question":"ちょっとごめんなさい、うっかりしていて。確認したいんですけれども、先ほどの定員のところで、公立保育園は６２３人の定員増と、私の計算では増えていることになっているんですけれども、その増えている内訳というのは、一つは定員増と、もう一つ何とおっしゃったか。","respondent":"伊崎待機児童対策担当課長","answer":"今、弾力化を無制限に、平成２２年度からできるようになっておりますので、品川区でも当然施設環境と人的な配置は確保しながら、弾力化で対応していくことになっています。","voiceIndex":24,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"だから、そういうふうにさせないためにも、だから定員が決められているわけで、その辺というのは一定程度のラインを引かなくてはいけないし、そこは公立だからこそしっかり守らなければいけない、だからこそ守っていただくように、民間には私立も含めて指導しなくてはいけないというふうに思うわけで、その辺のブレーキというんですかね。","respondent":"伊崎待機児童対策担当課長","answer":"私立に対しましても、公立で行う研修や、都等々で行う研修のご案内、あと私立幼稚園の園長会などへ参加させていただいたり、あと年に１回東京都の監査が入りますので、それに同行しまして育成状況、教育状況を確認していく中で、子どもの育ちをきちっと確保していくということが。","voiceIndex":26,"id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"弾力化が無制限にできるようになったというふうなことはあっても、品川区としては一定のライン、施設の状況に応じて無制限に、いわゆる、言葉は悪いですけれども詰め込む、待機児解消のためといいながらも詰め込む、そういうことはしないというふうに、何というんでしょうか、信頼をして見ていっていいのかどうか、ちょっとそのあたりをお伺いしたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"今申し上げましたように、きちんと環境を整えながら受け入れを図っていっております。","voiceIndex":28,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"これからも、そういうことできちんと守っていただいて、やっていただきたいということをお願いしておきますが、何となく部長さんの姿を拝見すると不安を感じざるを得ません。ぜひ一言大丈夫だと。しっかり守るというふうに言っていただきたいなと考えていますが、いかがでしょうか。","respondent":"金子子ども未来事業部長","answer":"ご指名ですけれども、今、待機児童対策担当課長が申し上げたとおりの方針で対応しております。","voiceIndex":30,"id":"exchange-011"},{"speaker":"伊藤委員","kind":"確認","question":"何点か確認させてください。ありがとうございました。だからこれはそういうことでどういうふうに財源を入れていきますか。当然品川区の税金を投入しているわけですから、このことを前提として、それぞれの園でしっかりとした教育が展開されなければならないと思うので、そのことをまずお伺いします。だから、のぞみ保育園とキッズタウンにしおおいではどういうふうに展開されてきているのか教えてください。","respondent":"立川保育課長","answer":"保幼小の連携につきましては、私立の場合それぞれ自主的に学校のほうにアプローチしていく。学校のほうから、近隣の保育園、幼稚園に声をかけてもらって、年間を通じて交流事業、運動会であるとか、給食交流であるとか、行事中心でまず交流を始めていただいているという状況です。","voiceIndex":32,"id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問","question":"あれは交流するときに公立の保育園だけ展開したのではないと思うんですけれども、公立の幼稚園、それから品川区のさまざまな私立保育所、保育園等、やはり税金を投入している以上はそういう方針に従って、強制的ではないけれども、やはりある程度のものを展開していく必要があるのではないかなという、そういう素直な思いがするので、もう少し具体的な内容で答弁をお願いします。","respondent":"立川保育課長","answer":"ただ、やはり学校側のほうで複数の保育園、幼稚園を受け入れるというところで、なかなか難しいところがあります。","voiceIndex":34,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"それから気になったのは、保育をどんどん外に出すことについて、私たち自民党はそれをやれと言っていた立場ですから賛成するんですけれども、逆に見えなくなってくるところがあります。だけれども、品川区はさまざま形で関与しているわけだから、やはりそういうことについては吸い上げていくシステムをつくっていくべきではないかなと思うんだけれども、そのことについてのお考えをお願いします。","respondent":"立川保育課長","answer":"その辺、公立におきましても、ある意味園の中の園長を中心に処理していく方向であって、それ以上、いわゆるそこで解決できない場合、保護者から直接保育課のほうに私立、公立問わず苦情が上がってくる、苦情、要望が上がってくるところは、ある意味一緒のところです。","voiceIndex":36,"id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それはそういうことですのでここまでにします。単純に思うのですね。私立のほうはさまざまなものを持っているでしょうし、ある意味その経営としての商品なんでしょうから、なかなかそういうのを出すことは難しいのかもしれない。もしくはそのノウハウを共有していく責任をつくっていくとか、新たな形で連携をつくっていくべきだと思うんですが、そのことについてのお考えはいかがでしょうか。","respondent":"立川保育課長","answer":"私立のよいところは公立で、公立のいいところは私立にも実施していただく、その辺のシステムがないのではないかというご指摘だとお伺いしたんですけれども、その辺につきましては園によるんですが、私立との交流では、例えばプールを一緒に使えるところは使ってもらうとか。","voiceIndex":38,"id":"exchange-015"},{"speaker":"伊藤委員","kind":"確認","question":"私も言いながら難しいだろうと思いますよ、もちろん。私立のほうは、それがやはりその売りになっている。ただ、繰り返しますけれども、難しいことはわかります。それからもう１点だけ、大井町のぞみ保育園は、今日の説明だとテンプスタッフ社長さんだったかな、個人の持ち物を保育園として扱っている。私は全部一緒じゃないといけないと思っていますので、そのことの確認を改めてお願いいたします。","respondent":"伊崎待機児童対策担当課長","answer":"それが施設とお金の流れの、１点目のご説明です。２点目の私立保育所の補助金ですが、私立保育園につきましては国が支弁ということで、負担金を交付しております。国と東京都と、あと区で基準の経費を国が２分の１、東京都と区が４分の１ずつ負担する形になっております。","voiceIndex":40,"id":"exchange-016"},{"speaker":"阿部委員","kind":"質問","question":"先ほどは失礼いたしました。幾つか質問したいと思うんですが、まずこの新規開設園の園数を見ますと、平成２０年度に２園、それから２年間ほどなくて、それから３園増えると近年急ピッチで増えてきているわけですけれども、この背景となっている、何か要因というのはあるんでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"平成２１年、平成２２年につきまして、確かに開設はございませんが、この間に幼児教育を保育園で進めていくという視点とまた違う視点の、待機児童対策の側面からの対応に力を入れてきておりまして、平成２２年度はご存じのとおり公立保育園での定員拡大を行う中で。","voiceIndex":43,"id":"exchange-017"},{"speaker":"阿部委員","kind":"質問","question":"すみません。私立保育園が運営主体の認証も増やしてほしいんですけれども、認可保育園をとったはいいけれども、１０年で子どもがいなくなったということでは、多分経営される方も困るんでしょう。その辺の子どもが減った後のバランスということも、ある程度念頭に置いていらっしゃるのかどうかということもあわせて伺います。","respondent":"伊崎待機児童対策担当課長","answer":"区では現在、長期基本計画の見直しに伴う人口動態調査と同時に、保育事業調査を実施しております。この結果を踏まえまして、今後の対策については考えていくということになります。","voiceIndex":47,"id":"exchange-018"},{"speaker":"阿部委員","kind":"質問","question":"具体的なところは保育事業調査を行って、その結果を見ながらということで、それはスケジュール的には何か出ているものがあれば教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"保育事業調査につきましては、年度内に一定のめどはつける予定です。","voiceIndex":49,"id":"exchange-019"},{"speaker":"阿部委員","kind":"質問","question":"ありがとうございました。と同時に障害者の受け入れ。これについても何らか、私立保育所に対する基準を持っていらっしゃるでしょうか。あるいはお願いベースなのか、一切その保育園ごとのお任せになっているのかも教えてください。","respondent":"立川保育課長","answer":"もう１点、障害者の関係につきましては、受け入れる、受け入れないという部分につきましては、各保育園の特別支援ということで、一応入る前に認定審査を行っておりますけれども、それで受け入れてもらうという前提がありまして、実際に受け入れてもらえたのであれば。","voiceIndex":51,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"さっきの私の質問のところで、ちょっと改めて確認したいと思ったんですけれども、受け入れ枠を随分増やしてきたというのはこの数字でもわかるけれども、具体的に何人ぐらい、どれで何人増えたかというのをちょっと知りたいと思ったんです。二つです。","respondent":"伊崎待機児童対策担当課長","answer":"待機児童対策につきまして、私立、公立の定員拡大、弾力化、それぞれ数字のほうをということでしたが、申しわけありません、細かい数字がございませんので、また改めて説明をします。","voiceIndex":58,"id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"人口動態や事業調査を見てという、そこはそれであると思いますので、一定の時期にまた報告をいただきたいと思います。それから、一番最初に質問した受け入れ枠の拡大については、次回の委員会でいいですから、ちょっとお知らせをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-022"},{"speaker":"高橋委員","kind":"意見","question":"まだ４月からなので、初めにかなり出していると思うので、ちょっと比べるのも難しいでしょうけれども、同じように大井町のぞみ保育園のほうでどれだけの経費を出していて、これぐらいの規模の保育園だと運営費がどれぐらいかというのを、次回でも結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-023"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"すみません。端的に２点だけ伺いたいんですけれども、私立の保育園、今日見させていただいて、ああ、いいなと思いました。私立園のほうが施設は新しいというような意味で、希望を出されるときに、やはり公立園だから、私立園だからというような傾向が見られるかどうかというのを実感で受けるか。数字を持っていれば教えていただきたいんですが、どれぐらいの比率で。２点教えてください。","respondent":"伊崎待機児童対策担当課長、立川保育課長","answer":"ご入園の申し込みについてですが、私立園、公立園というよりも、おっしゃられたとおり近い園というところをまず第一に考える方が多いと思われます。それ以外で公立でやっていて私立でやっていないところがあって、同じ保育料なんだけれどもという部分につきましては、思ったほどそういう問い合わせというのはいただいていないというのが現状でありますので。","voiceIndex":64,"id":"exchange-024"}]},{"id":"topic-02","title":"(1) 品川区立小・中学校のいじめ等の状況","agenda":"(1) 品川区立小・中学校のいじめ等の状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この手引書をつくって、改めてこういうふうに整備して対策をとるということに至った教育委員会の考え方というのは一定程度、何というんでしょうか、今社会問題になっているいろいろないじめを原因とする子どもたちの自殺について、相当な関心というか、認識をお持ちになったからこそなんだろうなというふうに理解はするんですけれども、まずこの手引書について。","respondent":"太田指導課長","answer":"いつごろこれを子どもに、またいつごろ調査をというお話でしたけれども、先ほど申し上げたように、これは９月に入って早々に学校のほうに示し、子どもたちにも示し、そしてまたこの生活アンケートについても、９月早々に実施する予定です。","voiceIndex":72,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひこういう手引書をつくりましたよということで、子どもさんや保護者、あと学校の先生方にも一刻も早くお伝えをして、きちんとした対策をとっていただくということは当然で、９月の早々にというお話なので、２学期からやっていただくということで取り組んでいただきたいというふうに思っています。やめるべきだと思っているんですけれども、その辺についてどんなふうに考えているのか、伺いたいと思います。","respondent":"太田指導課長","answer":"その学校評価等について、大津市の事件についてのお話ですけれども、大津市の件、今回その大津市の件も一つの重大なこととして捉えるというお話を申し上げましたが、品川区はそれ以前からさまざまな手を打って、このいじめに対しては対応してきています。","voiceIndex":74,"id":"exchange-026"},{"speaker":"南委員","kind":"意見","question":"このペーパーに、先ほど説明していただいた注１のところに、先ほどお話ししてくださいましたが、けんかやいたずらの範疇であったと学校が判断したものは外すという、それはあれなんですけれども、それではどういう物差しでけんかやいたずらだったのか、いじめではなかったのかというのを線を引くのか、そのあたりの基準というのはどういうふうに考えたらいいのか。","respondent":"太田指導課長","answer":"ですからそれは担当した教員等、その子どもたちの様子をしっかり見取って、先ほども申し上げましたけれども、一応いじめやけんかの範疇だと判断しても、継続的にその子たちを見ていく。","voiceIndex":76,"id":"exchange-027"},{"speaker":"南委員","kind":"確認","question":"最後に、最後にというのは、ちょっと確認したいのは、スクールカウンセラーの活用などによりというふうに２ページに書いてありまして、実際問題品川区は複数のカウンセラーを週に１回か３回ぐらいかな、学校に巡回できるようにという対策をとっておりますよね。","respondent":"太田指導課長","answer":"中学生になると生活指導主任がいたり、学校にはいろいろそういうふうな、いろいろな立場の教員、大人がおりますので、そういった大人が相談を聞ける体制を子どもたちに示していくということが大切なのかなというふうに思っております。","voiceIndex":80,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"そういう中で、「ああ先生に相談してもだめなんだ」、こういうふうに子どもはあきらめてしまうというのが今までの事例の中で、社会的に大きくなった問題の中で、結構そういう状況というのはあるという話ではないですか。したがってしっかりとこの点についても、今後第一義、第二義的課題として取り上げて、検討していただきたいと強く要望して、今回の質問は、ちょっと今は終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-029"},{"speaker":"伊藤委員","kind":"確認","question":"何点かまとめて質問します。今のお話ですと悪いんですけれども、ほかの自治体の例にあるように、教育委員会のこういう問題に対する隠匿体制がさまざま指摘されていますから、やはり、品川区としては守るべき情報は守らなければいけない。それはそうです。だけれども、区役所の情報を隠すようなこと、疑いは全く抱かれてはいけないわけで、そのことに関して、改めて教育委員会の見解を確認しておきます。","respondent":"太田指導課長","answer":"今先生おっしゃったように、守らなければいけないものについてはもちろん守りますけれども、今回の大津市で話題になっているような、情報を隠すということは決してその後の状況をよくするわけではありません。","voiceIndex":83,"id":"exchange-030"},{"speaker":"伊藤委員","kind":"確認","question":"手引書を見させていただきまして、これはもちろん貴重な思いがあるんですけれども、何といったらいいんですかね、チャート式にまとめるようなこともしたらいいのではないでしょうかということです。これは現場の狭小であって、私の個人的な感触なんですけれども、もう少しこれをわかりやすくして、保護者、それから児童・生徒に配ったほうが、より効果的な手引書となるように思います。","respondent":"太田指導課長","answer":"先生おっしゃるようにわかりやすくということでは、これからまた努力をしてまいりたいと思いますけれども、これを一つのパターンにまとめて、それに当てはめて、きちんと当てはめてというのは現実的にはなかなか。","voiceIndex":85,"id":"exchange-031"},{"speaker":"伊藤委員","kind":"確認","question":"私の思いとしては、もちろん千差万別の話ですから、それを表中の大枠に当てはめてみてもできないとはもちろん思います。だけれども、例えば共通のポイントとして、いじめの早期発見、それからその問題の確認、それから早い段階での該当生徒の指導というふうなところはある程度、何というかな、自然の流れとしてまとめができると思うんですよ。これはお願いして起きます。","respondent":"太田指導課長","answer":"ただ、今回このような状況を踏まえまして、改めてこういったものにまとめ、品川区の教員が同じ思いを持って、一丸となっていじめに対応するというようなことのために、今回これをまとめさせていただきました。","voiceIndex":87,"id":"exchange-032"},{"speaker":"伊藤委員","kind":"質問","question":"いじめの問題解決が目的であるなら。だけれども、もしそういう位置づけでこれをまとめたとするのであれば、より具体的な形で当該児童・生徒、それから保護者、それからＰＴＡの方々、地域の一部の方々にも浸透していただくことになれば、恐らく目的が達成されると思うんですが、そのことについてのお考えはいかがでしょうか。","respondent":"太田指導課長","answer":"今後、やはりこの中にもうたってあるように、いじめに対しては学校の内外問わず起こる可能性もありますし、子どもを取り巻く社会全体で解決していく問題でもありますので、まずはこれを教員に徹底させるということの次に。","voiceIndex":89,"id":"exchange-033"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひそれは、いい意味での前進になると思いますので、それはぜひよく検討していただいて、できれば９月に教員に配付した後でも結構ですから、それぞれの関係する方々にはこの内容、エキスを抽出したものを検討していただいた上で、配付を検討するようお願いをしておきます。それは去年の冬、鮫洲運河で裸で泳がせたということですね、被害者を。ですから本当に難しいんですよ。","respondent":"太田指導課長","answer":"そういったような、いじめを発見するすべといいますか、そういったものをなるべくたくさん持つようにして、子どもたちの周りに持つようにして、学校中心に子どものそういった問題行動も含めたいじめの発見については対応していきたいというふうに思いますし。","voiceIndex":91,"id":"exchange-034"},{"speaker":"伊藤委員","kind":"質問","question":"今、そういうのを聞いてふと思ったんですけれども、こういういろいろな角度からいじめということは追求していかないと、学校現場だけの責任ではないと私は思っていますので、ですから、今まさにお話あったように、警察の意見、お話がありました。大津市のああいう事件がクローズアップされたわけですから、例えば品川区教育委員会がメーンとなって、そういう関係諸機関がありますよね。","respondent":"太田指導課長","answer":"ただ、その内容をこういったいじめの視点からも高めていくということも一つ大切なことなのかなというふうに思いますので、そういう意識を我々も持って、その会の運営等にも当たっていきたいと考えています。","voiceIndex":93,"id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問","question":"これで終わりますけれども、今の体制で活用していただくことはもちろん一つなんですけれども、さっきお話をさせていただいた公立中学生が逮捕されたケースは、何というかな、ほとんど学校が把握しなかったという厳しい話をしてしまったものですから、やはりそれはさまざまな観点からシステム構築をして、いじめを未然に防ぐようなことを検討していってください。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-036"},{"speaker":"鶴委員","kind":"確認","question":"ほかの委員の方がお聞きになったかもしれないんですけれども、まずこれ、手引書の３ページから４ページの最初のほうに「（平成１８年文部科学省通知）」とあって、ただ前々回ぐらいの委員会のときに参考資料として提出されたようなものを改めてまとめられたものかなと思っているんですけれども、先ほど話があった中で、全国的にもクローズアップされてきた中で。","respondent":"太田指導課長","answer":"そのとおりです。","voiceIndex":97,"id":"exchange-037"},{"speaker":"鶴委員","kind":"質問","question":"それで、今ほかの委員からいろいろありました。それは今までも含めて、この９月に皆さんに、学校現場に配付をされるという中で、例えば、どこまで学校の先生が当該生徒、いるとすればやっていいのかどうかというのはありますね。その辺について、何か別途そういう配付されるものがあるのか、それとも学校現場で、それは具体的な形で個々に対応してくださいねという形なのか、そこを一つ教えてください。","respondent":"太田指導課長","answer":"ですから、何か一つ示すということではなくて、このように基本的な考え方を示すことで、あとは各学校で、もちろん教育委員会もいろいろな形で相談にも乗りますし、各学校で個別の、ただ、ここにも申し上げているように、担任１人で抱え込まない。","voiceIndex":99,"id":"exchange-038"},{"speaker":"鶴委員","kind":"質問・要望","question":"それはいじめという言葉で表現するのか、いろいろな形があるということがありましたけれども、当然人とのかかわりに社会の縮図があるので、当然好きや嫌いが、お互い嫌だどうだということもそうした形であらわれてくることが多分あると思うんですけれども、今これがいじめ等の状況についての報告についての質疑ですからあれですけれども、これは要望にしますが、いじめになる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-039"},{"speaker":"阿部委員","kind":"質問・要望","question":"いいですか、質問して。例えば、この第１段階で遊びと書いてしまっている。その確認と、今日いただいた資料の中で、品川区実施のいじめ事例件数、ここであるのは、第１・第２・第３段階すべてを含んだ数字なのでしょうか。さすがにけんかや冗談まで含めてこの数字というのは、多分あり得ないだろうと思っているんですけれども、どういう感じなんですか。","respondent":"太田指導課長","answer":"それと２点目ですけれども、その数字については先ほどご説明申し上げたんですが、このペーパーの中段に２のいじめ月例報告等の、例えば小学校の２７件とか３８件、これにつきましてはいじめと捉えた部分、第２段階、第３段階、それ以上というところの数字です。","voiceIndex":103,"id":"exchange-040"},{"speaker":"阿部委員","kind":"質問・要望","question":"第１段階のことやそれによるちょっとしたトラブルというのは、皆さん先生だったらご存じのとおり、本当に毎日毎日いろいろなところで起きているものですから、多分第２段階だってかなり日常的に、実際の学校の中では起きているであろうと思われます。それで、保護者が直接学校以外、あるいは教員以外のところに相談を持ち込んだときの、何か対応の定型というものがおありになるのか、どうでしょうか。","respondent":"太田指導課長","answer":"そういった定型というものはございません。","voiceIndex":105,"id":"exchange-041"},{"speaker":"阿部委員","kind":"質問・要望","question":"ぜひここは各学校にも徹底していただきたいんですけれども、他機関に相談することによって、その保護者が不利益を受けないように、あるいは学校や担任がそのケースを手放してしまわないということは、ぜひ徹底していただきたいと考えています。","respondent":"太田指導課長","answer":"この手引でも、学校は関係諸機関ともしっかり連携してというのもうたっておりますので、これをもとに再度、今までもそういう対応をしておりましたけれども、再度徹底したいと思います。","voiceIndex":107,"id":"exchange-042"},{"speaker":"阿部委員","kind":"質問・要望","question":"それを聞いて安心しました。ただ、これらの連携というだけではなかなか具体的な行動がわかりにくい部分もあると思いますので、ぜひ具体的に示していただければというふうに、書きかえなくて構いませんので、口頭でも構いませんが、ぜひ学校現場にそこは徹底をしていただきたいと思います。防止というところでは、残念ながらかなり弱くはないだろうかという、その辺のお考えをもう一度。","respondent":"太田指導課長","answer":"３点についてお聞きいただきましたけれども、まず１点目の、これが出たことによって安易にこの出席停止制度が運用されるのではないかということですが、先ほどご説明の際に私が申し上げたとおり。","voiceIndex":109,"id":"exchange-043"},{"speaker":"阿部委員","kind":"提案","question":"減らす方策というものを提案されている。そういったことを示さないで、ただいじめをなくそうとか、悪いことだというだけでは、なかなか難しいのではないでしょうかね。というのが、いじめ研究の世界の中ではかなり言い尽くされているので、釈迦に説法だとは思っているんでしょうけれども、そういったところからきちんと現場に示していくということもぜひお考えいただきたいんですけれども、いかがでしょうか。","respondent":"田村教育次長","answer":"ちょっと阿部委員の考え方は考え方で結構なんですけれども、この冊子そのものは、もう一度指導課長が先ほど来から説明しているのですが、いじめ防止の関係で、例えば具体的に見てもらうと、６ページは、６ページあるいは４ページの中段の表は、例えば第１段階。","voiceIndex":111,"id":"exchange-044"},{"speaker":"阿部委員","kind":"提案","question":"ありがとうございました。このテーマはしゃべっていると終わらなくなってしまうので、今第１弾という話もありました。ぜひ、これが第１弾というのであれば、さらに実効性のあるさまざまな提案を教育委員会のほうから現場のほうに提示していただきたいと考えています。私が知る限りでは残念なケースが多いように感じられますので、ぜひ今後もさまざまな形で現場の力になっていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-045"},{"speaker":"高橋委員","kind":"質問","question":"３つお伺いしたいんですけれども、一つ目は１枚のほう、アンケートの結果の二つ目のほうなんですが、これ４月１日から７月２０日までの結果のほうは、これ東京都教育委員会が７月の間にアンケートをとるようにというお話があったと思います。それは何というんですか、先ほどお話あったように、いじめられた子が学校から出ていくことで終わってしまっていることがあるわけですね。","respondent":"太田指導課長","answer":"こういったことを子どもを通じて家庭にも周知できるのかなというふうに思っておりますし、各学校では校長先生の学期初めのお話とか、そういった中でいじめについての内容を盛り込むようにというような形で、当初していっておりますし、また保護者会等でも、各学校ごとに校長が。","voiceIndex":115,"id":"exchange-046"},{"speaker":"高橋委員","kind":"質問・要望","question":"それをやはり、先生方はこういう取り組みをしているし、これからも先ほどいじめは許されないし、問題を隠すことは絶対しないとおっしゃっていますし、いじめを根絶させるとか、そういった決意とか、努力しているということを、先ほどもほかの委員からもありましたけれども、ちょっと冊子だと厳しいということなんですが、せっかく児童・生徒にこの半分の言葉なんですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-047"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"１件だけお伺いしたいんですが、この１ページ、読ませていただいたけれども、品川区の「いじめ」に関する考え方についてということで、品川区全体を見ていると思うんですが、これを１ページのこの文章をつくられるに当たってどのような話し合いがどれぐらい積まれて、このような形の文章になって、横断的にいろいろな区長部局の方とかも、教育委員会でよく見るんですが。","respondent":"太田指導課長、田村教育次長","answer":"この部分をつくるまでには、さまざま検討というか、それは意見交換をやりながら、済みません。ただ、新しいものもあるけれども、今までの文部科学省のほうから抜粋したものもあって、ただし教職員も異動がありますので、校長も異動があるので、毎年毎年それを徹底していくことがすごく重要になるという説明もしております。","voiceIndex":119,"id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"私は先ほど質問遠慮してしまったんですけれども、その分簡潔に。最後の最後の対策だということを改めて確認いたします。ぜひ教えていただきたいんですけれども。そういう場面で共通認識を持つ、情報交換するということがやはり大事なので、ぜひその辺も話し合う情報交換の場はどういうふうに考えているのか、ちょっとそこについて確認をしたいと思います。そういう意味で私は質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-049"},{"speaker":"南委員","kind":"質問","question":"そのことは本当に歓迎できることだというふうに思っているんです。であるならば、やはり遺族の希望は、それは尊重しながらも、いいですか。そういう点で、どういうふうに品川区としては自殺と、しなかったそこのところと、いじめがなかったという根拠は何なのかと、そこのあたりはやはり明らかにする必要はあるのではないかなというふうに思うので、そこについて伺いたいと思います。","respondent":"太田指導課長","answer":"事例をですけれども、事例をもっとアピールしてですが、なかなか具体的な事例を子どもたちにということは、発達段階もありますし、個人情報の心配もありますので、そこのところを十分考えて、子どもたちへの指導については考えていくことと認識しております。","voiceIndex":124,"id":"exchange-050"},{"speaker":"南委員","kind":"意見","question":"やはり第３、第４の、こういう自殺という事例を出させないために、やはり子どもたちに年齢に応じた、発達段階に応じた、そのことに対しての大人側の問題意識等を子どもたちに伝えていく必要はあるのではないかなというふうに思うんです。それからこころの相談フリーダイヤルをつくりますよという、そういうことであると思うんですけれども、何かそういうことも含めて、やはり今回のお二人の本当に残念な……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-051"},{"speaker":"渡部副委員長","kind":"質問","question":"だから、それとこれとは違うと言っているじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-052"},{"speaker":"渡部副委員長","kind":"質問","question":"今はいじめ防止に関する手引書についての報告で、いじめに対する議論をしているじゃないですか。自殺の話じゃないじゃないですか、今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-053"},{"speaker":"南委員","kind":"質問","question":"自殺を出させないためにつくったというふうに説明しているじゃないですか。","respondent":"田村教育次長","answer":"なぜかというと、これ先ほど来指導課長が説明しているように、ここのところ他の自治体でこういう事例で自殺の事例が出ているということなので、それを重く受けとめて、今まで取り組んだものを成果としてこれを出したということです。","voiceIndex":136,"id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"意見があったら、ぜひ手を挙げて言っていただきたいと思います、まずね。それで私は、その二つの残念ながらのこの３月と７月ですか、その自殺の件がここに盛り込めなんてことは一言も言っていないですよ。よく聞いていただきたいと思います。したがって、誤解はしていただきたくないというふうに思います。その辺の認識はいかがなんでしょうか。","respondent":"太田指導課長","answer":"ですから、今回特にその事例をピックアップして、近くにいた子どももいますし、そういった子どもたちのことも考えれば、そういった事例を特に用いて、あえて自殺とか、みずから命を絶つとか、危険な行為をするとか、そういったような指導をしなくても。","voiceIndex":138,"id":"exchange-055"},{"speaker":"阿部委員","kind":"提案","question":"一つだけ、やはり気になるのでごめんなさい。小さな提案です。やはりこの手引、ちょっと項目のところで、もし次につくることがあれば、この出席停止に関する要綱や書式の部分は参考のほうに、参考資料にまとめられたほうがよろしいのではないですかね。内容からいくと、これは参考という副資料的な内容だと思いますし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-056"},{"speaker":"阿部委員","kind":"意見","question":"そう来られたら、ごめんなさいね。参考資料３にはチャート出ていますよね。多分、資料のつくり方としては、こうした様式というのは最後に書式集に載せる際は、それは相手がだれであっても一般的なつくり方だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":145,"id":"exchange-057"}]},{"id":"topic-03","title":"のひとり親世帯等への手当および医療費助成の認定基準の拡大","agenda":"のひとり親世帯等への手当および医療費助成の認定基準の拡大","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"済みません。私ちょっと、この辺の申請にかかわる手続に余り詳しくないのでお伺いしたいんですけれども、これは新たに対象者は何らかの手続が必要なんでしょうか。ＤＶなんかは拡大するといっても本人に申請させないと対象にならないのではないですか。ちょっとその申請ということで。","respondent":"梶青少年育成課長","answer":"今までは、こちらに今説明しましたとおり、離婚という具体的事実がないとだめだったわけですけれども、例えば離婚が起こらないまでもＤＶ被害等で、いわゆる地方裁判所のほうに申請をいたしまして、地方裁判所のほうから保護命令が出された場合につきましては。","voiceIndex":152,"id":"exchange-058"},{"speaker":"阿部委員","kind":"質問・要望","question":"そうすると、このＤＶ被害の方がみずからこの一部改正を知って、その申請をしないと、この一部改正の恩恵を受けるといったらいいんですかね、給付が得られなくなるということで、ＤＶ被害の方が、それだけ今でも行政情報を知っていらっしゃるかというのは非常に、できるだけ漏れのないように受給していただきたいなと思うんですが、決して数は多くはないと思うんですけれども。","respondent":"梶青少年育成課長","answer":"先ほどの児童扶養手当のほうにつきましては、国のほうでは手当の施行令の改正を７月の下旬にやりまして、その後は区のほうも実施するようにして、東京都のほうでも７月の下旬なんですが、我々もそれを受けまして、広報は９月１日号となってしまうんですけれども、ホームページ。","voiceIndex":154,"id":"exchange-059"},{"speaker":"阿部委員","kind":"質問","question":"繰り返しになりますけれども、該当者にダイレクトにお知らせする方法というのはないものなんですか。","respondent":"梶青少年育成課長","answer":"そういうところには我々のほうで窓口のほうで注意してまいりたいと思います。","voiceIndex":156,"id":"exchange-060"}]},{"id":"topic-04","title":"の認可保育園の新規開設","agenda":"の認可保育園の新規開設","exchanges":[{"speaker":"南委員","kind":"質問","question":"これ、このブリリア大井町ラビィアンタワーがあって、区にスペースを提供していただいたというふうにちょっと聞いているんですが、要するに公設民営なのか、民設民営なのか、ちょっとそのあたりの考え方、仕分けとしてどういうふうに見たらいいのかということを質問したいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"再開発組合から、品川区に土地および建物の一部の寄附がございました。社会貢献の一環としていただいたものです。そちらのスペースをどういった用途に使うかということを区で検討いたしました結果、認可保育園としての活用を決定したです。形態といたしましては民設民営です。","voiceIndex":163,"id":"exchange-061"},{"speaker":"南委員","kind":"質問","question":"そうすると、この開設に当たって内装をしなきゃいけないわけですから、その辺への補助金というは、先ほどの冒頭の、こちらの視察した保育園等々の関係で見たときに、どういう内容の補助金がどういうふうに使われるのかお聞きします。","respondent":"伊崎待機児童対策担当課長","answer":"ですので、特に施設整備費に対する事業者への負担、区からの補助金は今のところ予定しておりません。","voiceIndex":165,"id":"exchange-062"},{"speaker":"南委員","kind":"確認","question":"最終確認ですけれども、品川区から開設に当たっての家賃要請はあると思うんですけれども、今まで、開設までの補助金というのはなくて、これから運営が始まっていったときに家賃補助という形でなのかな、あとほかにどんなものが補助金としてこれから出るのか、そのあたりをちょっと。","respondent":"伊崎待機児童対策担当課長","answer":"まだ契約はこれからになっております。運営開始後につきましては、本日見ていただいた保育所に対する補助と同等の補助ということになります。","voiceIndex":167,"id":"exchange-063"},{"speaker":"阿部委員","kind":"意見","question":"今のお話の続きなんですけれども、これ床の寄附は区が受けて内装工事で、それを低廉の家賃で貸し付けて家賃補助なしで運営をしていくという。そうすると、例えば共益費とか、あるいは今後の改修等々についても区が持っていくことになりますよね。","respondent":"伊崎待機児童対策担当課長","answer":"その辺は細かいことは経理課のほうでの管轄になってくるんですが、今聞いておりますところでは、共益費は区が家賃補助として最初からもらうという話で、修繕の積み立ては区のほうで行っていくという予定だということを聞いておりますが、契約の詳細までは聞いておりません。","voiceIndex":170,"id":"exchange-064"}]},{"id":"topic-05","title":"の最後となりました。(4)の子育て交流ルームの新規開設","agenda":"の最後となりました。(4)の子育て交流ルームの新規開設","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"済みません。経費のところで開設経費と家賃助成、販売促進経費補助はわかるんだけれども、これはずっと続いていくものなんですか、家賃補助。家賃補助ですね。それから、まあ開設準備経費はあるんだけれども、販売促進経費補助等々。続いていくとなると趣旨が違うような気がするんだけれども、確認だけ。","respondent":"伊崎待機児童対策担当課長","answer":"商店街の空き店舗利用の補助金としましては、３年という年限がありますので、３年間はこちらで補助をいたします。失礼いたしました。1)の開設準備経費と2)の販売促進経費補助は、開設時のみの補助となっております。","voiceIndex":176,"id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4768#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":64234,"voices":183}},{"id":"h24-20120821-14","meetingId":"h24-cm08","date":"2012年8月21日","dateIso":"2012-08-21","committee":"行財政改革特別委員会","time":"午後１時００分～午後５時２４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"旧第一日野小学校跡地の貸付","agenda":"旧第一日野小学校跡地の貸付","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"２回の住民説明会が行われましたが、まず率直に伺いたいことは、説明会を通じ、ＴＯＣへの学校貸付について、住民の理解は得られたと考えているのか伺いたいと思います。品川区は議事録作成のため録音していると冒頭説明がありましたけれども、改めてどの点について住民におわびをしたのか、その認識を確認したいと思います。率直にこういう参加者の思いをどう受けとめているのか、そこを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"３点のご質問かと思います。住民説明会ですね。２回ほど行った中身で、住民の方々の理解を得られるかといったところです。説明会につきましては、今までの経緯等々をご説明させていただきまして、その考え方等をお示しさせていただきました。","voiceIndex":11,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は、理解も得られていないのに、この計画を進める気なのかと、住民理解を得られていないのに、ごり押しするのはやめるべきだと思いますけど、いかがでしょうか。品川区はこれまで繰り返し貸付の条件として具体的な施設計画がどういうものであるかしっかり確認すると、これが前提だと話し、これが示されなければ白紙を含めて検討すると説明がありました。ちなみに、まとめて伺います。","respondent":"日下部企画部長","answer":"ですから、私どもは今回の貸付条件の中で、先ほど課長のほうからご説明をさせていただきました６のその他、その(1)の中で、基本的な建て替え計画のコンセプト、基本的な考え方、これについて区とＴＯＣが基本的に合意をしていると。","voiceIndex":13,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"こういう状態でごり押しするのは間違っていると、白紙に戻すべきだと改めて伺いたいと思います。案文は両者の合意ですから、品川区としてはこの案文で合意したいと示していると、それを示せばいいわけですよ。それが示されないということは、結局何なんだと思いますので、改めて品川区がＴＯＣに提出している案文を、そのものを出すべきだと思いますけれども、いかがでしょうか。それ自体も私自身も疑問。","respondent":"日下部企画部長","answer":"これに沿った形でこの建て替え計画を具体的に進めていきたいと、そういう意味ではやはり地域の願い、それから区としての基本的な考え方、これをベースにした建て替え計画を進めていくという基本的な方向性がはっきりしているわけでありますし、ここに1)から2)。","voiceIndex":15,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"そこをもう一回伺いたい。これは紛争予防条例にそもそも位置づけられているものですから、住民が言っているのは事業説明会なんですね。引き続き継続すべきだと思いますので、改めてここも伺いたい。要するに、ＴＯＣのお客さんの流れをつくって救済したいという計画ではないでしょうか。こんな計画の実効性の担保がどこにあるのか、この点、伺いたいと思います。結局、マンションでもオーケーなのかどうか。","respondent":"日下部企画部長","answer":"説明会については、先ほど申し上げました。今後とも説明会という形はとりませんけれども、しっかりした形で情報の提供はやらせていただきたいというふうに考えております。","voiceIndex":17,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"説明会という形はとれないけど、説明していきますというのはどういう意味ですか。しっかり区の説明責任を果たす意味で、しっかり住民説明会を継続すべきだと私は思いますけれども、改めて伺いたい。先ほど聞きました、マンションでもオーケーなんですか。住民参加を位置づけた検討会の開催、公園や特別養護老人ホームなどの住民要望こそ優先すべきだと思いますので、この貸付には反対です。","respondent":"日下部企画部長","answer":"ただ、私どもこの２回の説明会の中で、それぞれ時間の延長も含めまして、最大限誠意を持って対応させていただいたつもりでもありますし、この説明会をもってすべてが終わりということではなくて、先ほども申し上げましたさまざまな手法、町会回覧等を通して。","voiceIndex":20,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"その気持ちがわからないのかと、私はその点をもう一度伺いたい。そういう計画よりも、実際声が上がっている公園とか、特別養護老人ホームとか、保育園とか、住民要望こそ、みんながなるほどこれだったら、学校がこう変わるんだったら、なるほどこれだったらそうだなと、そう思える計画にすることを優先すべきだと私は思いますけど、最後にいかがでしょうか。","respondent":"日下部企画部長","answer":"ただ、その後は、ある意味での本格貸付、これは議会、それから地域の声もしっかりといただいて、考えていきたい、できるだけ早目に検討を進めたいというふうに思っておりますので、ひとつご理解をいただきたいと思います。","voiceIndex":22,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、説明するかどうかわかりませんけれども、そういう思いはやはり強く言っていただきたいなというのが一つあります。私は建設的にちゃんとこういう議論がされている、声のトーンは確かにわかりませんけれども、しっかりと答えられていて、きっちりと質問に対している回答が出ているわけですから、それによってご理解いただけた感じなのではないかなと思うんですが、その辺はいかがでしょうか。","respondent":"日下部企画部長","answer":"１点目なんですが、確かに第一日野小学校については、学校自体が廃校になってしまったということではなくて、日野中学校の移転した跡に、そのまま存続をしているわけでありますので、そういった意味では、私どもの説明が十分行き届いていない点もあろうかと思いますが。","voiceIndex":24,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、確かに説明会というのは反対者もいれば、いろんな考えの方がいらっしゃるので、感情的になったりという部分もあるかと思うんですけれども、それはやっぱり内容を聞いていると、もっともなお話でもあるし、質問内容でもあるし、それに対して区のほうは淡々とお答えしていくという、説明はいろんな書面を使ったりとかして、これからされるということなので、そこはあまり感情に流されないで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"委員会運営について。区は今回の報告をもって了承されたら進めるとおっしゃっているんですね。この中から１人もこの計画でよしなんていう発言はありません。今１人は終わったけど、結局反対意見を言ったのは私だけで、よいなんて言う人はだれもいないわけですよ。だから、改めて、態度を明らかにして、報告事項ではあるけれども、しっかり採決をとっていただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-009"},{"speaker":"中塚委員","kind":"意見","question":"そう仕切るのであれば、反対を言ったのは私だけです。この計画はすばらしい、進めてほしいなんていうのは、今日の報告を受けてだれも発言はありません。ということは、この委員会の意思として反対だということで、委員長、よろしいんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-010"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、今日はある程度報告事項なので、それがこういう経過で報告されましたということなので、そこでいいとか悪いとか言わないから、全部賛成じゃないんだなんていう問い方を委員がされたり、まちの人に聞いたりするのはおかしいので、そういうことを言うこと自体がまずおかしいと思うので、今日はあくまで報告事項をいただいて、その報告に対して質疑があったならば質疑をするということだけなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-011"}]},{"id":"topic-02","title":"旧西五反田職員待機寮跡地","agenda":"旧西五反田職員待機寮跡地","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"売却の方針は疑問です。区は今理由として、立地条件から費用対効果の面で課題があり、売却としての財産の活用と説明がありましたが、この費用対効果とは具体的に何と何の比較なのかを伺いたい。これが自治体の役割なんでしょうか。こうしたのを見通しても、またこれまでもそう使ってきたことを見ても、やはりこうした住宅支援に充てることこそ必要じゃないかと思いますけれども、いかがでしょうか。","respondent":"平澤経理課長","answer":"そういったところを勘案いたしまして、こちらの施設につきましては、売却により財産として品川区でお金にかえて、別の事業に実施することが、この建物の有効活用であるということを考えた次第です。","voiceIndex":37,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"実際に区が売って、だれが買って、どう使うかはわかりませんけれども、あそこで何かしようと思ったら、周りは住宅ですから、まあ住宅なのかなと、これは相手が決めることですけど。これは何と何ですか。結局、さっきも言いましたけど、壊して建てて新しいものをつくって、そのコストを利用する人に減価償却として出して、もうけようとしているんですか。それが自治体の姿なんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-013"},{"speaker":"須藤委員","kind":"質問・要望","question":"それで、こういった報告をいただいているので、今の質問をしてくると、そのことに対してじゃなくて、また戻せという話なんで、その辺は委員長のほうで十分質問の仕方を整理していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-014"},{"speaker":"中塚委員","kind":"確認","question":"前回の委員会で納得できないことを質問するのを制限するのは不当です。今の発言で、消費税、意見があったことは私も知っていますよ。それが委員会の意思とは確認していません。そういう質問制限は不当だと思いますけれども、いかがでしょうか。納得できないことを質問して何が悪い。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"前回の中身に納得できないから質問して何が悪い。それが議会でしょうが。話し合おうという特別委員会で、前回の中身に納得できない場合、質問して何が悪い。〔「同じ質問したってしようがないだろう」と呼ぶ者あり〕それはあなた方の評価でしょう。私は納得できないから質問している。しかも、費用対効果について答弁がない。それをね、発言を制限するなど、不当だ。訂正してほしい。","respondent":"桑村総務部長","answer":"この費用対効果ですが、立地条件からということで、これまでもご説明したとおり、ここは基本的に耐震をやらなきゃいけないということ、耐震については相当お金がかかるということが１点です。","voiceIndex":44,"id":"exchange-016"},{"speaker":"中塚委員","kind":"提案","question":"費用対効果という言葉は、何かと何かを比べるんですよ。今の説明は、建築にお金がかかるから。違うでしょう。わかります。改築にお金がかかるのは当然なんですよ。問題なのは、何に使うのか、それが地方自治体として必要なのかどうか。私はそうすべきだと提案したわけですけど。〔「また戻ってきちゃったよ」と呼ぶ者あり〕改めて、ここを住宅支援として使うべきだと思いますけど、いかがでしょうか。","respondent":"桑村総務部長","answer":"今の意味で、収入を得る、得ないというようなことで費用対効果を使っているんではなくて、ここの立地条件、擁壁ですとか、あるいは行きどまり道路という意味で、このまま使うにはかなりのお金がかかるので、いわゆる通常の、いわゆる普通に建てられる用地だとか。","voiceIndex":47,"id":"exchange-017"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"前回といい、今回といい、特に第一日野小学校跡地についての報告で、傍聴者が定員を超えている状況があります。特別委員会の日程を考えると、今日であれば、６階の大きい部屋があいておりますので、事前の調整などで委員会室を変更して、傍聴者の要望をかなえてあげる、こうした委員会の取り組みも必要だと思いますので、今後の対応について検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5930#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":28525,"voices":54}},{"id":"h24-20120822-17","meetingId":"h24-cm08","date":"2012年8月22日","dateIso":"2012-08-22","committee":"震災対策特別委員会","time":"午後１時００分～午後３時２２分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、命の危険を守るということから考えると、市街地大火の火災から命を守るというふうなところで、広域避難所にやっぱり避難をするということになると思うんですけれども、そこら辺のところの認識としては、そういう考え方でいいんでしょうか。そこのところ。","respondent":"高山防災計画担当課長","answer":"避難行動というふうに書かれました中には、最も安全な場所への一時的な避難ということとなりますので、こちらのほうは必ずしも広域避難場所のようなオープンな、火災から身を守る一時的な場所にとらわれずに、避難所として指定されている学校のほか、堅固な建物であれば。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そういうときに、市街地大火になったときに、まずは小学校という、どうもそういうイメージがある中で、小学校に避難をして、大火に取り囲まれて、小学校に逃げ込んだ場合、命を守れないと、そういう状況になることは避けなくちゃいけないんじゃないかなと思うんですけど、そこのところの認識というのをお伺いしたいなと思います。","respondent":"高山防災計画担当課長","answer":"１点目につきましては、委員ご指摘のとおり市街地大火ということに関しましては、やはりこれまで東京都が整備してまいりました広域避難場所というのは、一定の輻射熱に対応できるというオープンな場所ですので、そういったものを活用するということについては。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つは、やっぱり避難所そのものの安全性を確保するというところで、周りの不燃化、耐震化という、周りといっても、そこの周りだけをやってもほんとうになかなか難しい部分がありますので、やっぱり不燃化、耐震化というところでは、ぜひとも取り組んでいただいて、避難所そのものの安全性を確保するというところでお願いしたいなというふうに、これは要望させていただきたいと思います。","respondent":"高山防災計画担当課長","answer":"２点ご質問いただきまして、まず１点目の３.３m2の根拠ですが、こちらは上位計画であります東京都の地域防災計画の中で避難所における１人当たりのスペースの標準的なものということで示されているものですので、委員ご指摘のように。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"１,１００人が収容できるということになるんですが、これは１４％ぐらいの避難者の人数ということになっているんですけれども、このパーセンテージというか、避難の収容人数というのは、どう考えられているのかというあたりをお聞かせください。","respondent":"高山防災計画担当課長","answer":"ただ、品川区の地域防災計画ですので、品川区で発生するであろう避難者を品川区内で何とか受け入れたいと、そのような趣旨のものですので、地域によって数字的なものが異なってまいりますが、最終的には品川区内で受け入れが可能なような形での計画と、そのように考えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それともう一つは、やはりこの劣悪な避難所生活を余儀なくされるというのを、ほんとうにもっと人間らしく過ごせるような、そういう体制というのがどうしたらとれるのかということももうちょっと検討することが必要なんじゃないかと思うんですが、今日の新聞でも震災の関連死というのが１,６３２人、今回の震災での関連死というふうなところが発表されていまして、それで。","respondent":"高山防災計画担当課長","answer":"加えまして、この間いろいろと備蓄などの品目なども増やしてまいりまして、少しでもそういった弱者にとって対応できるような形での区としての対応ということも進めてまいりましたところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は去年の委員会の中でもちょっと申し上げたんですけど、どう考えてもやっぱり２人に対して毛布１枚となれば、真冬にそういう震災が起こる場合もあるわけですから、それであれば、ほんとうに暖をとることもできないし、眠ることもできない、よく眠ることができないために、ほんとうに疲労が蓄積していって命まで奪うということにつながっていったというのも、今回の凡例集の中には書かれていたんですけども。","respondent":"高山防災計画担当課長","answer":"学校等の備蓄枚数にばらつきがあるのは、先ほどご説明いたしましたように、実は非常に毛布というのが一番倉庫の中で場所をとるものでございまして、現在の技術でアルミ真空パックなどにすることで、これまでの３分の２程度に収容体積を抑えられるという話は聞いているんですが。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は福島の伊達市に南相馬市から避難をしてきている方の避難所にお伺いして、いろいろとお話を伺ったことがあったんですけど、そこのところも４月末だったんですけど、それぐらい時間がたっているにもかかわらず、体育館にダンボールを敷いて、毛布を２枚敷いているというだけの生活だったんですよね。だから、ほんとうにそれでは疲労が蓄積してくるだろうなという思いがしていたんですね。","respondent":"高山防災計画担当課長","answer":"そんな中で、２階部分までというお話ですが、現在の改修計画の中では、まずは１階部分というお話で聞いておりますので、全校が終わった時点で、その次の段階としてどこまでトイレ機能、震災時のトイレ機能を確保していくかという部分で。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"長くなりましたので、これでとりあえず終わりますけど、排泄、睡眠、それからプライバシー、食事、清潔、そういうふうな基本的なところをしっかりと対応して、そうでなくても１人畳１畳という狭いスペースですので、人間らしい生活が送れるように、そしてまた、そういうところをきちんとやらないとまた感染とかなんかの拡大にもつながっていくということもありますので、ぜひ力を入れて拡大。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-008"},{"speaker":"阿久津委員","kind":"質問","question":"いまだにやはりまちの人から聞かれることが一つありまして、海側の地域の小学校で、非常に海抜の低い小学校があるということで、今回地震発生時の避難の流れということで考え方を整理していただいて、基本的に地震が発生して、津波等が起こる可能性がある場合は、避難所にもちろん行かないということはわかるんですけれども、私が今日調べてきたところだと。","respondent":"高山防災計画担当課長","answer":"例えば１階部分が浸水したということであれば、２階以上の使用が可能であるとかということもありますので、衛生状態を確認した上で、また建物の安全性を確保した上で避難所生活を送る上での機能が２階以上にあるということであれば。","voiceIndex":20,"id":"exchange-009"},{"speaker":"阿久津委員","kind":"質問","question":"それをまたそのときになってから考えるとなった場合に、もちろん今想定を考えられているのかもしれないんですけれども、それは前もって考えておく必要があるんではないのかなというふうに思うんですが、やっぱりまちの人からよく聞かれるので、今防災会議の中で、そのことについてはいろいろ皆さん、有識者の方がいろいろ想定をされて考えられているところですという答えを私もするんですけれども。","respondent":"高山防災計画担当課長","answer":"先ほどご説明の中で申しました１階部分が万が一浸水した場合にということは、ほんとうに最悪の場合のお話でございまして、当然それも例えばしかるべき防疫、消毒などが整えば、また１階部分についての避難所としての使用は十分可能ですし。","voiceIndex":22,"id":"exchange-010"},{"speaker":"阿久津委員","kind":"確認","question":"その点について付随してもう１点、ちょっと細かいことなんですけど、学校避難所の備蓄物資については、こういう施設については１階部分に置いてあると浸水してしまって使えなくなってしまうと思うんですが、逆に２階以上の部分にそういうものを置ける場所があるのか、そこのところだけ確認させてください。","respondent":"高山防災計画担当課長","answer":"実は学校備蓄倉庫の場所につきましてはまちまちでございまして、地下の場所もあるかと思えば、２階の部分もあるとかということで、基本的には学校の理解のもと、余剰のスペースを供出していただいて備蓄倉庫として使っているものについては。","voiceIndex":24,"id":"exchange-011"},{"speaker":"阿久津委員","kind":"確認","question":"品川区の地域防災計画の１５２ページですと、平成１８年度に獣医師会と協定を結んで、動物に対して獣医師等を避難所に派遣するというような取り決めがあるんですが、じゃあ実際に、現実的に飼い主とともに同行してきた動物に対してどういう取り扱いをするのかということで、避難所連絡会議などで対応策を検討していくとあるんですけれども、現状はこういったことが議論をされているのか、されていないのか。","respondent":"高山防災計画担当課長","answer":"獣医師会とは協定を締結しておりまして、けがをした小動物などについての対応については、協定の中で実現していくつもりではありますが、今回の発災などを見ますと、やはり動物についても広域的な受け入れというのも必要だろうというような話も出てまいりますので。","voiceIndex":26,"id":"exchange-012"},{"speaker":"阿久津委員","kind":"質問","question":"今お伺いすると、個別の連絡会議では否定的なご意見が多いと。もちろん人間の命、また避難が優先というのはもちろんだとは思うんですけれども、何度も皆さんも耳にされていると思うんですが、震災のときに避難所でいたたまれなくて車の中で寝泊まりしていた方が、エコノミー症候群で亡くなったりとかということもある。","respondent":"高山防災計画担当課長","answer":"この問題を議論するのも大変重要だと思いますし、また課題と認識しておりますが、この点については引き続き検討はしてまいりたいと考えています。","voiceIndex":28,"id":"exchange-013"},{"speaker":"阿久津委員","kind":"質問","question":"最後に一つだけ。この地域防災計画の中で、地区の防災訓練に東京都獣医師会品川支部も参加し、動物の保護訓練やしつけ教室など、区民に対して積極的に啓発を図っていくという目標が書いてあるんですけれども、この点については実績があるのかどうか、これだけ最後にお伺いしたいと思います。","respondent":"高山防災計画担当課長","answer":"すみません、ちょっと手元に詳細な資料はございませんが、医師会、柔道接骨師会などについては参加していただいている実績があります。申しわけございません。手持ちがございませんので、獣医師会の参加については、確認して後刻ご報告いたしたいと思います。","voiceIndex":30,"id":"exchange-014"},{"speaker":"阿久津委員","kind":"質問・要望","question":"後ほどご報告いただくということで、ありがとうございました。最後に一つだけ意見として。都にしても、区にしても、まず震災が起きたときは、飼っている動物を同行して避難所に避難するというのが前提になっているように読めるので、そこのところを、人間優先はもちろんなんですけれども、このところもぜひ考慮に入れて、今後も検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-015"},{"speaker":"井上委員","kind":"質問","question":"一つ、ちょっと今度は広いところなんですが、都立公園が防災広場として指定をされていると思うんですが、話を聞くところによると、都立公園のトイレは、マンホールとかそういうところは都が設置をしたり、工事はするんですけれども、そこにかかる上物というか、そういうトイレにかけるテント状のものとかは自治体が整備をすることになっていて。","respondent":"高山防災計画担当課長","answer":"２点目の都立公園のトイレの管理という部分ですが、区としましても、マンホールトイレに設置するいわゆる組立式の便槽につきましては、十分な余剰といいますか、余裕を持っておりますので、それについての活用ということは可能というふうに考えております。","voiceIndex":33,"id":"exchange-016"},{"speaker":"井上委員","kind":"質問・要望","question":"都立公園のほうは、またちょっと別の機会にお伺いしたいというふうに思いますので、これはいいんですが、今度は避難所運営について、なかなか今防災訓練の中で、地域によっては防災備蓄が見ることができなかったり、どこにあるのかという、いざ使うときに重立った方たちが指揮してくださるんだというふうに思うんですけれども、区民としては自分が避難をするところに。","respondent":"高山防災計画担当課長","answer":"２点目の現状の障害を持った方のサポートとそれから障害をお持ちということの情報発信という部分での何か避難所連絡会議での話し合いはあるのかといった点につきましては、先ほどのペットの話もそうなんですが、一つ話題ではありますが。","voiceIndex":35,"id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"きれいごとは言っていられないんだろうなというふうに思うんですけれども、そういうところも含めて、実際に、建前は一緒がいいですよと言いながら、そうはいかないというところを、区はどのように方針を明確にしていかれるのか、そこのところが、東日本大震災の経験を皆さんもお聞きになっているでしょうし、障害のある団体の方たちもそれぞれに研究をして。","respondent":"高山防災計画担当課長","answer":"一般的には、やはり避難所が立ち上がってくるのに時間的な差異がありますので、そういったものを踏まえて、受け入れの状況を見据えて、しかるべきタイミングにトリアージをして、移っていただくというのが、避難所があふれるという現状を考えますと。","voiceIndex":37,"id":"exchange-018"},{"speaker":"井上委員","kind":"質問・要望","question":"医療救護所のある指定の学校なんですけれども、区がこれを考えているときに、私たちはこれをどうとらえるかという問題なんですけれども、自分が持病を持っていて、お医者さんがいる学校へ避難したほうが安心だというふうに、病気を持たれている方は思うと思いますけれども、そういう避難の仕方を想定しているのか、指定避難所に行って、移動をサポートするというような形で想定されているのか。","respondent":"高山防災計画担当課長","answer":"それから２点目の医療救護所のある避難所に避難したほうがという、そのような思いはごもっともかとは思いますが、先ほどご説明しましたように、例えば５１カ所すべてに救護所を開設するというのは、医療機関の被災の状況でありますとか、もう一つの問題としては。","voiceIndex":39,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問","question":"１回、指定のところに避難をして、そちらのほうに通うというか、なかなかそういうことが現実的にできないときに、そういう避難所に行かれたときにどういうふうに対応を、来てはいけませんという話にはならないと思いますので、また、指定されたところは道路が不通になっていて行かれなければ違うところを、命を守るためにはいろいろなことがあって。","respondent":"高山防災計画担当課長","answer":"必ずしも区の職員が付き添ってということではなく、やはり避難された方々同士の、一つはルールの中で、力をかしていただける方に関しては、そういった部分での貢献ということも十分可能かと思いますので、そういった地域の方々の力もかりながら。","voiceIndex":41,"id":"exchange-020"},{"speaker":"大沢委員","kind":"意見","question":"井上委員がさらっと済ませちゃったんですけど、今日、所管のいつもの防災まちづくり事業部、あるいは都市環境事業部ということで部長がお二人、それと別に今日はわざわざ健康福祉事業部長が出ていただいて、この中で、先ほど来お話をしました学校の避難所である場合に、なぜ今日ここに教育委員会担当課の方が同席をしていないのか、よく言われています横の連携という区の事業部の中で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-021"},{"speaker":"大沢委員","kind":"質問・要望","question":"ここの中で、学校避難所機能云々とありますけれども、構成委員のところで学校施設管理者、防災区民組織の代表、区職員と並列で書いてありますけど、ここのところもよく避難所会議とか防災訓練をやるときに出てくるけど、どなたに従っていいかわからない、要は教育委員会と所管の防災課の職員が違うふうになっちゃって、連携がとれていないという声を多く聞くんですけれども、そこらあたりは。","respondent":"鈴木防災課長","answer":"現在、計画改訂のために分科会を幾つか立ち上げておりますが、その中で避難所に関する分科会につきましては、ご指摘のとおりまさにかかわるところですので、教育委員会の各課、それと学校代表の校長先生４名に入っていただいて。","voiceIndex":45,"id":"exchange-022"},{"speaker":"沢田委員","kind":"質問","question":"医療体制のことでお伺いしたいんですけども、指定避難所の備蓄物資を見ると、救護所指定校には医療資機材セットということで置いてありますけれども、それ以外には簡単な救急箱が医療ミニセットということで２箱ということなんですけれども、これは地区の医師会や歯科医師会、薬剤師会と連携する中で、救護所にはこういった資材が置いてあるということですけども、以前も何回か話が出ていましたけれども。","respondent":"高山防災計画担当課長","answer":"しかしながら、先ほどのご説明の中で、医療機関との話し合いをこの間複数回に渡って会合を持ったというようなご報告をさせていただきましたが、その中でやはり、発災後３日間、とりわけ急性期については。","voiceIndex":47,"id":"exchange-023"},{"speaker":"向委員","kind":"質問","question":"私からは、避難所運営の３ページ目ですかね、備蓄についてお尋ねしたいんですが、今年度の予算特別委員会のときに同じ会派の同僚議員から質問があった件で、精米協定、今こちらのランニングストック６万１,０００キロということで書いてありますけれども、精米協定とかほかの協定、先ほど動物愛護でも出ましたけれども、全般的に今年の協定の見直しとか進捗状況というのはどうなっているのか。","respondent":"高山防災計画担当課長","answer":"一方で、これまで結んできた内容の見直しというのも順次進めておりまして、近いところですと、例えば医師会との関係との話の中で、やはり新たに検討しておくべき内容はないかというようなことでのお話し合いでありますとか、あるいは既に締結したものとしましては。","voiceIndex":51,"id":"exchange-024"},{"speaker":"向委員","kind":"質問","question":"ちょっとこの数カ月気になっていたので、よくわかりました。ちょっと細かい話で、この精米協定のランニングストック６万１,０００キロですかね、この協定というのは平成３年４月１日に改定がされているんですけれども、この数字というのは約２０年ほど前の数字がそのままなんですが、今後見直しが行われるに当たっては、やっぱりこの数字というのは変わってくる可能性があると考えていいんでしょうか。","respondent":"高山防災計画担当課長","answer":"その意味で、都と区の役割というのもありますので、この６万１,０００キロが多い少ないということのお話はあろうかと思いますが、基本的には区として果たすべき役割の部分については、十分にこの部分については果たしていると、そのような認識でおりますので。","voiceIndex":53,"id":"exchange-025"},{"speaker":"武内委員","kind":"質問","question":"私は避難所となる学校の非構造部材の耐震点検、これはたしか今年度の予算でやることになって、おそらく夏休み等で進めていくのかなと思っていたんですけれども、その辺の、これももしかしたら教育委員会のほうになっちゃうのかもしれないけど、進捗状況というんですかね、体育館とか学校の教室等の非構造部材の点検の進捗状況みたいなのがわかれば、まず教えてもらいたいんですけど。","respondent":"鈴木防災課長","answer":"具体的には、一応今年度１校当たり１６万円を計上しまして、５３校、これは小学校３８校と中学校１５校ですが、基本的に避難所となる学校については、この点検と対応を行うということで聞いております。","voiceIndex":55,"id":"exchange-026"},{"speaker":"武内委員","kind":"意見","question":"わかりました。大事な視点だと思いますので、防災のほうもぜひ随時情報は共有してもらいたい。ハード面で言いますと、避難所生活もちょっと長くなりますと、どうしても暑さ、寒さ対策というのが必要になってくると思うんですけれども、特に体育館ですね、体育館は冷暖房が基本的に入っていないので、そういうときの、例えば寒さ対策、暑さ対策というのは、どういうことを考えていらっしゃいますか。","respondent":"高山防災計画担当課長","answer":"そういった意味で、被害想定などを見ますと、電力が比較的おおむね１週間ぐらいで復旧するというようなお話もありますので、そういったインフラの早期復旧を待って、そういった使用可能な電化製品類の使用を開始すると、そのようなことになろうかとは考えております。","voiceIndex":57,"id":"exchange-027"},{"speaker":"武内委員","kind":"質問","question":"ただ、長期間になってくると、やっぱり特に体育館で寝泊まりするとなると、寒さ、暑さというのはほんとうに大変なことになってくるので、そういう冷風機とか温風機とか、そういうものを随時手配というわけにはいかないんでしょうけど、それこそさっきの災害協定じゃないんですけど、ある程度長くなったときに。","respondent":"高山防災計画担当課長","answer":"救護所の設置ですが、これにつきましては、今日はご説明いたしませんでしたが、各学校避難所には、非常用発電設備がございまして、それが保健室に通電するような形となっております。","voiceIndex":59,"id":"exchange-028"},{"speaker":"武内委員","kind":"質問","question":"そこまでじゃないんだけども、やっぱりある程度普通の学校避難所ではちょっと心配だという方は、やっぱり二、三日ぐらい、もしくは１週間ぐらい救護所があるところに寝泊まりするということも想定されるんでしょうかね。そうなるとさっきの暑さ、寒さ対策もちょっとそういう場所、学校に関してはちょっと考えなきゃいけないんじゃないかなと思うんですけど、その辺のところをまとめてちょっと教えてください。","respondent":"高山防災計画担当課長","answer":"災害時の医療体制というのを考えますと、何も災害拠点病院のような大きな病院ばかりではなく、それ以外の救急病院でありますとか、クリニック等の診療所も被災さえしていなければ、地域医療が継続可能ですので、そういった意味でしかるべき医療機関につないでいくと。","voiceIndex":61,"id":"exchange-029"},{"speaker":"武内委員","kind":"質問","question":"それで、運営のほうなんですけれども、先ほどいろいろ分科会を立ち上げてやっていらっしゃるというお話もあったんですけども、以前に今年の予算特別委員会のときにうちの議員のほうから女性の視点ということで、この間も出てきてお話をしたときに、防災まちづくり事業部長のほうからお答えいただいて、女性の視点とか高齢者の視点とか、もっと言えばさっきの障害者の視点もそうなんでしょうけれども。","respondent":"高山防災計画担当課長","answer":"そうは申しましても、ではそういったところが全く抜け落ちているのかというと、そういうことではなくて、一つには例えば東京都のほうで進んでおります改訂の中にも、そういった視点は盛り込まれておりますし、あるいはこの間、子育てメッセでありますとか。","voiceIndex":63,"id":"exchange-030"},{"speaker":"武内委員","kind":"質問・要望","question":"避難所運営マニュアルの中に、多分学校にわたっているものですかね。そういうものというのは、どれだけ平準化されているかというか、区のほうで各学校のほうでマニュアルをつくってあると思うんですけれども、そういう形で役割分担が各学校でされているんでしょうか。それで、されている中で、それに基づいた役割分担ごとの研修なり訓練なりをされているかどうか、その辺を教えていただきたいと思います。","respondent":"高山防災計画担当課長","answer":"委員ご指摘の、避難所連絡会議の中できちっと役割分担のもと、それぞれの役割を意識を持ってやっているのかというお話ですが、これにつきましては、いわゆる一足飛びにこういったものの意識みたいなものの熟度が高まるということでもなくて、やはり避難所運営訓練でありますとか。","voiceIndex":65,"id":"exchange-031"},{"speaker":"武内委員","kind":"質問","question":"そうしたら、実際は、なかなかそういうマニュアルのひな形みたいなものを区のほうからも多分アドバイスとして出されているけれども、それが各学校によってやっぱりどうしても温度差があるとか、なかなかそこまでほんとうにきっちり決めて、事前に訓練するとかというところまではまだ行っていないという状況なんでしょうかね。","respondent":"高山防災計画担当課長","answer":"詳細については、もちろん今後の話となるわけなんですが、避難所の開設に当たって、当然避難所連絡会議を基礎とする避難所開設ないし運営ということになりますので、そういった中で改めて地域の方々に役割認識などをしていただければと、そのような思いでおりますので。","voiceIndex":67,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"救護所についてお聞きしたいんですが、救護所はこの計画を見ると二、三時間後に設置をするということになっているんですけど、ほんとうにこういう震災になると、診療所とか病院とかなんかにもけが人や病人が殺到するという状況になると思うんですが、そんな中で、すぐに１３カ所の救護所をこういう体制を整えて設置するというのは、かなり大変だと思うんですが。","respondent":"高山防災計画担当課長","answer":"医療救護所の設置ということで、この間話し合ってきている打合せ会の中身としましては、やはり直後の設置というのはなかなか難しいだろうというようなお話を医師会の方々からいただいておりまして、おおむね６時間ぐらいを目途に開設していくというのがやはり現実的だろうと。","voiceIndex":69,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、通常の患者の受け入れの２倍とか、ほんとうに何か、すさまじい数の患者さんが押し寄せてきたというのが本なんかでも出ていますけど、そういうところで、スムーズにそれをやっていくためには、かなり実演からのトリアージですとか、どういうふうに患者さんをどこにどう配置をして、日常と違う非常時の体制をとるかというあたりの訓練をしていたことがスムーズにいったと。","respondent":"高山防災計画担当課長","answer":"そういう意味では、医療関係者が医療救護所に駆けつけられる何がしかの展望があるかというお話がございましたが、これは一つは医師の職業意識の高さというところによるところが大きいので、ご自身が被災されることも鑑みまして。","voiceIndex":71,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、今回の震災で避難所に来るときに、薬を持ってこられなくて、薬を飲むことができない状態というのが続いて、ちょっと大変だという状況というのもあったと思うんですけど、そういうことをどうやって防ぐかというあたりも、ちょっと救護所そのものとは関係ないんですが、災害時の患者の命を守るというところではすごく大事かなと思うんですが。","respondent":"早津健康福祉事業部長","answer":"この３日間というのは、外傷系の治療等がメインになろうかと思います。そういう意味で、救護所にもそういった観点からの医薬品、それから衛生用品というようなものを、今、薬剤師会と連携して検討していただいているところです。","voiceIndex":73,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとあと、ここの災害初動対応マニュアルというところでの救護、これは職員の方々がどういうふうに対応するかというところですが、救護というところで保健衛生部品川保健救護部、荏原保健救護部というところで対応されるということですので、基本的には健康福祉事業部長がそのトップに立って、品川区の医療問題の大変な状況の把握ですとか、医療機関の被災の状況の把握ですとか。","respondent":"早津健康福祉事業部長","answer":"医師会等と連携しながら、そのようにしていくです。","voiceIndex":75,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"３.１１の経験から、外部からのボランティアの受け入れの窓口とか計画等、配置等は何か考えがありましたら教えていただきたいのでお願いします。","respondent":"高山防災計画担当課長","answer":"ボランティアにつきましては、大きく一般ボランティアと、それから専門ボランティアということで、医療関係でありますとか、あるいは建物の応急診断といったいわゆる建築の資格を持つような、そういった専門の方々ということでございまして。","voiceIndex":77,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"ちょっと確認させていただきたいんですけど、それぞれのボランティアの方々を区のほうでまとめて、その配置、医療なら医療と分けて、要するに入ってくるタイミングというのがありますよね。すぐに必要なボランティアと、そうじゃないボランティアとか、そういう意味での計画をちょっとお伺いしたいんですけど、お願いします。","respondent":"高山防災計画担当課長","answer":"それ以外の一般的なボランティアにつきましては、ニーズをはかりまして、しかるべき避難所でありますとか、あるいは物資の仕分けでありますとか、そういった人手を要するというようなところに適正に配置していく、そのような形で考えているところです。","voiceIndex":79,"id":"exchange-038"},{"speaker":"井上委員","kind":"質問・要望","question":"すみません、医療のほうで、ここに平成１９年度の品川区地域防災計画、１６８ページのところに、在宅難病患者について、平常時から保健所・保健センターで患者の把握を行い、必要に応じ医療機関への搬送等を行う体制を確立するということは、平常時の役割としてあるんですけれども、やっぱりほかの部分でも、いざ発災時というよりも、平常時からどう動いていくかというのが重要だというふうに思っていて。","respondent":"坂上品川保健センター所長","answer":"一たん立て終わった方もいらっしゃいますし、これからまた立てるという方もいらっしゃいます。今一たん立て終わったというふうに表現しましたけれども、もちろん新たにまた対応を考えて、よりよい対応ができるように今やっているところです。","voiceIndex":82,"id":"exchange-039"},{"speaker":"井上委員","kind":"質問・要望","question":"この在宅難病患者の皆さんというのは、要支援者であるというふうにとらえられると思うんですね。ほんとうに情報弱者の方たちなので、普通に文書を読んで、目で見て、耳で聞いてという方たちだけではありませんので、そこはほんとうに慎重な配慮、きめ細かな配慮をしていただきたいというふうに思います。これは要望ですので、ぜひしっかりと受けとめていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-040"}]},{"id":"topic-02","title":"津波自主避難マップの作成におけるモデル地区","agenda":"津波自主避難マップの作成におけるモデル地区","exchanges":[{"speaker":"阿久津委員","kind":"確認","question":"確認なんですけれども、真ん中の図のところで、第４・第７都営が図示されているんですが、これは、今回一応中に含まれているのか、どういう考え方なのか、ここのところを教えていただければと思います。","respondent":"武藤河川下水道課長","answer":"具体的には第３回のまち歩きにつきましても、この地域に含まれることから、ご案内をしていく予定にしております。ただし、自治会の状況によりましては、高い建物だったり、そういう状況ですので、そういったことを鑑みていただきながら作成をしていただく予定にしております。","voiceIndex":94,"id":"exchange-041"},{"speaker":"武内委員","kind":"質問","question":"東京都の浸水被害のおそれのあるところで、赤く印をつけていただきました。これはもともと津波の、この間の４月の東京都の発表のときにも、このエリア分けというのは発表されていたのでしょうか。それとも、今回初めてですか。","respondent":"武藤河川下水道課長","answer":"委員ご指摘のように、このシミュレーションの結果、元禄型関東地震の浸水分布、水門開放の場合につきましては、この報告書の中に含まれて既に発表されているものです。","voiceIndex":97,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6416#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":42811,"voices":101}},{"id":"h24-20120827-5","meetingId":"h24-cm08","date":"2012年8月27日","dateIso":"2012-08-27","committee":"総務委員会","time":"午後１時００分～午後４時４７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"事実関係をしっかりとした後、厳正に処分をしていくということなんですが、どのぐらいの期間で状況がわかるのか、または、その後でご報告をいただけるのかどうか、お伺いいたします。","respondent":"堀越人事課長","answer":"ただいま、警察のほうに確認を行っている最中ですので、早急に事実関係が確認できると考えております。処分について、改めて議会のほうにはご報告をさせていただきたいと考えているところです。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"はじめに、(1)の債権の放棄","agenda":"はじめに、(1)の債権の放棄","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"老人保健医療費の返還金の件ですけれども、診療報酬って、医療法人に対してのものだと思うんですが、先にちょっと、全体のお金の流れを教えてください。何で、そういう形で法人に対して残っているのか、そこがわからなかったので。","respondent":"福田会計管理者","answer":"その時点では、既にこれは不正不当請求でございました。ただし、群馬県の監査が行われましたのは、それよりずっと後の平成１９年ですので、私ども、あるいはほかにも５７ぐらいの保健者があったわけですけれども、知る由もないという状況でございました。","voiceIndex":11,"id":"exchange-002"}]},{"id":"topic-03","title":"の平成２４年度都区財政調整交付金当初算定の結果","agenda":"の平成２４年度都区財政調整交付金当初算定の結果","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的な流れを教えていただきたいんですけれども、３ページの当初算定で、品川区が３３８億円余なんですけれども、今年の予算書を見たら、３４０億円と品川区の当初の予算のところで載っていたんですが、結果がこうやって出るまでの考え方というんですか、計算書に載せた考え方とか、それから、ここ数年見ていると、決算のところで、交付額が少し増えているのかなと思うので、その辺の見方。","respondent":"本城企画財政課長","answer":"全体の流れですが、決めるにあたりまして、今回、２月に一度、ご説明をさせていただいたというところは、平成２４年度開始にあたりまして、大体どのぐらい見込まれるかということで、今、ご説明させていただいた中での、冒頭の調整税が大体幾らぐらいになるかとか。","voiceIndex":18,"id":"exchange-003"}]},{"id":"topic-04","title":"の西五反田四丁目、八潮二丁目付近下水道管改修工事請負契約","agenda":"の西五反田四丁目、八潮二丁目付近下水道管改修工事請負契約","exchanges":[{"speaker":"阿久津委員","kind":"質問・要望","question":"今回の下水道の工事では、道路陥没の発生を予防するという側面もあるということで読んだんですが、昨年の東日本大震災以降、陥没に関する事故が増えていると。特に被災地だった仙台とかでも、ものすごい数の陥没が起こっていて、浦安でもやっぱり７００カ所以上の陥没が、調査で判明しているということです。もしわかれば教えていただきたいと思います。","respondent":"平澤経理課長","answer":"本件につきましては、このほかに、次の(4)でご説明いたします、南大井三、四、六丁目付近下水道管の取替え工事が当たるのと同時に、委員ご指摘の耐震化ということになりますと、当委員会でもご報告させていただきました。","voiceIndex":25,"id":"exchange-004"},{"speaker":"阿久津委員","kind":"意見","question":"急にすみませんでした。所管が違うので、道路陥没の調査という話では、できれば区のほうでいろいろと前向きに積極的に予防調査とか、予備調査みたいなものをされて、またそれを東京都に申し上げるような、今のは受託事業ということで、そういう含みはないということなんですけれども、そういったことは必要になってくるのかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域の方から、あちこちやって、どうして続けてやらないのか、どういうところが工事になるのかという質問をよくいただくんです。東京都の調査で、ここが老朽化しているということだと思うんですが、そのような基準というのがあるのでしょうか。ちょっとその辺、わかったら教えていただきたい。この工事自体に、昨今のことなので、耐震化も含まれた工事なのか、その点もあわせて教えてください。","respondent":"平澤経理課長","answer":"基準と申しますと、大体の目安ですが、昭和４０年代から５０年代にかけて敷設された下水道管が主な対象と聞いているところです。","voiceIndex":28,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"今回、西五反田のほうは、確かに老朽化している、年代が相当経っていると思うんですが、八潮のほうは、西五反田に比べると、比較的新しい場所だと思うんですが、今回、そこの下水道管の機能を維持するということで改修工事をするんですが、八潮のほうで何かあったんですか。こちらのほうは、まだ時期的に早いのではないかという感じを受けるんですが、その辺、何かもし情報があったら教えてください。","respondent":"平澤経理課長","answer":"委員ご指摘のとおり、八潮につきましては、昭和５０年代八潮団地の建設に伴いまして敷設されたものですが、人工の埋立地ですので、委員ご指摘のような問題が発生したかとも聞いておりますが、それが全部ということではなくて、総合的に勘案してと聞いているところです。","voiceIndex":30,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"意見","question":"事業として受託ということでわかりますが、この契約に関して、場所の選定、なぜ西五反田と八潮が一緒の契約なのか。逆に、この後ご説明いただきますけれども、南大井も別の契約になりますよね。この契約というのは、どういう判断でなさっているのか。単純に考えれば、西五反田の契約、八潮の契約と考えるのが普通ではないかなと、私は思うんですけれども、この辺、なぜこうなるのか。","respondent":"平澤経理課長","answer":"わかりづらい回答で、大変申しわけないのですけれども、工事全体としては、こちらの切り分けで行わするということになってございまして、地域的には少し遠いんですけれども、工事、工法等勘案したうえで決定しているということを聞いております。","voiceIndex":32,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"あまり納得いかないですね。例えば、南大井は近いなら近いでこれがひとつ、理由なんですけれども、西五反田の工事と八潮の工事を同時にやるのか、別々にやるかによって、これを全く別々にやったら、二つの契約でできるのではないかと、私は思ったんですけれども、そこら辺を、もう１回ちょっとお願いします。","respondent":"平澤経理課長","answer":"工事につきまして、例えば内面被覆工事とか、大変難しい項目が入ってあります。こちらの工事ができる業者数というのが、下水道のＡというところ、またはＢというところで、区内業者に限りますと８事業所しかございません。","voiceIndex":34,"id":"exchange-009"}]},{"id":"topic-05","title":"の南大井三、四、六丁目付近下水道管改修工事請負契約","agenda":"の南大井三、四、六丁目付近下水道管改修工事請負契約","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"基本的なところを教えていただきたいんですけれども、前段にもありますけれども、７ページで言えば、予定価格というのが必ず書いてありますけれども、そもそもこの予定価格を算出するには、どのようなものを根拠として算出をされているのか。この予定価格というのは、区の中で契約を設定するうえで示されているのか、それとも、業者にも示されているのか。その２点を、まず教えていただきたいんです。","respondent":"平澤経理課長","answer":"したがいまして、予定価格を出させていただかないと、その事業者がそういった資格があるかどうかというのがわからないということになります。予定価格につきましては、談合防止とか、そういった意味も含めまして、事前に公表させていただいているところです。","voiceIndex":41,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、都の積算単価ということで算出根拠が出ているということなんですけれども、入札をかけた方たちに、どのような方法で周知をされているのか、もう１回ちょっと具体的に教えていただきたいんです。","respondent":"平澤経理課長","answer":"そのうえで、この案件につきましては、電子入札ということになってありますので、よくある入札室の前でたくさんの人が集まっているとか、そういうことではなくて、電子上の入札をするということになります。ですから、業者が一堂に会するということはございません。","voiceIndex":43,"id":"exchange-011"}]},{"id":"topic-06","title":"の商店街電線類地中化柱体設置工事（戸越銀座地区）その４請負契約","agenda":"の商店街電線類地中化柱体設置工事（戸越銀座地区）その４請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"電線類地中化工事というのは、いろいろな業者がかかわって仕事がシェアできるといって、大変有効な事業と聞いているんですが、今回は、柱体ということで、これは商店街の街路灯と一体化するんですか。それから、本契約はこの部分なんですが、この前後というのがよくわからないので、でき上がるまで、業者とどのような契約が結ばれるのか、ちょっとその全体的なところを教えてください。","respondent":"平澤経理課長","answer":"その後、電線の張り替えを行いまして、あわせて街路灯をこちら側に敷設しまして、最終的に、現在ある柱を、街路灯も含めてなんですけれども、それを引き抜きまして、路面を景観工事をして終わるです。","voiceIndex":50,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"随分いろいろな工程があるんだなというところですけれども、そういったところで、今回の柱体を立てるところは、かなり大きな業者というか、東京支店とか、品川営業所というところなんですが、こういった電線の地中化においては、この工事以外のところでは、区内のもう少し小さい業者でも請け負っていかれるのかどうか、ちょっとその辺を教えてください。","respondent":"平澤経理課長","answer":"こちらの工事につきまして、今回は１８４ｍの地域なんですけれども、これは第３工区といいます。全体で五つの工区がございまして、総延長で１,１８０ｍになります。","voiceIndex":52,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この費用の負担はどっちなんですか。普通の商店街でやると、街路灯は商店街の負担がありますよね。その点についてどうなるのかというのが１点。それから、これは第３工区で、まだこれから進めていくときに、やはり同じように柱体が立ったときに、商店街の負担というのがどうなってくるのか。各商店街で、街路灯って結構変えているのがある中で、それはどうするのかというのも教えてください。","respondent":"平澤経理課長、日下部企画部長","answer":"こちらの工事は、先ほどご説明いたしましたとおり、ほぼ５工程ぐらいの形に分かれているところです。商店街の負担につきましては、申しわけございません、ちょっと確認したうえで回答させていただきたいと思います。ちょっと大ざっぱな説明で申しわけないんですが、そういう形で、商店街の街路灯の更新も地中化の事業の中に含める形で、事業として進めていく。そのような形になっているというふうに、私ども理解しております。","voiceIndex":54,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"意見","question":"街路灯は、当然、都の補助金とか、商店街からあるのはわかるんですが、それを入れたうえで、これを一体工事にすると、契約がおかしくならないかという気がするんですけれども。商店街の街路灯の補助金って、当然ありますよね。それも乗せてここに入ってしまうと、この契約自体がいいのかという気がするんですけれども。","respondent":"日下部企画部長","answer":"すみません、私の発言が要領を得てなくて、大変申しわけございませんでした。ちょっとその辺の事実関係は、改めて確認をします。","voiceIndex":57,"id":"exchange-015"},{"speaker":"石田（慎）委員","kind":"質問","question":"以前、震災後に、たしか工期が少しおくれたような話を聞いていたような気がするんですけれども、全体的な工期は、その後どうなのか、そこだけお伺いしたいと思うんですが、よろしくお願いします。","respondent":"平澤経理課長","answer":"当初、地元にご説明をしたときの工期につきましては、こちらの第３工区のこの工事につきましては、大体６月から１１月までぐらいを予定したところです。","voiceIndex":61,"id":"exchange-016"}]},{"id":"topic-07","title":"の立会小学校擁壁改修工事請負契約","agenda":"の立会小学校擁壁改修工事請負契約","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"先ほど、予定価格等々につきましては、契約案件については、(3)から(6)まで各々あるわけですけれども、この中で、先ほど、経理課長もおっしゃられていたように、談合防止ということでお話をいただきましたし、それに対する行政側の防止策というのも伺いました。これについて、どのようにお考えになって、どのように分析をされているのか、教えていただきたいと思います。","respondent":"平澤経理課長","answer":"本事業につきましても、予定価格は公表していますので、見積りをオーバーしたところにつきましては、辞退ということになるわけでございまして、本件につきましても、電子入札の入札をしています。","voiceIndex":68,"id":"exchange-017"},{"speaker":"大沢委員","kind":"質問","question":"工事価格の高騰ということが、今、経理課長の説明からわかったわけなんですけれども、その要素を入れたにしても、やはり業者である以上、入札にかかわった以上、ましてや予定価格が出されているわけですから、自然な形として何らかの形で数字があり、また選定作業が、この件を除いた他のものと同様に行われるのが自然だと思うんですけれども、そこのところを、どのようにお考えになっていますか。","respondent":"平澤経理課長","answer":"その中身は、先ほど、ご説明いたしましたとおり、工事検討監督員の確保が難しかったとか、そういうことの理由になってございまして、そういったところを会社都合とかといったことになっておりますので、今回につきましては、幸い１社が入れていただいたということで。","voiceIndex":70,"id":"exchange-018"},{"speaker":"阿久津委員","kind":"確認","question":"１９ページの図なんですが、一応確認で、擁壁が撤去されて、新設をされると、この図で、私の見方だと、歩道上空地が設置されて、歩道が２倍ぐらいになるということで、木の芽坂のここのところはほんとうに道が狭かったので、非常にありがたいと思っています。ごめんなさい、これはもしかしたら所管が違うかもわからないですけど。","respondent":"平澤経理課長","answer":"委員ご指摘のとおり、今までは大体１ｍぐらいしか歩道がなかったところで、それが１ｍぐらい擁壁が奥に引っ込むということで、道路法上でいえば歩道ではないんですけれども、空地ができるので。","voiceIndex":73,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"１９ページと２０ページの図を見てみると、高さが結構高いんですけれども、これは両方工事の中身の違うということなんですけれども、耐震性というのは、どのように見て補強されるのか、ちょっとわかったら教えてください。","respondent":"平澤経理課長","answer":"はじめに、工法が違うというところからご説明申し上げます。坂の上のほうなんですけれども、建物が非常に近くまでございまして、こちらに逆Ｔ字型の擁壁を建設することができなくて、そのためにアンカーを打ち込んで、それを担保するということになります。","voiceIndex":75,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"建物ではないので、耐震の基準はないけれども、大丈夫だと、終わりのほうはそうなんですけれども、どのぐらいの地震まで耐えられるとか、そういうところはきちんとしたものはあるのでしょうか。ちょっとその辺をお願いします。","respondent":"平澤経理課長","answer":"先ほどもご説明しましたとおり、宅地造成等規制法施行令というのがございまして、そちらに基づく構造基準というのがあります。その構造基準に適したものをつくっていくということで、当然、耐震性はこれで担保されるです。","voiceIndex":77,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"先ほど、ほかの委員からもあったんですが、今回の入札に関しては、１回だけで終わったんでしょうか。１回だけの入札で終わったということなんでしょうか。","respondent":"平澤経理課長","answer":"ですので、このときに辞退があって、または１回で入札が行われて、この予算内に収まったです。予定価格が公表されておりますので、それ以上のものについては、当然入札がないわけですので、こういうことになっているということで、随意契約ではございません。","voiceIndex":79,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問・要望","question":"辞退ということは、もう価格が全然合わないのかと、そもそもそういうことにも誤解をされかねないので、今後、その辺、やはり、１回でだめならもう１回やってみるとか、これで決まったということなので、資材が上がったとか、人件費が上がったということで、またスライドして、金額が途中で補正で増えるとか、そういうことがあっては困るので、今までも適正にやっていると思うんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-023"},{"speaker":"石田（慎）委員","kind":"質問","question":"予定価格を算定する方式があると思うんですが、それは、先ほどの質問の答弁の中にも、いろいろ公表したりとかいう理由があるのかなという中で、算定方式がそもそもなかなか時代の流れに合わないときがあるのではないかと思うんです。この算定方式は、どのように決定をするのか。例えば、何年かごとに見直しがあるのか、その辺の方式の仕組みというか、そこをちょっと教えていただければと思います。","respondent":"平澤経理課長","answer":"したがいまして、算定方式が時代に合わないということはないのかなという気がいたしますけれども、この件につきましては、先ほどもご説明いたしましたとおり、建築と土木の相まった、ちょっと難しい工事だったというところで。","voiceIndex":82,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最終的に、これは区内の業者ですけれども、 １社あったからいいけれども、この業者にしたって、果たしてこの金額で折り合いがついているのかどうか。電子入札ですから、当然、どこが応札しているか、事業者同士でわからないでしょうけれども、うまく１社あったからこれは契約に至りましたけれども、出てこなかったときに、契約が不成立になる可能性が非常に大きなケースですよね。","respondent":"桑村総務部長","answer":"それとも、先ほどご説明したとおり、非常に長い期間で、その業種が建築業者を選んでいますが、土木系の工事がかなり多いものですので、これだけに限ったものなのか、少し分析をさせていただいて。","voiceIndex":84,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"このケースは、今はたしか２割上がったという話で、これがまだどうなるのかわからない中で、なるべくなくなら、この金額を超えない形でやっていただきたいというのが一つ要望です。これが通学路になっているでしょうし、安全性を考えたときに、非常に危険だと思いますので、その辺、十分に対応はできるということでよろしいのでしょうか。万が一の場合ということを、ちょっと確認だけお願いします。","respondent":"平澤経理課長","answer":"ちょっとそういった関係があって、工期が長くなってしまっているです。委員ご指摘のとおり、安全には十分に注意してまいります。","voiceIndex":86,"id":"exchange-026"}]},{"id":"topic-08","title":"の平成２４年８月２日執行、東京海区漁業調整委員会委員選挙の結果","agenda":"の平成２４年８月２日執行、東京海区漁業調整委員会委員選挙の結果","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"３のところに、選挙人名簿登録者数が３３人とありますけれども、品川区には、この資格を有した方が何人ぐらいいらして、どういった業種の方がいらっしゃるのか、ちょっと知りたいと思いました。それから、裏面の当選人一覧で、４の北品川の方がいらっしゃいますけれども、この方はどういったお仕事をされているのか、わかったら教えていただきたいんです。","respondent":"諸岡選挙管理委員会事務局長","answer":"品川区の選挙区内で３３名ですが、１８の自治体が東京海区の中にあります。そのうち品川区の選挙管理委員会が所管する中では３３名ということでございまして、全体で申しますと、２,１４９人です。","voiceIndex":94,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"今、漁民の方たちの意見を、という話があったので、そういうところで取り上げられるような場所なのかどうか、もしわかったら教えてください。","respondent":"諸岡選挙管理委員会事務局長","answer":"この委員会のその都度の議題については、ホームページ等のインターネットでも公表されておりますけれども、私はざあっとしか見ておりませんが、見た範囲では、そういうような議題はなかったと記憶しております。","voiceIndex":96,"id":"exchange-028"}]},{"id":"topic-09","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"説明は大体わかっていると思いますけれども、特別区競馬組合関係について、うちは今、管理者が区長になっていらっしゃいますけれども、行政側として、２３区の間で、競馬組合とか、大井競馬についての話し合いとか、何かそういうチャンスはあるものなんですか。例えば、区長等はわかるんですけれども、課長、部長というレベルでは、何かそういう話があるのか。","respondent":"武内総務課長","answer":"こちらの図にありますとおり、特別区が総務省から開催の許可をもらっていまして、それで、特別区競馬組合というのを組織しているんですけれども、そこの役員は、それぞれ２３区の区長がなっているということですので、その辺は、私ども総務部長とか総務課長が、直接、競馬組合と。","voiceIndex":105,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"確認","question":"特別区競馬組合とではなくて、２３区の中でというつもりだったんです。というのは何かというと、さっき説明だと２３区のほうに株式配当金が出ていますよね。品川区なんかは競馬組合に預けてしまっている。だけど、２３区のうち３区はまだ、区が持っている。それはもう当然、特別区競馬組合の中でも話はしておりますけれども、行政側のほうからも話をしておくべきではないかということで、確認をしたいんです。","respondent":"桑村総務部長","answer":"これは、区長等の指示のもと、副区長中心に区長会等で、３区に対して何からの対応をして、そのような形で、特別区競馬組合が全区の株式を持って、そのことをもって東京都、ないしあるいは、東京都競馬株式会社にあたるというふうにやっているところです。","voiceIndex":107,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ、お願いしたいと思います。ことに東京都に対しても、２３区の要望をしているのに、もとのところにいろいろ問題があると思うので、そこら辺はぜひ、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1922#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":28955,"voices":112}},{"id":"h24-20120921-4","meetingId":"h24-c-settlement","date":"2012年9月21日","dateIso":"2012-09-21","committee":"決算特別委員会","time":"午後４時１０分～午後４時１６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1354#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":1901,"voices":16}},{"id":"h24-20120924-6","meetingId":"h24-cm09","date":"2012年9月24日","dateIso":"2012-09-24","committee":"区民委員会","time":"午前１０時００分～午後２時３１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)の第６０号議案、品川区暴力団排除条例の一部を改正する条例","agenda":"はじめに、(1)の第６０号議案、品川区暴力団排除条例の一部を改正する条例","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"行政対象暴力というのは具体的にどういうことか教えていただきたいのですが。","respondent":"中川原地域振興事業部長","answer":"この法第９条にいう暴力要求行為というのは民間の事業者に対するものを含めて２８項目あるのです。そのうち、行政に対して契約締結や施設利用を要求する行為を挙げているものです。","voiceIndex":8,"id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"細かい聞き方になるのですけれども、いわゆる一般区民もあると思うのですが、役所に対してクレームってあるではないですか。クレーム類について暴力団がしてくる可能性もあるわけではないですか。もしかしたらこじつけて言ってくるのかもしれないし、そういうのもいわゆるこの行政対象暴力と考えるのか教えてください。","respondent":"中川原地域振興事業部長","answer":"特に暴力団については国等の動きもありまして、区として毅然とした態度で臨むということで考えているところです。","voiceIndex":10,"id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"そうすると、区の職員はいわゆる暴力団から行政対象暴力等があった場合には守られていると思うのですけれども、私たち議員は行政の仕事を監督または指導というのを両輪として働いているわけですけれども、議員に対して行政暴力という形のもので守られるシステムというのも役人と同じぐらいに考えていてよろしいのでしょうか。","respondent":"中川原地域振興事業部長","answer":"守られるというのは、この前の本条例のときにも担当課長から説明しましたが、本来は警察と一緒になってこういったことについて行われるものについてはすべて守るという前提です。","voiceIndex":12,"id":"exchange-003"},{"speaker":"藤原委員","kind":"確認","question":"最後に、担当課長が今休んでいるので、直接お伺いできないのですけれども、この条例が前回出たときに担当課長のところでそういう意味で区民と協力していくから、区民からの相談事とかはちゃんとしたポジションが担当課長のところが中心になって、そういうシステムをつくっていくという形でおっしゃっていたのですけれども、そのシステムに関しては、施行の後も、１０月ぐらいからやるわけですから。","respondent":"中川原地域振興事業部長","answer":"警察と専門機関対応になりますので、そこは何といいましょうか、この間説明するときに誤解がちょっとあったかもしれないのですけれども、そこはよろしくお願いしたいと思います。","voiceIndex":14,"id":"exchange-004"},{"speaker":"山内委員","kind":"確認","question":"確認なのですけれども、条例があることで、いわゆる罰することができる、いわゆる警察対応になって、例えば、何かあったときに加害者が警察に逮捕される。そういったときに法律にかかわることになったときは、条例があるからこの人を、何というのですか、裁判というか、そういったときに、その条例にのっとってこの人を裁くことができるというための条例ということでいいわけですか。","respondent":"中川原地域振興事業部長","answer":"前回もご説明したと思うのですが、法律でまずこういうことは暴力団に対してしてはいけないという規制行為を定めていまして、罰則も法律のほうで詳しく、こういうことをしたら罰金とか懲役というのは決まっています。","voiceIndex":16,"id":"exchange-005"},{"speaker":"山内委員","kind":"質問","question":"ということは、ある意味それというのは抑止力のための何かそういう声というか、区からの声というような捉え方でいいのか。そういうことで暴力団にこういうことをしてはいけないという、さっき言ったような抑止力の意味でのそういう条例ということで考えていいのですか。","respondent":"中川原地域振興事業部長","answer":"私どもの条例では、例えば、公の施設を暴力団の資金源になるような会合で使わせることはしませんとか、区の契約は暴力団を相手としたものはやりませんとか、何といいましょうか、暴力団が資金源とするようなものを許さないということなので。","voiceIndex":18,"id":"exchange-006"},{"speaker":"山内委員","kind":"意見","question":"よくニュースとかを見ていると、東京都迷惑防止条例というので、誰々が逮捕されたというのを、特に痴漢とかそういうのでよく見ることがあるんです。例えば、これから考えたときに、品川区独自の条例、２３区自治体の条例でそういった影響力を与えるような、そういった流れになることは今後考えられますか。","respondent":"中川原地域振興事業部長","answer":"条例でできないということはないのですが、法律、東京都の条例、区の条例というのが全体的に暴力団に対してこうしていきましょうということで、この条例にも書いてあるのですけれども、そういった暴力団排除活動の気運が醸成されることを狙いとしています。","voiceIndex":20,"id":"exchange-007"},{"speaker":"山内委員","kind":"意見","question":"それはわかるのだけれども、ということは、例えば、こういうのって、考え方一つなのだけれども、条例を定めたから、では、どうこうという、行政のサービスを受けられないですよという、そういった形ではこういった縛りがあるから、暴力団の方は行政に対するサービスは受けることができないとか、そういうことは言えるのかもしれないけれども、何というのだろう。","respondent":"中川原地域振興事業部長","answer":"区としてはやりませんから。施設も貸しませんし、家族葬は別ですけれども、葬祭場のお葬式も断りますし、そういうことをすると、向こうが何かを言ってきたときには警視庁と連携して、警察権力が守りますので、それは抑止力という意味では今の条例でも十分に対応できると思います。","voiceIndex":22,"id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"条例改正の理由の中で説明があるのですけれども、金融機関が１２号で、宅建が１５号で、そのところに「等」とあるのですけれども、ほかに具体的にこれ以外の等のところを説明していただきたいのですけれども。","respondent":"中川原地域振興事業部長","answer":"もう一つが入札業者に対する入札辞退等要求で、いろいろな民間の事業者に対して行われるであろう経済活動の場面を想定しています。","voiceIndex":25,"id":"exchange-009"},{"speaker":"本多委員","kind":"質問","question":"強化したということはわかりました。名義貸しとか、あと、委任状に委任して取引をしてしまうとか、そういったことへ対する防止というのですか、チェックというか、その辺はどういうふうになるのでしょうか。","respondent":"中川原地域振興事業部長","answer":"私たちも会場を借りに来たときに、そのときにはわからないかもしれないのですが、その後いろいろな情報が入ってきて、途中で実施日までにわかった場合は、その時点で断るというような、これも警視庁と連携して、情報収集に努めていくということで聞いております。","voiceIndex":27,"id":"exchange-010"},{"speaker":"武内委員","kind":"質問","question":"改正の中身についてはわかりましたのですけれども、関連して、ちょうど山内委員の質問の中にあったのですが、区の施設を今まで過去の例でそういった暴力団関係の資金源になるような会合で使わせてほしいみたいな申し込みというのか、そういうのがあったとか、もしくは使われたとか、そういうケースでは。","respondent":"中川原地域振興事業部長","answer":"きゅりあんのコンサートで１回そのような例があったと聞いておりますが、あと、区の施設ではなくて、臨海斎場でやはり葬儀が、葬儀の場が多いのですけれども、そういった事例があったと聞いております。","voiceIndex":30,"id":"exchange-011"},{"speaker":"井上副委員長","kind":"質問","question":"そのことについて、やっぱり対策すべきだと思うのですが、どうでしょうか。","respondent":"中川原地域振興事業部長","answer":"区の生活安全担当もここに大きく問い合わせ先となっていますので、問い合わせのレベルでしたならば、ここが責任の所在を明らかにしていますが、区役所に一本化ということは、この事案については非常に緊急の場合は夜だったり、例えば、課長がいない場合も想定されますので。","voiceIndex":35,"id":"exchange-012"},{"speaker":"井上副委員長","kind":"質問・要望","question":"そのときに、内容のお問い合わせとかではなくて、ここに条例でこういう形で定めたのであれば、そこは連絡をしたときに、何か誰かに伝わってどうにか置かれてしまったりとかならないように、そこについては区のほうの体制として、きちんと整えておくべきではないですかということなのです。この根拠で貸さないのだということは理解するのですね。そこはしっかりともう１回検討していただきたい。","respondent":"中川原地域振興事業部長","answer":"そういうことであれば、地域活動課の生活安全担当が窓口として対応いたします。","voiceIndex":37,"id":"exchange-013"}]},{"id":"topic-02","title":"の第７３号議案、指定管理者の指定","agenda":"の第７３号議案、指定管理者の指定","exchanges":[{"speaker":"武内委員","kind":"質問","question":"大体ここはいいのかなと。だけれども、やっぱり本来の趣旨とすれば、その中でもやっぱりあえてそのほかのところも含めて一緒に競わせようみたいな考え、選考委員会の中でそういう議論がされたのかどうか、その辺はどうなのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"ですから、選定委員会においても、民間という言葉も出ましたけれども、施設のあり方について検討を行ったところ、品川文化振興事業団というような特命となったところです。","voiceIndex":51,"id":"exchange-014"},{"speaker":"武内委員","kind":"意見","question":"わかりました。文化振興事業団自体は評価しているので、それをどうこう言うつもりはないのですけれどもね。それで、結果がよければそれでいいのです。ただ、本来の指定管理者の趣旨という部分からすると、ちょっとそこがすっきりしないのですね。その辺がどうなっているのか。","respondent":"安藤文化スポーツ振興課長","answer":"我々、地域振興事業部、主管の部としましても、とりあえず、コンペにするか、それからまた、特命にするかということも検討というか、話したところではあります。","voiceIndex":53,"id":"exchange-015"},{"speaker":"山内委員","kind":"質問","question":"今、区と密接な関係というのはちょっと引っかかるのですよね。やっぱり、施設を使うのは区民であり、お客さんがいるわけですよ。だけれども、あのままずっといってしまうのかなというと、それははっきり言って心配というか、そういう思いがあるのですよね。だから、それって区に目を向けているのではなくて、やっぱり使う利用者に目を向けてほしいのですよ。どうでしょうかね。","respondent":"安藤文化スポーツ振興課長","answer":"利用者にとっては、ここが文化やスポーツの発信と、また、コミュニティの活動の拠点となるというようなことで、地域の文化芸術を盛り上げるような形で、文化振興事業団というものが区の行政方針に従った区民の盛り上がりというのですか、つながりというのですか。","voiceIndex":55,"id":"exchange-016"},{"speaker":"山内委員","kind":"質問","question":"今、防災という話が出ました。それはわかりました。でも、それは、民間に委託しても、それは民間会社が区と連携をすればいい話であって、何かあったときどうしたらいいのですか。そういったことも考えると、あそこはどうやって多くの利用者に使っていただくかということは、ある意味、今文化振興事業団がきゅりあんを運営しているやり方では私はいけないと思う。その辺はどうですか。","respondent":"安藤文化スポーツ振興課長","answer":"文化振興事業団からの提案を受けて、説明を聞いたときに、文化振興事業団からも新たな展開方法として、今現在文化振興事業団も徐々に進めていますけれども、品川区の商店街連合会と連携したマイスター店講座シリーズとか、そういうものを展開をしています。","voiceIndex":57,"id":"exchange-017"},{"speaker":"山内委員","kind":"提案","question":"そういう提案があるということであれば、ほかの提案も考えられると思う。それはそれでいいですけれども、今後のことを考えたときに、ある意味、出来レースではないけれども、そういった見方をされないような、これからそういった形でのどういうところに委託をするのかといった考え方もこれからはやっぱり役所も持っていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いしますけれども、指定管理者の制度を導入した理由というのを教えていただけますか。","respondent":"安藤文化スポーツ振興課長","answer":"それからもう一つは、今、区も自治体も経費の削減、低減と申しましょうか、その２点があると思います。","voiceIndex":61,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"そういう意味において、やはり、公募をしないのはいろいろな理由はあると思うのですけれども、やっぱりどうしてかなと思いますよね。だから、この資料を見たとき、いつもみたいにここはこうでああでと出ていないというのはすぐ思ったのですけれども、それが１点です。改めてこれも聞きますけれども、この文化振興事業団の理事長の中尾根さんというのはどういう経歴の理事長ですか。","respondent":"安藤文化スポーツ振興課長","answer":"中尾根理事長ですけれども、区を退職した理事者として今は、現在は理事長をしている方です。","voiceIndex":63,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"そういう意味で区と密接という考え方はあるのかということと、文化振興事業団にいわゆる退職の方も含めて、再任用も含めてどのくらい行かれているのかというのも、大体でいいですよ。大体の人数とか、そういう形で教えていただけますか。","respondent":"安藤文化スポーツ振興課長","answer":"１点目の理事長とということではなくて、今回の指定管理者も文化振興事業団、その組織としてそこを指定管理者としたです。それから第２点目の区を退職したＯＢについて、まず、派遣の職員として今現在は課長を含めて３名が派遣しています。","voiceIndex":65,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"公ですよね。私たちは公でやっているわけですよね。だったら、公募をかけてどこもなかったのでというならまだですけれども、公募もかけないでここに決めたということは一番最初の根本の指定管理者の制度を入れたときの目的から外れているわけではないですか。指定管理者というのを独自に指定するという制度ではないではないですか。だって、今後もあるではないですか。その辺についてはどういう考えなのか。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、今回区民芸術祭をやっていく中で、非常に文化振興事業団とは密接な関係にあって、地域のにぎわいに通じていくというところを我々も非常に重視していたところです。ですから今回、５年間ではありますけれども、特命として候補者として指定させていただいたです。","voiceIndex":67,"id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"今後はどうするのですかというのは答えていただきたいのと、あと、課長が一生懸命熱く語ってくれると、課長が文化振興事業団の営業をやっているように思えてしまうのですよね。区民の立場でこうだああだではなくて、こんなにいいのです、こんなにいいのですと勧めているように思うのですけれども、今後、また、特命でやっていくのか、それとも次は公募も考えてやる方針、考えはありますよというのか。","respondent":"安藤文化スポーツ振興課長","answer":"とりあえず、今回５年間やらせていただきまして、それで５年間の中で検証します。そんな中で議員がおっしゃったような民間も含めて検討していきたいと思います。","voiceIndex":69,"id":"exchange-023"},{"speaker":"大倉委員","kind":"質問・要望","question":"１点なのですが、このただし書きに特別な理由がある場合にというところが品川区のそういった施設でどのくらいあるのかというのをちょっと教えていただきたいと思うのですが。","respondent":"安藤文化スポーツ振興課長","answer":"そうしますと、うちの所管で言いますと、きゅりあん、総合区民会館、そしてもう一つが私どもの主管であります公益財団法人品川区スポーツ協会が管理する総合体育館の区立体育館の二つです。","voiceIndex":72,"id":"exchange-024"},{"speaker":"大倉委員","kind":"確認","question":"確認なのですけれども、荏原平塚総合区民会館で三つ目ということになっているのですね。","respondent":"安藤文化スポーツ振興課長","answer":"そのとおりです。","voiceIndex":74,"id":"exchange-025"},{"speaker":"大倉委員","kind":"質問","question":"これからそういった指定管理者の指定についてはそういった特別な理由というのは今のところ、この選定委員会にかけて、これは特別な理由があると認められたときに、また、そういった場合は文化振興事業団とかになっていくという感じになのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"そういう施設を今後どういう予定だというようなご質問の趣旨だと受けとめさせていただいてよろしいでしょうか。今の段階では、文化センター等は直営でやってあります。今のところ、そういうような考え方は一切持ってございません。今後検討します。","voiceIndex":76,"id":"exchange-026"},{"speaker":"本多委員","kind":"質問","question":"この文化振興事業団はまさに適当なのですが、私は決めるところも競い合いがないということなので、ここの選定委員会を何というのですか、刺激したほうがいいと思うのです。そのことだけちょっとお聞かせください。","respondent":"安藤文化スポーツ振興課長","answer":"今回このような形でさせていただきましたけれども、今後、きゅりあんも総合体育館もあります。そんな中で、今後、選定委員会のメンバーについては改めて構成メンバーを構成させていただきたいと思います。","voiceIndex":79,"id":"exchange-027"},{"speaker":"井上副委員長","kind":"質問・要望","question":"大方がこの指定管理者制度という目的本来の選考がされなかったということの意見だったと思います。先ほど、民間で大丈夫かということを真っ先におっしゃられたのですけれども、大丈夫かどうかを決めるのがこの指定管理者の選考委員会でなければいけないのに、最初からその考えを排除したやり方については５年後にはしっかりと見直していただきたいと思いますが、いかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"委員ご指摘のとおりで、今後５年間、我々も十分に検証をしていく中で、次回については公募を含めて検討させていただきたいと思います。","voiceIndex":82,"id":"exchange-028"},{"speaker":"井上副委員長","kind":"質問・要望","question":"５年間の検証は問題にしていないのですよ。選考について変えてくださいということだから、５年間を検証してしまうと、実績がありますねということにまたなってしまうので、そこではないので、そこはしっかりと押さえていただきたいと思います。それから、１ページのところで指定対象事業者から提出された概要事業計画というのはいつ出されたものなのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"それは平成２４年７月２０日に選定委員会を開始いたしました。その前の平成２４年７月１３日に私どものほうに届いております。","voiceIndex":84,"id":"exchange-029"},{"speaker":"井上副委員長","kind":"提案","question":"ですから、本来は例えば、私が指摘をしたいのは、３ページの１番の(3)で、サービス向上につながる事業計画となっているかということに対して、どのような提案をされたから、そうだと見たとか、４番目の会館の利用率、山内委員がおっしゃったのと同じ、私もここのところに視点があったのですが、会館の利用率を高めるためにはどういうふうに提案をされたのか。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で私どもも委員の方々には配付をしますが、その後はすべて回収をしたり、そのような形で企業の企業秘密と申しましょうか、企業戦略と申しましょうか、そんなものも保護しています。","voiceIndex":86,"id":"exchange-030"},{"speaker":"井上副委員長","kind":"質問・要望","question":"当然プロポーザルとか複数の事業者があったら、そういうことは検討ありだと思うのですけれども、一つの事業者でここが適正であるというふうに認めるということが前提であれば、当然、そういうことが、一つしかないわけですから、ここにしてくださいねと言われるようなものですから、ここのところでは、ではここにもうちょっと指定管理者として努力をしていただきたいとか。","respondent":"安藤文化スポーツ振興課長","answer":"私どももこの選定に当たりましては、区の基本方針に基づきまして進めてあります。そんな中でいろいろお示しをしましたような指定管理者選定委員会の特別の理由がある場合ということで進めてまいりました。そんな中で基本方針に準じた形で進めてまいりました。","voiceIndex":88,"id":"exchange-031"},{"speaker":"井上副委員長","kind":"提案","question":"今まで利用していた福祉施設が突然運営者が変わることの市民サービスの低下につながらないようにということだったと思います。そこが文化的なこういった設置目的には、特別の理由には到底当たらないと私は判断をするのですけれども、区が特別の理由だとおっしゃった、そこの福祉施設とは違うのだというところも含めて、どのようにお考えなのか、そこだけはちょっとお伺いしてみたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"私どもとしては、基本方針に沿って、ただし書きのとおり、設置目的だったり、事業内容に特別の理由があるというふうに理解をいたしまして、それで選定したところです。","voiceIndex":90,"id":"exchange-032"},{"speaker":"井上副委員長","kind":"質問","question":"だから、その特別な理由は何ですかということなのです。文化施設のこういうものというのはどんどん民間のところに活力があってという、福祉施設とは違うというところで、そういうふうにくくられてしまって、決まって、随意契約みたいになっていくことはこの指定管理者制度の本来の制度に沿うものではないと思いますので、そこはいかがでしょうか。","respondent":"安藤文化スポーツ振興課長、中川原地域振興事業部長","answer":"ここのはじめの選定の考え方にお示ししていますが、私どもとしてはここのただし書きに書いてある設置目的や事業内容というところは一番の選定の考え方にあると理解をしまして、特別の理由があると理解をしています。今回、特別の理由に当たるかどうかというところで、選定の考え方で特別の理由に当たるということを述べさせていただいていると課長はるる説明していたのですけれども、今回、文化振興事業団は平成２４年４月に公益財団法人になりまして。","voiceIndex":92,"id":"exchange-033"},{"speaker":"井上副委員長","kind":"提案","question":"一つ確認だけ。１番の、今、改善をするという努力を選考の中で伝えられているということで、１番の利用者等の意見、ニーズを積極的に把握し、改善する体制となっているかということとクレームへの適切な対応が考慮されているかというところの二つについて、どのような提案で事業計画がされているのか教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"もう一つのクレームについても、クレームが業務改善の宝庫というふうに受けとめていると。それで、クレームをいただいた場合には、すぐに機動力を持ってきちんと処理をできるような体制を組むというふうに提案されています。","voiceIndex":95,"id":"exchange-034"},{"speaker":"武内委員","kind":"質問・要望","question":"ある意味では本当に文化振興事業団、自信を持ってそういうところと戦っても大丈夫だろうと我々思っているわけですから、だからという意味ではないのですけれども、その辺の指定管理者の選定のあり方というのをもうちょっと研究していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"意見","question":"共産党は前回設置条例のところでも、指定管理者はなじまない、直営でやるべきだということで、反対をしてきましたので、今回はこのやっぱり指定管理者の指定なので、同様の理由で反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-036"}]},{"id":"topic-03","title":"の第５９号議案、平成２４年度品川区一般会計補正予算（歳出、区民委員会所管分）","agenda":"の第５９号議案、平成２４年度品川区一般会計補正予算（歳出、区民委員会所管分）","exchanges":[{"speaker":"山内委員","kind":"質問","question":"ちょっとオリンピックのほうを伺いますが、これまでも横断幕とかやっていますよね。区として、気運の高まりを今どんなふうに受け取られているか。区内で気運が高まっていると思っておられるのか、そのあたりをお伺いいたします。","respondent":"安藤文化スポーツ振興課長","answer":"その後の感触としまして、区民の方々とスポーツの活動を通じて触れ合う中で、オリンピック後の気運の醸成というのは以前に比べまして非常に盛り上がっているような感覚を持ちます。しかし、これから、今後、一層の高めはまだまだ必要だと認識はしています。","voiceIndex":111,"id":"exchange-037"},{"speaker":"山内委員","kind":"質問","question":"前回のリオデジャネイロは落選をしまして、いろいろな反省点があったと思うのですが、そのあたりの反省点というのは東京都と、いわゆる東京自治体と、どういう話し合いをしているのですか。民間、すべての人たちがそういう捉え方をしているところがある中で、お金をかければいいというわけではないと思うのですが、そのあたり、どのように考えていますか。","respondent":"安藤文化スポーツ振興課長","answer":"ですから、我々のほうからその内容について、いろいろなものを考えたり、そういうボトムアップと申しましょうか、そんな形で今現在進めているところです。","voiceIndex":113,"id":"exchange-038"},{"speaker":"山内委員","kind":"質問","question":"私の感想。であるのならば、よくオリンピック招致に賛成ですか、反対ですかという数字がありますよね。例えば品川区でも、そういった数字をとってみたらどうですか。それで、品川区は例えば、７割の人が賛成ですよと。であるならば、そういった数字を堂々と、これは東京都に示すことができるような数字をとってみるというのもおもしろいのではないかなと思うのですけれども、どうでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"東京都でやった部分については六十何％という上昇がされたというふうに聞いています。今ご指摘のように品川区でもというようなお話でございました。今後、できるかどうかを踏まえまして、ちょっと研究させていただきたいと思います。","voiceIndex":115,"id":"exchange-039"},{"speaker":"山内委員","kind":"提案","question":"確かにできるかどうかというのはあると思うのですが、これは本当に私の提案というか、思いつきで言っているだけであって、別にそれをやるやらないは要請もしませんけれども、数字が出ることによって、では、品川区、何をしようかということを改めて、せっかくこうやって今気運を高めようと言って、補正予算を組んでやっているわけですから、そこら辺までちょっと徹底的にやってみて。","respondent":"安藤文化スポーツ振興課長","answer":"文化スポーツの所管の担当課長としても、この招致については東京国体とも絡めまして、ぜひ区民の方々に意識の啓発をして高めていきたいと思っています。","voiceIndex":117,"id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"私はオリンピック・パラリンピック招致賛成という立場なのですけれども、まず、ちょっと大まかな質問をしますが、よくオリンピックというと経済的にという話が、経済効果って出てくると思うのですけれども、今日、産業振興のお２人が来ていらっしゃるので、どちらでも結構ですので、実際大まかな話でやっぱりオリンピックと産業といいますか、その辺についてのお話をちょっといただけないかと。","respondent":"米田商業・観光課長","answer":"これで、今一定の制約があるのですが、招致が見事かなったということになりましたら、また別のＰＲの仕方ができるのだろうと考えております。","voiceIndex":120,"id":"exchange-041"},{"speaker":"藤原委員","kind":"質問","question":"前回は、残念ながら招致ができなかったわけですけれども、ちょうど今日は前回のときの担当者の課長が偶然いらっしゃいますけれども、前回のここがだめだった、一番言われているのは、国民があまり来てほしいというパーセンテージが上がらなかったということもあると思うのですけれども、前回、招致できなかった担当の課長として、今どういうふうな思いがあるのでしょうか。","respondent":"中川原地域振興事業部長","answer":"まだ来ていないのです。","voiceIndex":122,"id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"そこを聞こうと思ったのですけれども、そうなんですよ。まだ来ていない。順番に行きますね。それで、招致という形をしましょうと。ロンドンで日本がものすごくメダルもとれた。東京都というのが中心でやっていたのですけれども、あのとき、招致バッジ、バッジだけで招致できるわけではないですが、今、部長からもちょっとお話がありましたけれども、東京都からバッジも全然来ないわけではないですか。","respondent":"安藤文化スポーツ振興課長","answer":"東京都招致委員会の動きですけれども、今、東京都招致委員会に非常に各２３区はじめ、各区長が連絡をとって、それでそれぞれバッジもそうですが、グッズ、それからのぼり旗とか、横断幕、非常に急ピッチで今製作の段階に入っています。","voiceIndex":124,"id":"exchange-043"},{"speaker":"藤原委員","kind":"意見","question":"頑張っているのですよね。それで、課長も部長ももちろんぜひオリンピック来てもらいたいという気持ちでやっていると思うのですが、改めまして、部長、本当に来てもらいたいかと思っているとは思うのですけれども、その辺の、東京都から言われているからとかという仕事の面でというよりも、私も気持ちの中で本当にオリンピックに来てもらいたいのだという思いをいただければ。","respondent":"中川原地域振興事業部長","answer":"先月の区長メッセージは、オリンピックについて職員への呼びかけでした。区長は、皆さんもお聞きになっているかもしれませんが、今、いろいろなところに行ったときに、今の小学６年生が二十歳になるときが２０２０年。今、大人の都合で決めるのではなくて、子どもに夢をつなぐ。","voiceIndex":126,"id":"exchange-044"},{"speaker":"武内委員","kind":"確認","question":"防犯カメラのほうでまず質問で、この補正予算自体は非常に大事なものだと思っているのですが、このまず２番目の事業目的のところで、区が指定する安全安心まちづくり推進地区内においてとあるのですけれども、その安全安心まちづくり推進地区というのはどこになるのかというのをまず教えてもらいたいというのと、それから下側の３の事業内容のところの防犯カメラ設置の実績と、各町会のがあって。","respondent":"中川原地域振興事業部長、安藤文化スポーツ振興課長","answer":"補助とセットのお話だそうです。それから、平成２４年度の大井銀座商店街ですが、これはまず前に１回3)で大井銀座商店街に設置をしています。3)の２ということで、増設という意味です。私からは、障害者のＰＲ、それから学校等のパラリンピアンの訪問についての２点を説明します。","voiceIndex":128,"id":"exchange-045"},{"speaker":"武内委員","kind":"確認","question":"それは確認しました。それから、運用のところですけれども、そうすると、今までこれだけ平成１７年からやってきて、３１７台になるわけですけれども、何かトラブルとか問題があって、そういうチェックをしないといけない、防犯カメラの見直しだとか、何かそういうケースがあったのかどうか、もしわかれば教えてください。","respondent":"安藤文化スポーツ振興課長、中川原地域振興事業部長","answer":"大変恐縮ではありますけれども、私ども文化スポーツ振興課としてはこの１,０００万円の事業を全庁的に調査をかけました。そんな中で、障害者福祉課のほうでこういう事業の提案があったということで、計上させていただきました。特に私どものほうで問題があったということはないのですが、むしろ、犯罪の捜査に役立ったということのほうが、大井町の横断歩道での事件とか、かなりこのごろ犯罪に対する効果が高まっていますので。","voiceIndex":131,"id":"exchange-046"},{"speaker":"武内委員","kind":"意見","question":"今のところですけれども、そうすると、これは、防犯カメラを見るときは、区の関係者が立ち会うときに警察とか、あと、商店街のしかるべき方が立ち会って見るということですね。","respondent":"中川原地域振興事業部長","answer":"これを見るときというのは、何かないときは見ないのですね。何か事件とか問題があったときに、警視庁のほうに資料提供をして、そして見てもらうという形になりますので、それをまちの人が見るということはあまり想定はしていないということです。","voiceIndex":134,"id":"exchange-047"},{"speaker":"武内委員","kind":"意見","question":"それはわかります。この間の大井町の殴ってしまって亡くなったという、ああいうときに、では、それは警察からその商店街か何かの防犯カメラの設置者のほうに依頼が来て、それで警察の方が見る。区によってはそこには一切立ち会わない。商店街の方もそこには立ち会わないとかその辺はどうなっているのか。","respondent":"中川原地域振興事業部長","answer":"捜査の状況にもよると思うのですが、委員会をつくってやっていますので、その責任者の方は資料提供ということで、警察の方と連携されると思いますが、そういった状況だとは思います。","voiceIndex":136,"id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問","question":"オリンピックのところなのですけれども、この間、品川区で東京招致に向けてかけてきた予算というのは今回も含めてどのぐらいになるのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"私が今把握しているところで、今回この２０２０年オリンピック・パラリンピック直接に予算を投入しているというのはございません。今回初めて予算を計上させていただきまして、気運醸成事業をするです。","voiceIndex":139,"id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問","question":"だから、幾らこちらで頑張っても、去年のアンケートですけれども、都民の声というところでも反対が朝日新聞でも８割、日経ビジネスインターネット版では７割。去年ですけれども。区長はそうではなくて、進めるのだというふうに言っていますけれども、課長としてはどういうふうに、全く別の意見を言うことはできないと思うのですけれども、本当に盛り上がると思っているのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"そんな立場から言わせてもらいますと、まさしくこのオリンピックというのは子どもたちの本当に夢を与えて、２０２０年、重要な、何でしょうか、開催となるような気がします。まして今回の平成２５年には東京国体もあります。","voiceIndex":141,"id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"わかりました。ですので、そういった日ごろからの予算をしっかりつけていくということ、どんどん区民も参加しやすいものにしていくということが必要だと思うので、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"意見","question":"防犯カメラのほうは賛成ですが、やっぱりオリンピックのほうでは、今の現状をしっかり見て、今はやるべきではないと私たちは思います。それだけあれば、復興・防災にやはり使うべきだというのが都民感覚、区民感覚だと思いますので、オリンピック・パラリンピックの東京招致気運は反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":150,"id":"exchange-052"}]},{"id":"topic-04","title":"はじめに、(1)の「品川区地域安全のつどい」の開催","agenda":"はじめに、(1)の「品川区地域安全のつどい」の開催","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"必ずこういうのが出たときに目的とか趣旨が出てくるのですけれども、改めて目的を書かなかった理由と目的を教えてください。","respondent":"中川原地域振興事業部長","answer":"今回は、報告なので、イベントといいますか、行事のお知らせに従って書きました。目的につきましては、地域安全運動の始まりを告げる年中行事ということで、地域安全運動に皆さん、今年も取り組みましょうといった防犯協会と警察署の関連の方々が集まって行うものです。","voiceIndex":158,"id":"exchange-053"},{"speaker":"藤原委員","kind":"質問","question":"ここに書いてあることは質問していいのですよね。第４部、歌謡ショーなのですけれども、何で里見浩太郎さんなのでしょうかということと、それと里見浩太郎さんへ払うギャラといいますか、区から出てくると思うのですけれども、大体お幾らぐらいなのでしょうか。","respondent":"中川原地域振興事業部長","answer":"すみません。詳細については、資料をちょっと持ち合わせませんので申しわけございません。後ほどお知らせいたします。","voiceIndex":160,"id":"exchange-054"},{"speaker":"藤原委員","kind":"質問","question":"こういう事業をするのは投資対効果というのを行政として必ず考えると思うのですけれども、地域安全のつどいに歌謡ショーとか落語とか、こういうイベントを入れていくのというのはどういう投資対効果というのがあるのでしょうか。","respondent":"中川原地域振興事業部長","answer":"ただし、テーマにつきましては、落語とかこういうものも、防犯とかそういったものを視野に置いた構成になっていると考えています。","voiceIndex":162,"id":"exchange-055"},{"speaker":"藤原委員","kind":"質問","question":"すいません。芸能人を呼んで、芸能人が来るから来てねというよりも、その集いは集いでやる。なぜ里見浩太郎さんなのかなという思いもありました。その辺も含めて、後で予算に関しても、あした、また委員会があるので、あしたでも結構ですし、その辺のもの、さっき雑費ともに幾らとか、里見さんに幾らかと、その辺が教えていただければ幸いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-056"},{"speaker":"武内委員","kind":"質問","question":"品川区のほうは、主催も品川区なのですけれども、どなたが参加される予定なのですか。","respondent":"中川原地域振興事業部長","answer":"決算特別委員会中でもありますし、例年そうなのですけれども、区長が挨拶に行って、すぐ戻ってくる予定で、区の関係者は、管理職は参りません。","voiceIndex":168,"id":"exchange-057"},{"speaker":"武内委員","kind":"質問","question":"今気になったのは、その区長が決特中なので、今、では毎年、大体この時期になっているのか、なってしまうのか、それともほかのところとの、警察とか防犯協会との当然日程調整があるのでなかなか区の都合どおり行かないのだろうと思うのですよ。その辺は毎年どうなのでしょうか。","respondent":"中川原地域振興事業部長","answer":"全国地域安全運動に合わせてやっていますので、どうしてもこの時期に、若干のずれはあるのですけれども。","voiceIndex":170,"id":"exchange-058"},{"speaker":"山内委員","kind":"質問","question":"日時が１０月５日金曜日１時から３時半と書いてあります。そうやって考えると、この防犯協会の会員という人たちはほとんど仕事をやめられているお年寄りの方なのかなと想像するのですが、この防犯協会ってよくわからないのですけれども、この会は一体何なのですか。もし若い人たちがいるのであれば、この日時というものの設定の仕方はちょっとおかしいのではないかなと思うのですけれども、どうでしょうか。","respondent":"中川原地域振興事業部長","answer":"私がこの防犯協会の会議に出させていただいている限りでは、年配の方が多いのですね。防犯協会というのはどういう会かといいますと、警視庁の応援といいますか、支援をする人たちなのです。","voiceIndex":173,"id":"exchange-059"}]},{"id":"topic-05","title":"の区立総合区民会館および区立体育館における指定管理者のモニタリング・評価結果","agenda":"の区立総合区民会館および区立体育館における指定管理者のモニタリング・評価結果","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"総合区民会館のところで、サービス向上および業務改善の視点のところで、利用者にアンケートを実施されるということなのですけれども、私の地域の方から、集まるところでは、多分料金が高いというのが一番多いのですけれども、そういった声はありましたか。","respondent":"安藤文化スポーツ振興課長","answer":"私もアンケートの中身は一通りチェックをさせていただきました。そんな中でアンケートについては、施設の開設日だとか、使用時間についての意見が多くございまして、料金が高いというのは、今のところ見てございません。","voiceIndex":185,"id":"exchange-060"},{"speaker":"武内委員","kind":"質問","question":"スポーツ協会のほうですけれども、ちょっとそっちはここの指定管理とは関係ないかもしれないのですけれども、総合体育館のほうは冷暖房完備ですけれども、戸越体育館はもともとそれがつくられたときに、あまり冷暖房という発想がなかったから、そのまま残ってしまったのですけれども、そこら辺の経緯を教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"工事といいますか、計画的な修繕ですが、とりあえず、今現在においてはこの平成２４年度まで計画していると。","voiceIndex":188,"id":"exchange-061"},{"speaker":"武内委員","kind":"質問","question":"わかりました。きゅりあんのほうですけれども、施設の維持補修はわかりました。この間もちょっと戸越体育館にある行事で行ったときに、やっぱり、結構暑いのですね。それで、所管が違うのかもしれないのですけれども、災害時のときにそういう扱いになるに当たって、中でもそういう暑さ対策、寒さ対策みたいなものを考えないといけないのかななんて思って、その辺の計画はあるかどうか。","respondent":"安藤文化スポーツ振興課長","answer":"一般的なアリーナというのですか、それについてはほとんど冷暖房がないと認識しています。今後につきましては、それが検討されるか、ちょっと私は断言できませんけれども、利用者の安全確保のためを思って今後進めていくのだと理解しています。","voiceIndex":190,"id":"exchange-062"},{"speaker":"武内委員","kind":"意見","question":"わかりました。そうしたら、きゅりあんのほうは、ここに出ているのはいわゆる毎年やっているものの継続みたいな意味合いで書かれている。何か今後もうちょっと抜本的に、まだ２３年ですけれども、あそこ全体をどうしようかということを踏まえた提起というわけではないということなのかなというのが一つと、それから、体育館のほうはまたもう一回。ではちょっとそこだけ。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、プライオリティーの高い順に改修を進めているということと、それから一度にホールの照明、ホールのじゅうたんだとか、一つのものが長期間にわたって利用ができないということにならないよう配慮いたしまして、そこら辺を配慮して、今、計画的にやっているところです。","voiceIndex":192,"id":"exchange-063"},{"speaker":"山内委員","kind":"質問","question":"両方の説明の概要のところにその他区長が必要と認めた業務というのは、過去にどんなことがあったのですか。お願いします。","respondent":"安藤文化スポーツ振興課長","answer":"そこも総合体育館のアリーナを使って全面的にやっているところです。そういうふうな設置目的だとか、そういうものに反して、そういうものを使う状況のときに定めたものです。","voiceIndex":195,"id":"exchange-064"},{"speaker":"井上副委員長","kind":"質問","question":"区民会館のほうなのですけれども、先ほど武内委員からもあったのですが、割と区のこういう改築のことというのは改築をしてから二、三年後に解体みたいな、あのときに直したのにというようなケースも見受けられるのですけれども、この場合、どのぐらいまで個々の改修で続けるという、建物自体、きゅりあん自体は何年後ぐらいまでが使う想定をされているのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中でも、補修をしてなるべく使っていこうというふうになってありますので、きゅりあんのほうもまだ２４年ですので、また、補修をしながらやっていくのだというふうに理解しております。","voiceIndex":198,"id":"exchange-065"},{"speaker":"井上副委員長","kind":"質問","question":"都市整備公社が管理を受託してということになると、ビルを兼ねて、きゅりあんだけの話ではなくて、そちらに今あるヤマダ電気が企業が変わったりとか、いろいろな関係で一緒にやったほうがいいケースとか、いろいろ出てくると思うのですが、そういったときに、あそこの、きゅりあんは権利として総合区民会館として一部しかないわけで、その辺の。","respondent":"安藤文化スポーツ振興課長","answer":"先ほど都市整備公社と事業団が連携しているのは、そこの全体のビルは都市整備公社が面倒を見ていますけれども、指定管理の部分のところは文化振興事業団が指定管理者として入っていると。","voiceIndex":200,"id":"exchange-066"},{"speaker":"井上副委員長","kind":"質問・要望","question":"質問のやりとりなんかにワイヤレスを使ったりだとか、そういうのはそこの建物では、結構ニーズがあって、相談をすると、２本しかだめですと切られて終わってしまうのですけれども、そういうところのアンケートに要望が結構出されていると思うのですが、私たち結構周りでそういう要望を出していますけれども、そういうところについて改善とか何か方法はないのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"今、お尋ねのマイクについてではございませんけれども、利用者の方から例えば、調理の部屋を借りると、そんな中で電気釜をたくさん使ったらすぐヒューズが飛んでだめになってしまうだとか、そういう直接的にかかわる部分については出していただきまして。","voiceIndex":202,"id":"exchange-067"},{"speaker":"井上副委員長","kind":"質問・要望","question":"例えば、そういうふうなニーズがあったときに、施設等の維持および修繕に関することという指定管理者の改修範囲ではないと思うのですけれども、多分何か線とかいろいろな工事が必要で、そういったときにはどういうふうなルートというか、経過をたどって改修ができるのか、それはただ聞き置いて、できませんよという、私たち区民の方が利用する場合には、窓口で対応するしかなくて。","respondent":"安藤文化スポーツ振興課長","answer":"スポーツ協会もそうですが、小破修理と申しましょうか、一定の管理や修繕だとか、すぐ対応できるものについてはやはり民間の機動力だとか柔軟性を活かしまして、すぐそこで対応できるような措置もしています。","voiceIndex":204,"id":"exchange-068"}]},{"id":"topic-06","title":"の区立荏原平塚総合区民会館の愛称","agenda":"の区立荏原平塚総合区民会館の愛称","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"検討会の区側なのですけれども、何で待機児童対策担当課長が入っているのですか。","respondent":"安藤文化スポーツ振興課長","answer":"ここは、幼保一体施設も入った複合施設となっています。そこの所管の担当課長として、そこの場所に幼保一体施設が入るということで、メンバーに入っていただいたです。","voiceIndex":215,"id":"exchange-069"},{"speaker":"武内委員","kind":"確認","question":"確認なのですけれども、この１１９通と８９通の公募があった中で、スクエア荏原、ひらつかホールがやはり一番多かったのですか。それがどれぐらいあったのかというのがもしわかれば。それから、それ以外に何か幾つかあれば、どんなのがあったのか。","respondent":"安藤文化スポーツ振興課長","answer":"とりあえず、１１９通の中からスクエアのものができたところは２通ございました。２通です。それで、多い中で我々検討委員会の中で検討委員の皆さんに候補というものを１人３件ほど選んでいただきました。その中で、スクエアやひらつかというのが２件。","voiceIndex":218,"id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2646#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":49266,"voices":228}},{"id":"h24-20120924-7","meetingId":"h24-cm09","date":"2012年9月24日","dateIso":"2012-09-24","committee":"厚生委員会","time":"午前１０時００分～午後０時２６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"八ツ山保育園ふれあいデイホームのほうなんですけれども、平成７年からずっとやってこられて、今回、廃止ということなんですが、ここにも書いてあるんですけれども、廃止の理由で、自立している高齢者が要介護とかになってきたと。その２点について、お伺いしたいと思います。","respondent":"原高齢者福祉課長","answer":"１点目の廃止のところです。廃止の理由と、廃止後のところとかぶってまいりますけれども、委員ご指摘のとおり、人の入れかえをすればいいのではないかです。","voiceIndex":11,"id":"exchange-001"},{"speaker":"塚本委員","kind":"質問・要望","question":"空いたスペースについては、また今後、何か動きがありましたら報告いただきたいと思います。この前、視察で見にいった高齢者と乳幼児の交流みたいな施設とか、ああいうものも、ひとつ今後の構想の中に入っているかと思うんですが、その点に関しての、今回のこの辺の参考というか、見解とうか、ちょっと最後にお伺いしたいと思います。","respondent":"原高齢者福祉課長","answer":"園児との交流というのは、八ツ山で、それが問題だったということでは、区のほうは全く考えてございません。","voiceIndex":13,"id":"exchange-002"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これは、定員が１０人と書いてあるんですけど、実際は何人くらいが利用されているんでしょうか。","respondent":"原高齢者福祉課長","answer":"今、３０名登録していますので、おおよそのイメージとしまして、週に２回ご利用いただいているというような認識です。","voiceIndex":15,"id":"exchange-003"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１回１０名と書いてあるんですけれども、そうすると、１０名が週２回というふうに理解してよろしいんですか。","respondent":"原高齢者福祉課長","answer":"３０名の方が週２回、ですから１日１０名という形です。","voiceIndex":17,"id":"exchange-004"},{"speaker":"鈴木（博）委員","kind":"意見","question":"わかりました。それから、ここが廃止になってから、空いたスペースに関しては、保育課のほうで管理することになるというお話なんですけれども、保育園自身が足りないので、やはりその辺は、保育課のほうで、要するに子育てのほうに十分に利用していただいたらいいのではないかと思います。それはそれで、もう決着がついたということでいいのではないかと、僕は思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、そういう最初の目的は目的としてあるのであれば、今度、それを達成するために、今、元気高齢者も増えてきているのであれば、そういう部分のモデル的なこととか、そういうことは、私は続けていくべき、模索をしていくべきというのか、そういうことが必要だと思うんだけれども、そこら辺の考え方というのを、ちょっと教えてほしいと思います。","respondent":"原高齢者福祉課長","answer":"一つ、区のほうでも、所管は別ではありますけれども、医療センターと高齢者、シルバーセンターとの交流といったところもモデル的に実施をして、行事があるときにお互いに。","voiceIndex":20,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"それはそれでいいんです。ただ、いろいろな年代がありますよね。保育園だと、ここは１歳からずっときて、いろいろな場面があるじゃないですか。だから、目的をどう捉えるかということがあって、ここはこれでいいんだけれども、そこら辺のところのことを、ぜひちょっと話を聞きたいと思っていたので、もうちょっと突っ込んで教えてほしい。","respondent":"原高齢者福祉課長","answer":"例えば、そういった高齢者のところに園児が来ることによって交わるということも一つ想定できますし、あるいは、何らかの形で保育園に、現在、食事を通じてということで、地域によっては少し取り組みもあるかと思いますけれども、いろいろな形の園児との交流。","voiceIndex":22,"id":"exchange-007"},{"speaker":"若林委員","kind":"質問","question":"そういう中で、あえてこれを廃止して、まだ受入れ先の態勢が、いわゆる園児、幼児との態勢がまだ決まっていない中で、こういう決断、計画を立てられるというのは、それをもう１回、ちょっとお聞きしたいと思います。ちょっと納得いかないところがあります。","respondent":"原高齢者福祉課長","answer":"なかなかこじんまりとしたところであるがために、通常でありますと、認知症の方は認知症のデイサービスということで、認知症専門に対応するデイサービスが用意されておるわけですけれども、認知症だからそこだけということではなくて、今までの中で。","voiceIndex":24,"id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"少し難しい程度であれば、せっかく平成７年からやられているこの八ツ山保育園のふれあいデイホームをさらに充実をさせて、いずれにしても高齢者の利用者は、当分増え続けるという予測が立てられているので、一方でバリアフリー住まい館のぽかぽかというのですか、この定員の拡大も同時に図るということで、全体として、園児との交流も含めて拡大、充実をさせていくという。","respondent":"原高齢者福祉課長","answer":"考え方として、今のものを継続していくという考え方も一方ではあるかと思いますけれども、先ほど来の話の繰り返しになるかと思いますけれども、入っている方、ここに通われている方の中でも、認知症でも２ｂ以上ということで。","voiceIndex":26,"id":"exchange-009"},{"speaker":"若林委員","kind":"質問","question":"わかりました。そうすると、もう一つ五反田保育園のほうのふれあいデイホームがありますけれども、こちらの現状と、こういう流れの中で、保育園の拡大も含めて、高齢者のサービスとして、現状と、今後の見通しを、何か立てていらっしゃると思うので、ちょっと教えていただけますか。","respondent":"原高齢者福祉課長","answer":"登録者は、現時点で３２名ということで、八ツ山とほぼ同じような状況です。そういった中で、こちらのほうも、シルバーと、保育園と、ふれあいデイホームということで、八ツ山保育園とは、また少し中身が変わってあります。","voiceIndex":28,"id":"exchange-010"},{"speaker":"中塚副委員長","kind":"質問","question":"平成７年にふれあいデイホームの開設時に、まずこの場所を品川区が取得した経過と背景、そして始まるに至った、この事業をやろうと思った、そこの開設当時の状況を、改めて伺いたいと思います。先ほどからの説明ですと、今後、福栄会でのぽかぽかの定員が増えていくなどありましたけれども、どう引き継がれていくのか、そこの経過を伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"その間は、保育課、あるいは高齢者福祉課が連携をして、在宅サービスセンター条例の中で、始まった当初は要項でスタートしましたけれども、平成９年に条例改正の中に、この部分を入れさせていただいて、介護保険のときには、指定事業者ということで。","voiceIndex":30,"id":"exchange-011"},{"speaker":"中塚副委員長","kind":"質問","question":"確かに新たに入浴施設も増えますから、利用者にとってもサービスの幅が広がるのかなと思いますけれども、場所が変わりますけれども、利用者にとって不利益やサービスの内容に変更などを生じないような、その辺の対応をどうお考えなのか、改めて伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"不利益というところがございましたけれども、そういったことがないように、移行の調整でありますとか、あるいはご家族との相談の中できちっとした対応ということで、しています。","voiceIndex":32,"id":"exchange-012"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"あわせて一つだけ月見橋の在宅サービスセンターの移転ですけれども、この間も計画はあったので、確認ということですけれども、当初予定していた移転先が変更となったり、この場所になったり、周辺の方々との説明会など、少しちょっと経過を改めてご説明いただきたい。一時移転ですけれども、広さや事業内容に変更はないのか。この点、確認だけさせていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった中で、区内で四、五カ所案を出したところですけれども、さまざまな条件、事情等々がございまして、最終的にはこの場所ということで落ち着いてきたところです。そういった中で、この間、私も出席して、２回ほど、ご利用者のご家族の説明会をさせていただきました。","voiceIndex":34,"id":"exchange-013"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"先ほども述べましたが、ふれあいデイホームの廃止ですけれども、現在、利用されている方々、ご家族の方々への丁寧な説明や対応、それから、福栄会でも場所が移るわけですけれども、丁寧に対応していただきたいということと、必要な対応だと思いますので、これについては賛成です。月見橋の在宅サービスセンターについても、必要な工事ですから、もちろん賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-014"},{"speaker":"中塚副委員長","kind":"質問","question":"薬剤師や食品衛生検査施設設置について、今まで法律で定められていたものを、各自治体の条例で設置するという一括法について、まず、こうした規制緩和について、品川区はどう考えているのか、その評価を伺いたいと思います。自治体の財政力次第で公共サービスに格差が生まれる、こうした流れは間違っていると思うんですけれども、区の評価を伺いたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"この２件、第６５号議案、第６６号議案におきましては、地域主権の大きな考え方、大綱に示されているとおり、基本的には自治体のほうで責任を持つということになっておりますが、事柄によって、例えば、今回、医療水準を一定にしなければいけない、また検査室におきましても。","voiceIndex":48,"id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問","question":"そうなったときに、自治体間によって、医療や介護や、こうした福祉の確保に自治体の財政力次第で格差が生まれてしまう、こういう流れについて、区はどうお考えなのか、改めて伺いたいと思います。そのところを、品川区はどういうふうに考えているのか。あわせて、具体的に今回、条例設置ということですけれども、現状の基準と何か変更があるのか、そこも伺いたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"現状の基準と異なっているかということにつきましては、今回、条例化するにあたりましては、現状の基準と変更はございません。","voiceIndex":50,"id":"exchange-016"},{"speaker":"中塚副委員長","kind":"質問","question":"いわば緩めておいて、基準をつくるという、ちょっと変な法律だと私は思うんですけれども、今、法律の説明があったんですけれども、医療の基準とか、地域や自治体によって格差を生むということはあってはならないと思うんですけれども、その点、区がどうお考えなのか、伺いたいと思います。今度は区の条例になるわけなので、実際に区内ではどうなのか伺いたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"基準の考え方におきましては、やはりそれぞれの事業等のケースによるものだと考えています。２点目の、品川区内における適用されている施設ですが、今、私ども、把握しておりますのは２施設、医療法第１８条の考え方に基づいて薬剤師を配置しているのが２施設あります。","voiceIndex":52,"id":"exchange-017"},{"speaker":"中塚副委員長","kind":"質問","question":"規制緩和のことについて、事業によるものとおっしゃいましたが、じゃあ今回、具体的に薬剤師と食品衛生検査施設のことですけれども、この基準や役割を、私は緩めてはならない、弱めてはならないと思うんですけれども、区の意思を伺いたいと思います。","respondent":"早津健康福祉事業部長","answer":"例えば生命にかかわるようなことであれば、ナショナルミニマム的な基準が必要でしょうけれども、そうでないものについては、地方の自主性に任せるような形で地方に委任していくと、こういう流れの中で、今回のものも出てきていると考えています。","voiceIndex":54,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この前の区長の答弁でもあったけれども、与えられた部分の中で、しっかりそれを踏まえながら区民サービスを提供していく、特にこういうのでそういう話が出たときは、しっかりそういうところは答えていただかないと、アバウトな話をしていたってしようがないわけで、与えられたものをしっかり、よりよい方法で区民サービスをしていくんだということは、我々も言うけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-019"},{"speaker":"中塚副委員長","kind":"意見","question":"今回の新しい条例は現行と同じ基準だというご説明ですので、賛成ですが、その基準を緩めたり、規制緩和をする流れは、しっかり国に対してもやめるように意見を言っていくべきだと思います。賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-020"}]},{"id":"topic-02","title":"第５９号議案、平成２４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第５９号議案、平成２４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"さっきの地方分権じゃないけれども、頭に来るのから一つ。それの考え方を教えてください。調剤薬局で生活保護の人が来たってわかるわけだから、必ずそういう医薬品を出すんだということを決めることがいいのかどうかわからないんだけれども、そうでもしなくちゃ、こんなお願いばっかりじゃ進まないような気がしてならないんですけれども、そこら辺の感じを教えていただきたい。","respondent":"伊津野品川区保健所保健予防課長、竹田生活福祉課長","answer":"定期予防接種の財源につきましては、特別区長会等を通じまして、いろいろな機会を通じまして、国のほうにも要望しておりますが、とりあえずのところは、一般財源で補正するという形で決めていくしかないところです。条例化というお話ですけれども、こちらも、国、東京都のほうの基準に基づきまして実施している事業なので、単独の条例化も難しいかと考えております。","voiceIndex":76,"id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"単独の条例化というのがなぜできないかというのを、もうちょっと詳しく教えていただきたい。そうしたら、条例化することによって、基本的にはジェネリックというか、後発医薬品にして、そういう何があったときには、こういうこともできる規定とか、原則とか、条例にはそういうのがつきものなんだけれども、そういう規定をつけたっていいわけではないですか、できるみたいな。そっちだけ答えてください。","respondent":"竹田生活福祉課長","answer":"生活保護での後発医薬品の考え方ですが、まず処方医が後発医薬品に変更可としている方に対して、薬局において一旦服用していただくご説明し、ご本人の同意のもとで、１回の処方期間を目安に服用していただき、さらにその後、ご本人の希望を確認して。","voiceIndex":79,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ、その部分は調べていただいて、教えていただきたい。例えば、普通は調剤薬局で出していただくときは、お金は払う。ジェネリックに変えたらどうですかって、もちろん医薬会社の方から言われたりして、そうすると、お金が６割とか、７割とかになるというと、じゃあそのほうが安いからと、お金を払っている人はそう思います。それじゃあ、絶対に進まない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-023"},{"speaker":"中塚副委員長","kind":"質問","question":"今回の当初予算は何件分を計上していたのか。そこら辺について、どういうスタンスなのか、伺いたいと思います。それとも継続をちゃんとしているのか、そこら辺については、どういう考えのもとにやられているのか、伺いたいと思います。今は高齢者、障害者だけの支援ですけれども、やはり防災対策として引き上げて、一般世帯対象に広げていくことも考えていくべきだと思うんですけれども、いかがでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"一般世帯のほうへ拡大ということにつきましては、高齢者世帯につきましては、家具転倒防止の器具を取り付けるのにも一苦労されるということで、一般世帯につきましては、防災課のほうのあっ旋物資の関係で対応していますので、今後も。","voiceIndex":82,"id":"exchange-024"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"私の理解が間違っていたら指摘してほしい。あわせて、どんな薬を使うかは、医師の専門的な判断と、患者の選択によるものだと思いますが、先ほどから、区は強制は難しいという説明がありましたけれども、そもそも薬というのは、ドクターの専門的な判断と、患者の選択だと思うんですけれども、そこについては、どうお考えなのか伺いたいと思います。","respondent":"白鳥高齢者いきがい課長、竹田生活福祉課長","answer":"平成２４年度のときには、やはり見込み数がそれほど多くはないというような時期でございましたので、今年度、補正ということになったわけです。その調査結果に基づきまして、特段の理由なく先発医薬品の使用を継続する生活保護受給者につきましては、２月、３月をめどに後発医薬品使用促進相談員、調査員により、後発医薬品を一たん服用していただくよう説明し。","voiceIndex":84,"id":"exchange-025"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区がどういう仕組みで確認するかということは、わかりました。私は、ジェネリックの普及そのものは大切なことだと思います。私が、先ほど伺ったのは、やっぱりどんな薬を使うかは医師の専門的な判断と、患者による選択であって、区民であっても、生活保護の方であっても、ジェネリックの使用が強制であってはならないと思うんですけれども、そこについて、どうお考えなのか伺いたいと思います。","respondent":"竹田生活福祉課長、伊津野品川区保健所保健予防課長","answer":"その処方箋に基づきまして、薬剤師、ご本人の話し合いの中で決まっているものですので、関係者のご意思は反映されているものだと考えております。定期予防接種につきましては、予防接種法により区市町村の事業ということに位置づけられておりますので、そもそも区市町村の財源で行うもので、交付金をもらっている団体につきましては、国からの補助はありますが。","voiceIndex":87,"id":"exchange-026"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"勝手に本人の意思に反して変えることはあってはならないと思うんです。改めて伺いますが、どんな薬を使うかは、医師の専門的な判断と患者の選択によるものだと、よって強制はあってはならないんだと、私は思うんですけれども、そこを伺いたいと思います。ポリオについては、しっかりと国に対してこの財政を求めていくということを、引き続き求めていただきたいと思います。これは要望です。","respondent":"竹田生活福祉課長","answer":"医師の専門的な判断に基づきまして、処方箋に書かれた薬を使用するものです。処方医が後発医薬品の変更可としているものに対して、薬局において、一たん服用していただくようご説明し、ご本人の同意のもとで１回の処方期間を目安に服用していただくものです。","voiceIndex":90,"id":"exchange-027"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"家具転倒防止については、当初予算の想定というのは、もちろんいろいろな考え方があるわけですけれども、しっかりと区民の需要を見込んで位置づけていただきたいと思います。ジェネリックについては、どんな薬を使うかは、医師の専門的な判断と患者の選択によるものだと、そういう説明がありましたので、そこを徹底していただきたいと思います。財源については、国にしっかりと求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-028"}]},{"id":"topic-03","title":"平成２４年請願第１１号、上大崎三丁目「みやこ荘跡地」への特養ホームの整備を求める請願","agenda":"平成２４年請願第１１号、上大崎三丁目「みやこ荘跡地」への特養ホームの整備を求める請願","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"質疑ではないんですが、今ご説明いただきました。我が会派も署名をしておりますので、これはぜひ、こういう形で進めていただきたいと、我々は署名もしていますので、思っております。態度は後で言いますが、そういう感じで、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-029"},{"speaker":"塚本委員","kind":"意見","question":"この請願につきましては、我が会派の幹事長も署名をしています。特に区の財政運営も考慮のうえということで、前提条件はありますけれども、もちろんこれは大事な視点かとは思いますが、基本的には、これはやるという前提での考慮ということで捉えていきたいというか、私どもは、そういうふうに思っておりますけれども、その辺、ちょっとお考えをお聞かせいただければと思います。","respondent":"原高齢者福祉課長","answer":"そういった中で、ここの土地についても、区のほうで、今、国を通じて交渉をしている最中ではありますけれども、そういった意味では、区の条件の中にこういったものが入っているという理解でいるところです。","voiceIndex":106,"id":"exchange-030"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"請願にあるように、大崎地区は一つも特別養護老人ホームがないわけですけれども、特別養護老人ホーム増設を掲げるだけでなく、それ自身は歓迎しますが、地域配置についても、どのように配置をしていくのか、区の方針を定めるべきだと思うんですけれども、この点を伺いたいと思います。検討とは、何を検討しているのか、その中身を伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった中で、特別養護老人ホームの増設は、現状の中で必要という認識の中で、さまざまな形で土地を探しているということで、この間、ご説明させていただいたところです。それから、検討中ですけれども、これは土地ということで相手のある話です。","voiceIndex":108,"id":"exchange-031"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区は購入にあたって、具体的に施設を建設したいから名乗りあげているのではないでしょうかということなので、ちょっとそこが一緒になってしまったので、もう一度、ご説明いただきたいと思います。慣れ親しんだ地域で整えていく、そういう配置の考え方を示すべきではないかと思いますけれども、いかがでしょうか。","respondent":"原高齢者福祉課長","answer":"検討中ですけれども、用地がまだ交渉の段階で、これにしたということはなかなか言えないという意味で、検討中という話になるわけです。","voiceIndex":110,"id":"exchange-032"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"こうした具体的な計画をしっかり示していくということが必要だと思いますけれども、この考え方を伺いたいと思います。そういう事情からも、しっかりと地域にどのように配置をしていくのか、慣れ親しんだところに、それぞれの地域に、また要望が強いところに特別養護老人ホームをつくっていきたいと、そういう方針を示していくべきだと思うんですけれども、いかがでしょうか。","respondent":"原高齢者福祉課長","answer":"特別養護老人ホームはおおよそ３,０００m2、老人保健施設もおおよそ３,０００m2という土地を考えますと、なかなかそこのところを計画に記すということは難しいと捉えているところです。","voiceIndex":112,"id":"exchange-033"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それ自身は歓迎いたします。いつまでにという計画の区の計画をつくるべきだと思うんですけれども、改めて伺いたいと思います。私はやはり、地域バランスを考えた特別養護老人ホームの要望の強いところ、また将来を見込んで、高齢者の住んでいる方が多いところ、こういったところに特別養護老人ホームをつくっていくという方針、考え方をしっかり持つべきだと思うんですけれども、いかがでしょうか。","respondent":"原高齢者福祉課長","answer":"先ほど来、説明していますように、まだ国と交渉中ですので、区の考え方という計画の中で、今回の土地をどう捉えるかということで、まずは高齢者施設、その中でも、特別養護老人ホームと老人保健施設というのは、この間言ってきておりますので。","voiceIndex":114,"id":"exchange-034"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"何だか押し問答みたいなんですけれども、どういうふうにつくっていくのか。これまでも、品川区は跡地活用だけでなく、民間の土地の購入も、当然、検討に入っておりますと言っているわけですから、区の計画をしっかり示すことを持たなければいけないと思います。これからは、どういうテンポで、どういうふうにつくっていくのか、その区の考え方がなければ、私は進まないと思いますが、改めていかがでしょうか。","respondent":"原高齢者福祉課長","answer":"再三の答弁になりますけれども、特別養護老人ホーム、老人保健施設については、条件が整えば、ということで方向性を出して、この間、そういう中で、八潮南特別養護老人ホームも昨年５月、それからその後、杜松小学校跡、平塚橋会館跡、それから、みやこ荘跡地ということで。","voiceIndex":116,"id":"exchange-035"},{"speaker":"若林委員","kind":"質問","question":"みやこ荘跡地、ようやくそういう方向性なったということで、特に高齢者のための特別養護老人ホームを中心に、ということで、こういう請願が出されたということを、議会としても、区民的にも歓迎したいと考えています。これについて、ちょっと考え方を教えていただければと思います。","respondent":"原高齢者福祉課長","answer":"地域のお声です。この間、区のほうは、跡地活用も含め、杜松小学校もそうですけれども、さまざまな形で地域の方のご意見を頂戴しながら、計画、それから、実施に移してきた、そういう意味では、地域の方のご理解とご協力がないと、当然進まないということは前提にしています。","voiceIndex":118,"id":"exchange-036"},{"speaker":"若林委員","kind":"質問・要望","question":"ぜひ、また具体的にそういうお声を聞く場というのはつくって、活用していただきたいと思います。当然、私自身もこの地域でお世話になっている一人なので、ちらちらお声も聞いておりまして、やっぱりどうしても、もともと上大崎ですから、前に１回、総括質疑でやりましたけれども、上大崎というのはああいう場所で、地理的に、また心理的にさまざまな行政サービスが、やっぱり遠いねという地域です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-037"}]},{"id":"topic-04","title":"平成２４年請願第１２号、品川区が購入を決めた国有地（旧みやこ荘跡地）に特養ホームと老健施設の建設を求める請願","agenda":"平成２４年請願第１２号、品川区が購入を決めた国有地（旧みやこ荘跡地）に特養ホームと老健施設の建設を求める請願","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"具体的に聞きます、今のお話。だけれども、平塚橋のときには建て替えなんで、しっかり採算性がとれるベッド数でということで、その部分を聞きたいんですけれども、平塚橋では大体１００床だけれども、それぐらいは取ると、老人保健施設も１００床ぐらいは取ると。もう何度も、これまでいろいろな機会で言っているから、そこら辺の考えを、改めて、今、区の考え方を教えてほしい。","respondent":"原高齢者福祉課長","answer":"現実的には、あそこの中でどのぐらい建てられるかというところから想定しますと、今の特別養護老人ホームと老人保健施設を、旧みやこ荘の跡に両方建てるということは難しいと判断したところです。","voiceIndex":141,"id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"必ず地域の要望、バランス、いろいろな話があって、地域の人は老人保健施設も望んでいる、特別養護老人ホームも望んでいると、それは確かなんでしょうけれども、これから跡地が出てくる問題とか、さまざまいろいろなことがあるときに、やっぱりそこら辺は、必ず採算の合う規模で行えるものは、それは必ず守る。床を減らしてでもやれということは、私は考えるべきではないと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-039"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"特別養護老人ホームと老人保健施設の利用状況について伺いたいと思うんですが、請願にはまだまだ足りないとありますが、本会議の答弁で、若干ありましたけれども、総数について伺いたいと思います。それから、申込み者ですけれども、今年２月時点では５１９人と、以前伺っています。今年８月は６２４人だと、先日、説明がありました。この増加要因を、どうお考えなのか伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった中で、さくら会の定員が１００名ということを考えますと、区内の方が１００名、さくら会を使っていて、残りの方は５００名から他区、あるいは他県を含めて老人保健施設を使っているということで理解しています。","voiceIndex":144,"id":"exchange-040"},{"speaker":"中塚副委員長","kind":"質問","question":"２月に申し込んだ５１９名中７５名が入所できたということになるのでしょうか。しかも、８月では１０５名増え、６２４人ですから、ますます深刻だなと思います。品川区では、どのぐらいの方々が、特別養護老人ホームに申し込みながら、老人保健施設を、３カ月、ないし６カ月ごとに転々とされているのか、そういう人数的な状況というのは把握されていらっしゃるのか、どうお考えなのか、伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"そういったところでは、今回のこの地域もそうです、それから、その土地の中でどういったものが建設可能かということを十分に見極めながら、目標に従って進めてまいりたいと思っているところです。","voiceIndex":146,"id":"exchange-041"},{"speaker":"中塚副委員長","kind":"質問","question":"私は、特別養護老人ホームも、老人保健施設も、一日も早く増設を具体化していく、それぐらい切迫した状況が、家族やご本人に生まれていると思うんです。もちろん運営状況を、全く無視していいとか、そんな乱暴なことを言うつもりはありませんが、家族の状況をどう理解されているのか伺いたいと思います。この状況が、ほんとうに胸が痛くなる思いもするんですよ。","respondent":"渡辺委員長","answer":"中塚副委員長に申し上げます。先ほど来、本請願に関する説明、それの背景等で、副委員長の質疑によってかなり説明もなされたと思いますので、請願に関するものに絞ってお願いします。","voiceIndex":148,"id":"exchange-042"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"この請願に関して、みやこ荘跡地に二つの施設をつくってほしいと、そこには一日も早く増設が求められている実態があるからだと思うんです。増設とは言うけれども、具体的にどう考えているのか、伺いたいと思います。私は、一日も早く増設が必要な実態があると思いますので、みやこ荘跡地についても、こういう角度での検討は行うべきだと思いますけれども、あわせて、いかがでしょうか。","respondent":"原高齢者福祉課長","answer":"そういう中で、今回のみやこ荘跡地についても、どういった施設が可能かというところもあわせて検討する中で、なかなかというところが、現状況で、検討したところの方向性として出たところです。","voiceIndex":150,"id":"exchange-043"},{"speaker":"中塚副委員長","kind":"質問","question":"特別養護老人ホームの入所のしづらさを改善しようという方針が明確にならない。いつまでにどうつくっていくのかも不明確。一日も早い、特別養護老人ホームと老人保健施設の増設が何よりも急がれていると思いますが、改めて、その具体的な方針を伺います。","respondent":"原高齢者福祉課長","answer":"この間、条件が整えば、ということで進めてきておりますので、今後についても、そういった中で捉えていきたいと考えております。","voiceIndex":152,"id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"意見","question":"先ほど、採択したあれもありますけれども、先ほど来、ずっと言っていますように、特別養護老人ホーム、老人保健施設、皆さんがしっかり整備をする、我々もその方向には、もちろん賛成なんですけれども、この請願項目については、特別養護老人ホームと老人保健施設をつくってください、採算のことも考えると、これは願意に沿いがたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-045"},{"speaker":"渡辺委員長","kind":"質問","question":"私のほうから、今定例会の一般質問に係わる所管質問について、ご案内申し上げます。本件は、委員会活動の活性化という観点から、各常任委員会において、当該会期中の一般質問に係わる当該委員会の所管質問を行うものであります。質問をなさりたい委員がいらっしゃいましたら、この場で通告し、翌日、理事者に答弁をしていただくことになります。本会議でのご質問の繰り返しならないようお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3334#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":44176,"voices":172}},{"id":"h24-20120924-8","meetingId":"h24-cm09","date":"2012年9月24日","dateIso":"2012-09-24","committee":"建設委員会","time":"午前１０時００分～午後１時４６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を68件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)第６７号議案 品川区防災会議条例の一部を改正する条例","agenda":"はじめに、(1)第６７号議案 品川区防災会議条例の一部を改正する条例","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"今回、災害対策基本法が改正されたことに伴う改正ということでございまして、地域防災計画への多様な主体の参画が今回盛り込まれたという趣旨だと思うんですけれども、この多様な主体の参画の中で、私たち公明党としましても、女性の参画ということを議会のほうでも質問していますけれども、女性に限らず障害を持たれている方、また外国人の方、高齢者。","respondent":"鈴木防災課長","answer":"ご質問いただきました防災会議に関するさまざまな主体の参画についてですが、基本的には、先ほど申し上げましたように現在の規定でも、委員の構成としまして「区長が必要と認める者」という文言がありますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"浅野委員","kind":"意見","question":"今までもできていたということで、今回はさらに強化される、そういう文言になっているかなと思うんですが、これが出た以上、今後の防災会議の中に、やはりこういう新たな方々を積極的に、また数についても、どうしても男性の人数が多くなりがちな部分がありますけれども、女性の視点というのは、ある意味ではもっときめ細やかなところに目が届くとか、またそういう団体の方々の考えというものも。","respondent":"鈴木防災課長","answer":"ご意見いただきました、さまざまな主体の方々の意見を防災計画に反映するという視点につきましては、区といたしましても重要なことだと考えていますので、今後も今まで以上にそういう方の意見を取り入れて、より実効性のある。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特に女性にしても障害者にしても本当に弱い立場で、ここのところがしっかりと人権が守られる形になることが、みんなが守られるということにつながっていくのではないかと思いますので、ぜひメンバーとして加えていただくということで、前向きにお願いしたいと思うんですけれど、いかがでしょうか。","respondent":"鈴木防災課長","answer":"今後、委員の選定におきましては、そういう視点を入れて検討したいと考えておりますが、現在の防災会議の委員の構成は、定員６１名に対し、５９名ということで枠もいっぱいになってきておりますので、その辺の枠とどの主体の方に参加していただくかというところは。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５９名ということですが、その中に現状で女性の方はいらっしゃるのかどうか、障害者の方もいらっしゃったら、現状について教えていただきたいのと、もう一つは、現在、防災会議はどういう場合に、年間何回ぐらい開かれているのかについて、ちょっとお聞かせいただきたいと思います。","respondent":"鈴木防災課長","answer":"それともう一点、防災会議の開催についてですが、基本的には地域防災計画の改訂の作業のタイミングで、素案なり、確定の部分で会議を開催していますので、定例的に開催をするという形態はとっておりません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今年は防災計画の改訂の年だと思うんですけれど、そういう年に当たっては、どれぐらい会議が開かれ、防災計画を改訂していくのか、その状況と、この品川区防災会議条例を見ますと、「地域防災計画を作成し、およびその実施を推進すること」とあるんですけれども、そういうことでいえば、防災計画を作成したその後、どういうふうにその計画が実施されているのか検証していくというか。","respondent":"鈴木防災課長","answer":"計画作成に関して、防災会議を開催するタイミングですが、現在予定しておりますのが、１１月下旬を目途に、計画改訂の素案の段階で一度お諮りする予定です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それは、議会でももちろんそういう、いろいろ提案とかチェックというのも必要だと思うんですけれど、そういう点では防災会議というのも、少なくとも毎年開いて、どこまで到達をしているのか、さらに到達させていくための、減災目標とかも立てていますし、どういう課題があるのか、それをさらにどう進めていくかというあたりをやることが大事なのではないかと思うんですけれど、そこら辺のところは。","respondent":"鈴木防災課長","answer":"今後につきましては、今回の災害対策基本法の改正の趣旨にも載っておりまして、今後の開催のあり方について、ご指摘のあった視点も含めて、改めて検討してまいりたいと考えております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"須藤委員","kind":"質問","question":"２文字が「あたる」というふうに出ているんだけれど、私は第３条の２項のほうの「充てる」を使うのではないかと思うんですけれど、いかがでしょうか。","respondent":"鈴木防災課長","answer":"申しわけありません。ご指摘いただきましたとおり、第３条のほうの「充てる」という文字が正しいものですので、これは説明資料ですが、早急に直しますので、訂正のほうをお願いしたいと思います……。失礼しました。","voiceIndex":18,"id":"exchange-007"},{"speaker":"須藤委員","kind":"意見","question":"だから、同じ文章をつくっているのに、同じ条例の中で違う「あてる」というので、文章はしっかり統一しておかないと、どちらが正しいのか、正しくないのか、何かあると思うんですよね。私は第３条のほうの「充てる」というのがこういう文章には、人を充てるという形になるので、そちらが正しいんだろうと思うんだけれど、いかがかなと。","respondent":"鈴木防災課長","answer":"それから第５条のほうですが、こちらのほうは委員がこの仕事に「当たる」ということでございまして、これは明確に、意味によって使い分けをしているということになりますので、先ほどの説明は間違いでございました。失礼いたしました。","voiceIndex":20,"id":"exchange-008"}]},{"id":"topic-02","title":"第５９号議案 平成２４年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第５９号議案 平成２４年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２１ページの温暖化対策事業からお伺いしたいんですが、この省エネルギー設備導入助成と太陽光発電システム設置助成が、第１期申請でそれぞれ何件ぐらいずつあったのかお聞かせいただきたいのと、今回２０件ずつ補正を組みましたけれども、この補正を組んだ理由についてもお聞かせいただきたいと思います。なぜ２０件かということもお聞かせください。","respondent":"野呂瀬環境課長","answer":"それぞれ１期と２期を組んだ理由ですけれども、設置の予定がある方は、申請が４月から５月末ということで１期にしておりますので、それ以降に計画をされる方についても、チャンスを与えるというか、設置していくということで、この理由で組んでいます。","voiceIndex":46,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで太陽光では２３件オーバーしてしまっているわけですよね。そうすると、その分でこの２０件は終わってしまうのかなと思うんですけれど、今期の分で同じように１０件、３０件という形で組まれていると思うんですけれど、それがまた１期分と同じような形で２０件ぐらいずつオーバーしたとしても、それは認められるという考え方でいいんでしょうか。","respondent":"野呂瀬環境課長","answer":"昨年も、２期でオーバーした分については要綱どおり抽選をいたしております。ですから今回も昨年どおり、１期分も予定件数をオーバーしていますので、要綱ではその１期分につきましても、本来でしたら抽選という形です。","voiceIndex":48,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"後期に申し込んでオーバーしてしまった分は抽選で、昨年はどれぐらいの方が抽選から外れて、申し込んだけれども受けられないという方がいらっしゃったんでしょうか。","respondent":"野呂瀬環境課長","answer":"手元にちょっとないのですが、多分数件だったと記憶しております。","voiceIndex":50,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことであれば、２期分も抽選という形にしないで、申し込んだ方は同じように認めるという形にぜひしていただきたいと思うんですけれど、それがなぜできないのか。そういう中で、これは、本来であればもっともっと推進していただきたいと思うんですけれど、いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"ですからほかの設備につきましても、できるだけやりくりの中で、温暖化対策事業の補助金の中でやりくりできるようにしますし、ほかのところでも流用等でやれるような助成額であればいいんですけれども、１件について４０万円、２件だと８０万円。","voiceIndex":52,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"エネファームというのは私はよくわからないんですけれど、ぜひそれは積極的に、区のほうとしても、申し込んだ方が受けられるような形で、取り組んでいただけるようにお願いしたいと思います。だからそういった意味では、ぜひ通年で申し込みができるような仕組みにして、これを本当に積極的に進めていただきたいと思うんですけれど、そこはいかがでしょうか。","respondent":"野呂瀬環境課長","answer":"そういうのもありまして、今のところやはり１期、２期で、公平性ということで分けているという考え方の中でやっております。","voiceIndex":54,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひとも大枠そのものを増やしていただいて、通年で申請を受け付けて、太陽光などを品川区の中でどんどん増やすということで取り組んでいただきたいと、大枠を増やして取り組んでいただきたいと思うんですけれど、いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"それと、特にまたほかの区でも財政難とか、環境行政としても補助金だけでやっているのが、いろいろな環境行政で予算を振り分けなければいけないと、いろいろありますので、補助金額はそれはそれで、その中で地域の特性を鑑みながら検討を加えて。","voiceIndex":56,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に、自然エネルギーをもっと爆発的に増やすということが、政策としても必要だと思うんですね。そういった意味ではぜひ枠を増やして、希望の方がどんどんつけていけるということで、区としても取り組んでいただきたいということで、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-015"},{"speaker":"浅野委員","kind":"質問・要望","question":"私からは、多分ほかの委員からも聞きたいところがあるかと思うんですけれども、都市計画費の中から２つあるんですけれども、特定整備路線計画推進費と、その下にあります荏原町駅前地区防災街区整備事業補助金の２つについてお聞きするんですけれども、特定整備路線計画推進費で補助２９号線と放射２号線の２つ入っているんですけれども、これは費用としては、１,２６０万円と一括に出ているんですが。","respondent":"藤田都市計画課長","answer":"それにあわせまして、区のほうとしてできる検討を進めようということで、一つは沿道のまちづくり、これについて検討していくということと、もう一つは都市計画の手法の中で、用途地域ですとか容積率、この辺の見直しも合わせて考えようということで。","voiceIndex":59,"id":"exchange-016"},{"speaker":"浅野委員","kind":"質問","question":"では一つ一つということで、特に放射２号線というのは補助２９号線よりも遅れてというんでしょうか、前にもちょっとお伺いした件なんですけれど、地元の方がこの放射２号線というのをどこまで理解をされていたのか、また今現在いるのかということと、これを知っていて、例えば建物を建てるときに、そこに当たらないような形で建てたとか、そういうようなことが過去にあったかどうか、この点お伺いします。","respondent":"藤田都市計画課長","answer":"放射２号線ですが、こちらにつきましては都市計画道路の優先整備路線ということで、既に平成１６年の段階で、今後１０年間の間に都市計画道路として整備を進めていくということに指定をした路線です。","voiceIndex":61,"id":"exchange-017"},{"speaker":"浅野委員","kind":"質問・要望","question":"もう一つ、荏原町駅前地区防災街区整備事業補助金の件ですけれど、こちらは経費を助成するというふうに伺っていたんですが、４,０００万円という中身について、ちょっと教えていただきたいと思います。","respondent":"品川防災整備担当課長","answer":"それから権利者の皆さんがやります建物等の資金計画費作成が１,５００万円かかります。これが計６,０００万円になります。このうちの３分の２を補助するものです。","voiceIndex":63,"id":"exchange-018"},{"speaker":"浅野委員","kind":"意見","question":"３分の２ということで、３分の１はまた翌年度という計画、予算に入ってくると思うんですけれども、ここまで来た事業で、皆さんも少しずつといいましょうか、前向きに検討されて、業務も進んでいくかと思いますので、ぜひとも早期に、こちらは大きなプロジェクトでありますし、また防災上にも大きな役割を果たすと思いますので、滞りなく進められるように、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-019"},{"speaker":"須藤委員","kind":"質問","question":"区がやろうとすることの前に、調査・検討する前に、まちの人たちへ説明が必要だと思うんですけれど、そのあたりはいかがでしょうか。","respondent":"藤田都市計画課長","answer":"補助２９号線等を進める上で、今後どのように地元のほうに説明していくかということは、大きなお話だと思います。","voiceIndex":66,"id":"exchange-020"},{"speaker":"須藤委員","kind":"質問","question":"ですから、これから東京都が、今言ったこれからの生活支援体制を含めての検討もきちんとこういうふうにやっていくんだよ、ですから区としても連携して説明に入りますという、事前の説明をしておかないと、東京都が説明するのを待って、我々がそれから調査・検討に入りますみたいな話ではなくて、地元なんだから、地元としてやることは何かというと、やはり東京都からこうなって。","respondent":"藤田都市計画課長","answer":"その情報が少しでも入れば、また地元に対して説明をしていけるのですが、新たな情報が今の段階ではないので、東京都のほうからいち早く情報収集に努め、地元への説明がスムーズにできるようなことは、この後も検討していきたいと考えています。","voiceIndex":68,"id":"exchange-021"},{"speaker":"須藤委員","kind":"質問","question":"それが私はやはりよくないと思うので、今、東京都が精査している、また詳しい話はこう来るけれども、我々がわかっている範囲ではここまでですよと、何月ごろに来る話になるので、そのときは東京都と我々が一緒になって説明にあがりますというような、事前の説明はしておくべきだと思うのだけれど、いかがですか。","respondent":"藤田都市計画課長","answer":"そういう中で、次のステップの説明についても、また検討していかなければいけないと考えています。","voiceIndex":70,"id":"exchange-022"},{"speaker":"須藤委員","kind":"質問","question":"その前に、こういったことでまちの安全のためにこうなんですよという話は、それなりの町会なり商店街なりに、まちづくりの会合があるからそこで説明しますという消極的な立場でなくて、皆さん方がやはり説明に入っていくべきだろうと。我々も地元の人たちにそういう話をさせていただいているけれど、しっかりと行政側からそういう説明をすべきだろうと思うんですけれど、今の考え方はだめなんですかね。","respondent":"片田都市環境事業部長","answer":"おそらく年明けになってくると思いますけれども、東京都のほうと十分連携をとって、東京都といっても第二建設事務所が中心になってくると思いますけれども、地元のほうに説明に入っていくと。","voiceIndex":72,"id":"exchange-023"},{"speaker":"須藤委員","kind":"質問","question":"そういうのを待っていたのでは遅いのではないですかと。そうでなくて、固まってから、はいといったら、そこでいろいろなものが出てしまうから、その前に、新聞でこう出たけれど、実はこれはこういう防災のために、品川区のまちづくりで前から、東京都で計画されていたものが実際に出てきた話なんだというぐらいは、しておいてあげていいと思うんですけれど、いかがですか。","respondent":"山崎マスタープラン担当課長","answer":"地元のほうのまちづくりの関係につきましては、自主的なまちづくりへの支援ということもやっておりまして、実際に戸越公園の駅の周辺で、５町会２商店街等で構成されているまちづくり協議会があります。","voiceIndex":74,"id":"exchange-024"},{"speaker":"須藤委員","kind":"質問・要望","question":"補助２９号線は非常に長い路線で、いろいろな町会があり、商店街も入ってくるので、個々に云々するのは大変だけれど、一回、町会長や商店街に区が顔を出して、こういう状況なのでまた改めて説明にあがりますから、そのときはまたお集まりいただきたいとかいう話だけでも流しておかないと、今やっている、今やっている、できてからというと、ますます不安の声がいろいろ我々に入ってきてしまうので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今のお話ですと、政策の公表が１１月末で、年明けからの説明に東京都としてはなるのではないかということですけれど、それでは今回のここの補正で組まれた調査そのものも、その後から調査に入るということでいいのかということと、この調査そのものが沿道まちづくり調査、沿道土地利用のあり方とか、用途地域、容積率の見直し検討経費ということですけれど、具体的にどういう調査になるのか。","respondent":"藤田都市計画課長","answer":"都市計画道路、今回は２０メートルの道路ですけれども、１２メートル以上ありますから、一定程度の延焼遮断効果はありますが、それにあわせて地域の沿道部分の不燃化を進めることで、さらなる延焼遮断効果が見込めるです。","voiceIndex":77,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前段の基礎的な調査というのが、具体的にまちに入って、まちの方々とかかわりながら調査をするという、そういう中身になっていくんですか。それから、これそのものは、区の一般財源ということでの１,２６０万円になっていると思うんですけれど、都道であるにもかかわらず、東京都からの財源ではなくて、品川区からの財源というふうになるのはなぜなのかということを一つ教えていただきたいのと。","respondent":"藤田都市計画課長","answer":"お示しになりました図面等については、結構大きな建物のイメージになるかと思いますけれども、今回の補助２９号線の場所、まちのでき上がり、その辺については、今後の用途、容積率のあり方を検討する中で、十分に議論すべきと考えています。","voiceIndex":79,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"木造建築物の棟数率が７０％以上とか、老朽木造が３０％以上とか、そういうのが幾つかあると思うんですけれど、そういう木密というところから考えたとき、この補助２９号線、放射２号線というのは、木密の地域が何％ぐらいあると、区としては見ていますでしょうか。木密に当たらないところもあるのではないかと思うんですけれど。","respondent":"藤田都市計画課長、品川防災整備担当課長","answer":"ちょっと細かいことは別にして、まず木密地域不燃化１０年プロジェクトについては、もともと先ほどのお話にもありました木造住宅密集地域整備プログラム等の中で、具体的に数値が示された、木造建築物の棟数だとか老朽木造。補助２９号線、放射２号線につきましては、東京都が決めております整備地域内にすべて入ります。","voiceIndex":81,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。もう一つお伺いしたいのは、特に補助２９号線ですけれど、これは今までの経過からしても、昭和５１年、昭和５９年、平成１４年と３回にわたって区議会に地域から、この都市計画道路を廃止してほしいという請願が出されて、全会一致でそれを採択して、東京都に廃止を求める意見書を、区議会として３回ほど上げてきたと。","respondent":"藤田都市計画課長","answer":"区のほうとしても、先ほどお話がありました平成１４年の段階で、ちょうど第５回の地震に関する地域危険度測定調査の発表がございました、その際に、非常に区内に危険な場所が多いということもございましたので、区として改めて、その当時第三次の事業化路線ということで。","voiceIndex":84,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうことでもう一つ、先日の本会議の中でも取り上げたんですけれど、阪神淡路大震災のときにそういう道路が延焼遮断帯になったということから、延焼遮断帯として進めていくんだということですけれども、それに対して車両火災の危険性はどうしても、道路をつくると車が必ず出てくるわけですから、そこら辺の危険性というのは考えないで進めるというのは、私はちょっと無謀だと思うんですね。","respondent":"藤田都市計画課長","answer":"本会議の答弁の繰り返しになりますが、定量的な評価が今のところ技術的に確立ができていないために、今回、その中での検討をしなかったという結果になっているです。","voiceIndex":86,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"実際に安全のためだということで道路を通して、地震当日ということでいえば、阪神淡路大震災のときは午前５時何分ですから、ほとんど車が通っていなかった時間帯もあって、でもその中でもかなり車両火災の報告はされているわけですよね。その辺についてはいかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"都市計画道路としての基本的な考え方には幾つかございまして、まず私どもがずっと進めてきました都市計画道路の考え方は、交通ネットワーク、まちをつくる際に道路という基盤をまずつくるです。そういった意味での都市計画道路があります。","voiceIndex":88,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"避難や延焼遮断効果、歩道のところは避難ということで使えると思うんですけれど、多分車両のところは、阪神淡路大震災の文献を読んでも、車であふれかえり、朝の地震の時点では車はそうでもなくても、その後はもう本当に車であふれかえって、身動きがとれないような状況になったということなんですね。だからそういう点では、私は道路ができれば、そこで……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それと、この間ＮＨＫスペシャルでも、７００メートルも火の粉が飛んだり、２０メートルの道路だと輻射熱で、本当に５秒ぐらいで焦げ始めるというのをやっていて、区長は「それは一人の学者が言ったことです」と言われましたけれど、そういうふうにＮＨＫでも報道されたことに対して、区としてはどう考えられて、こういう計画をつくっているのかというあたりを、改めてお聞かせください。","respondent":"片田都市環境事業部長","answer":"仮に万が一道路の中で火災があったとしても、その火災が周辺には飛び散らない、火の粉としても、輻射熱等の影響ももたらさないといったような遮断効果を期待して、周辺のまちづくりをあわせて、道路等とは別に、区としてはまちづくりで検討していくと。","voiceIndex":91,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それに加えて、線から面にということで沿道の高い建物の開発をしていく、その開発にも補助金を入れていくとなると、今度、大井一丁目の開発にも税金が入っていくと思うんですけれど、そういう形で進めていくと、一体この道路は、延焼遮断帯として輻射熱も飛び火もさせないほどの高い建物をつくって、安全な燃え広がらない町をつくるという計画に対して、どれぐらいの税金が使われていくと考えられているのか。","respondent":"藤田都市計画課長","answer":"１,３００億円、これについて私どものほうでは根拠がわかりませんが、この後いろいろな検討を進めていく中で、東京都のほうが今、生活再建のための支援策の検討をしておりますが、その支援策がどういう中身になるかによって、東京都が税金を使う部分があるのかないのか。","voiceIndex":93,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この１,３００億円というのは、例えば補助４６号線が６００メートルで幾らかかって、１メートル当たり幾らと、そういう計算から引き出したものなので、多分ここはもっと支援策を、あそこは６００メートルが２１年間かかってできていますから、それを今回はこれだけの長さを、８年とか７年とかでやっていくというところですから、もっともっとたくさんのお金がかかっていくと思うんですね。","respondent":"藤田都市計画課長","answer":"延焼遮断帯をつくることだけで木密地域の不燃化を実現していくというものではございませんので、この中の枠組みである不燃化特区ということで、先般、先行実施地区が決まりましたけれども、この後、本格実施の地域についても検討を進める。","voiceIndex":95,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"荏原町駅前ですけれど、荏原町駅の沿道というのは高くて８階、多くが３階から４階というところで、１７階、６４メートル、その２倍以上の建物というのは、本当に高すぎると思うんですけれど、事業採算性ということでの答弁だったんですけれど、今回建て替えるに当たって、今回は地権者の自己負担はなしで建て替えることになるということから、１７階になるのかということが１つと、それから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから荏原町のところだけ聞きます。例をただ言っただけですから。荏原町駅がこれからも、この６０メートルを皮切りに、６０メートル級のビルが建つことになっていくのか、そこら辺も含めてお聞かせいただきたいと思います。","respondent":"品川防災整備担当課長","answer":"１点目のご質問ですが、荏原町駅前は現在の防災街区整備事業で地権者の自己負担ということですが、現状としては負担がないというような状況でありますが、また個々の権利返還等をやっていく中で、もしかしたら出る可能性はあるというふうに考えております。","voiceIndex":98,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これからも６０メートル級が建つということですか。","respondent":"品川防災整備担当課長、片田都市環境事業部長","answer":"これからも６０メートル級のビルができるかですが、基本的には高さ制限というものがございませんので、できないというふうにはお答えはできないかと考えております。ですので、やはり地域の皆さん、２０人ぐらいいらっしゃいましたけれども合意形成の中で、そういうまちづくりを、これまでもずっと勉強会をやって、考えてきたところもありますので。","voiceIndex":100,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ただ、その老朽化した店舗が支援を受けて、建て替わった後にどれぐらいの店舗が戻ってくることになるのか、その割合とか何かがわかったら、お聞かせいただきたいと思います。","respondent":"品川防災整備担当課長","answer":"現在店舗をやっているところがどれだけ戻ってくるかというご質問ですが、現在いろいろ、権利返還と地権者の皆様がこれからどうしていこうかということを考えている状況ですので、現在のところどうなるかは把握しておりません。","voiceIndex":103,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私、ちょっと地元の方に聞いたところでは、戻ってくる店舗というのは本当にわずかしかないということを伺ったんですね。そうすると、テナント貸しみたいな形になってしまうことになると、今までの荏原町商店街が、本当にさま変わりしてしまうのではないかと思ったんです。","respondent":"品川防災整備担当課長","answer":"当然のことながら、商店街に関して一番考えて、この計画は立てているところです。今後も、この地区にビルが建つということで、商店街の連続性ですね、ここら辺を一番重視して、現在計画のほうを進めている状況です。","voiceIndex":105,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"とはいっても、ほとんど戻ってこないとなると、やはり入ってくるのはチェーン店とか大型店になってしまうのではないか、そういうのが拭い切れないんですけれど、そこのところは、こういうふうにしていくから大丈夫だというのがあったらお聞かせいただきたいのと、もう一つは、６４メートルなのでかなり高い建物が、あそこら辺にはちょっと考えられない建物という感じなんですけれど。","respondent":"品川防災整備担当課長","answer":"１点目ですが、ほとんどの方が戻ってこないという前提のもとにお話をされているようですが、まずその状況を把握していませんので、戻ってこない中で商店街がどうなるのかという議論は、さすがにこれはコメントとしてお答えできないという状況です。","voiceIndex":107,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"もう一つ、ここの説明を見ていましたら、防災公共施設というのがあったんですけれど、それはどういうものができるのかということと、駐車場が地下にあると思うんですけれど、この駐車場は居住者のためのものということで考えていいのか。それと駐輪場とかも、ここら辺はすごく駐輪場がないので……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"でもどういう建物かがわからないと、どういうふうに予算を評価していいのかわからないじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"６割。そうですか。税金がどれぐらい入るのかという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"補正の部分では３分の２ということですけれど、総事業費からいえば３割になるということ、それがおおよそ総事業費、今回の補正はわかりましたけれども、おおよそどれぐらいになるかということも、あわせてお聞かせいただきたいと思います。","respondent":"品川防災整備担当課長","answer":"申しわけございません、現時点では計画段階ですので本当にアバウトで、やはり補助金のほうが全体の３０％程度、今回の補正に関しましては、３分の２を補助というような形で進めております。","voiceIndex":117,"id":"exchange-045"},{"speaker":"須藤委員","kind":"質問","question":"今の荏原町駅前ですけれども、地権者の商店街の皆さんと話しまして、今お話があった、ある程度高さが出てくると。私が聞いている範囲では、あそこがポンとあいちゃう、商店街と連続性がなくなっちゃうということではなくて、今後の荏原町商店街の発展につなげるような仕組みをみんなで考えていこうというような話を、私は聞いたんですけれども、課長はどうでしょうか。","respondent":"品川防災整備担当課長","answer":"まさに委員がおっしゃるとおり、この荏原町商店街は非常に活気のある商店街です。こういった活気のある商店街を、活気をなくさないような形で、共同建替えのビルのほうは進めていき、なおかつ商店街の一体性、これを非常に重視した形で、今後進めていきたいと考えております。","voiceIndex":119,"id":"exchange-046"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほどマスタープランのほうで、いろいろなことで産業振興とかその辺と連携をとっていますというお話なので、ここについても産業振興のほうと連携をとりながら、商店街の意向とか地権者のほうでは建替え中の店舗をどこにしたらいいんだろうとか、そういう悩みを持ってきておりますので、そういうものも連携しながらやっていくと、この地域ならどうだとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-047"},{"speaker":"沢田委員","kind":"質問・要望","question":"それが、どこが正確で不正確かということは、ちゃんと区のほうでそれを受けてちゃんと説明を、なおさら地域にやっていただきたい。ということを早急に、もう３カ月もたっているので、やっていただきたいということを、要望として言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"別の件ですけれど、２３ページの住宅改善工事助成のことをお聞かせいただきたいんですが、エコ・バリアフリーとＬＥＤは、計画に対して今までどれぐらい実績があるのかということと、今回１,３５０万円が当初予算で組まれたと思うんですけれど、もう既に使い切っている状況なのか、それであれば、いつごろまでに使い切るような状況だったのかということもお聞かせください。","respondent":"大串住宅担当課長","answer":"で、助成額ですが、これはまだ予定のものも含んでいる数字ですが、２,２３７万５,０００円ということになっております。先ほど委員のご指摘があったように、当初予算は１,３５０万円ということで、基本的にこの当初予算は既に終わっているという状況です。","voiceIndex":123,"id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これについては建設業組合からもすごく切実な要望があって、区としても今年拡大をしていただいて、それがすごく好評でこういうことになっていると思うんですけれど、これは本当に、建設組合の皆さん方の仕事確保という点でも有効なのではないかと思うんですけれど、あと５０万円というのはあまりにも少ないのではないかと思うんですが、何とかもうちょっと補正を。","respondent":"大串住宅担当課長","answer":"こちらの制度につきましては来年度以降も、どういった形で継続をしていけるかといったところは考えながら、今後は進めていきたいと考えております。","voiceIndex":125,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この１５３件ということですが、エコ・バリアフリー等とＬＥＤがそれぞれ何件だったかということを教えていただきたいのと、２,２３７万５,０００円ということですけれど、これだけの助成をされる中で、どれぐらいの経済効果があったのかというところも教えてください。","respondent":"大串住宅担当課長","answer":"内訳ですが、ＬＥＤの設置工事が７４件です、で、それ以外の工事ということで９６件ということで、合計１５３件という数字になります。","voiceIndex":127,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当にこの不況で、仕事確保という点からも本当に切実な要望として出されていましたので、そして今聞いても経済効果は１０倍以上あるということですよね。２,２３７万円の助成に対して２億円ですから。","respondent":"大串住宅担当課長","answer":"先ほどの答弁の繰り返しになりますが、一旦ここでは申請については終了としますけれども、こういった形で経済効果がかなり出ているということが実証されましたので、来年度以降につきましては、これを継続する方向で、検討を進めていきたいと考えております。","voiceIndex":129,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"反対です。理由を述べたいと思います。さらにこれを充実させていただきたいということで、要望させていただきたいと思います。それから荏原町の予算に対しても、木造密集の解消ということでは本当に支援をしていかなければならない、本当に重要なことだと考えておりますけれども、いかんせん１７階というのは荏原町の駅にはふさわしくないということで、この予算に対して反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-053"}]},{"id":"topic-03","title":"２の報告事項、(3)武蔵小山駅周辺地区のまちづくり","agenda":"２の報告事項、(3)武蔵小山駅周辺地区のまちづくり","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"説明会が２４日、２５日と２日間にわたってされたんですけれども、多くの出席者も出たんですが、この１日目、金曜日の夜と、土曜日の出席者は、それぞれまるっきり違う人たちが出ているのか、ダブって話を聞いている人がいらっしゃるのか、そのあたりをお聞かせください。","respondent":"溝口都市開発課長","answer":"出席者につきましては、基本的に両日とも別の方、中には多少、両方とも出られた方がいるというふうに聞いておりますが、基本的には別々の方、両日かぶらずに出席された方が多かったと聞いています。","voiceIndex":152,"id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"自転車のことをちょっとお伺いしたいんですけれど、この自転車ゾーンを設けることについて、この辺は放置自転車も多く、自転車を使ってパルム商店街に行く方もいっぱいいらして、いろいろな問題等もあるみたいなんですが、その辺の対応に関してお聞きしたいと思います。","respondent":"溝口都市開発課長","answer":"駐輪場の整備の件のお尋ねです。今回先行しておりますパルム、今回追加するＢ地区の開発計画の中では、買い物客ですとか、そういった商店街を利用される方の駐車場の整備を計画しておりますので、そちらで開発時に駐輪場等の対応をしていきたいと考えております。","voiceIndex":154,"id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"先にお話しいただきました駐輪場に関しては、新たに駐輪場スペースを設けるのでしょうか。","respondent":"溝口都市開発課長","answer":"新たに開発する施設の中に、駐輪場を整備するという形になっております。","voiceIndex":156,"id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つは、今回Ｂ街区に加えてＡ街区も１４５メートルまでの高さが建てられるという変更という報告なんですが、説明会の中でも、１４０メートル級の建物がどれぐらい建つのかということに対して、４棟建つという回答だったんですけれども、その４棟というのは、このＢ街区、Ａ街区、それに加えて、どこにどう建つのかということも教えてください。","respondent":"溝口都市開発課長","answer":"これも同一の準備組合が立ち上がっておりますので、準備組合としては合計３つなんですけれど、地区としては４つ。その４つの地区に、１４０メートル級の建物が建つであろうという想定で、街並み誘導指針は４棟、建物を示しているものです。","voiceIndex":158,"id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つは、今回１４０メートル級が４棟というので、あの武蔵小山に１４０メートルが４棟かと思うと、うわっという思いが私などもしてしまうんですけれど、それに加えて、もともとの街並み誘導指針の中にもスカイラインをあわせて６０メートル、ここにも６０メートルまたは４５メートルということが書かれているんですけれど、６０メートル級のビルというのは。","respondent":"溝口都市開発課長","answer":"今後のパルム商店街周辺のまちづくりについてのご質問ですが、具体的に６０メートルが何本で、４５メートルが何本という形での計画はまとまっておりませんが、聞くところによると、商店街の中でもそれぞれ今後の商店街の活性化を図るために、共同化ですとか。","voiceIndex":160,"id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、品川区が誘導して１４０メートル級のこういうマンションが建設されていくことになっているのだと思うんですけれど、そういうことでいえば、この街並み誘導指針、武蔵小山駅周辺のビジョン、これについてはやはり地域の住民に対しての説明会を、今からでも私はすべきだと思うんですけれど、これからのまちづくりにかかわっていくことなので。","respondent":"溝口都市開発課長","answer":"これにつきましては一般質問等でもありましたように、策定段階で、アンケートをとったり、また商店街ですとか町会、そういった方たちのご意見を聞きながら策定したものでありますので、改めてこれについて区としてご説明する考えはございません。","voiceIndex":162,"id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、１４０メートル級の建物がこれからどんどんでき、また４５メートル、６０メートル、その間というのも、６０メートルが限度だから今のところはできないですかね、そういう形で大きく武蔵小山のまちが変わっていくわけじゃないですか。ぜひともしていただきたいと思うんですけれど。","respondent":"溝口都市開発課長","answer":"これまでと同様になりますけれど、策定段階で十分にアンケート等をとりながら進めてきたものですし、個別の建物、１４０メートル級の建物を建てるということであれば、当然、市街地再開発事業等になると思いますが、その際には、任意ではありますが当然。","voiceIndex":164,"id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"アンケートをとったことで区民に意見を聞いた、また区民に説明したということにはならないと思うんです。区が言うようにアンケートをとりましたということであれば、その結果をどう評価してこういうビジョン、誘導指針をつくったかということを改めて、アンケートのお返しという点でも私はやるべきだと思うので、ぜひともしていただきたい。","respondent":"溝口都市開発課長","answer":"まちづくりビジョンおよび誘導指針の説明についてですが、できたものをホームページで公開し、皆さんがごらんいただけるような環境をつくっておりますので、そちらで十分説明はさせていただいている、また繰り返しになりますけれど、当然。","voiceIndex":166,"id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何で高い建物ができたのかという質問に対して、品川区の誘導指針によるものですということで言われているだけですから、それでホームページに載せているというだけでは区の説明にはなりませんので、私は改めて住民の中に区が入って、住民の意見も聞きながら、そして説明会もやるという、これだけのまちをこれだけ変えていくわけですから、ぜひともそういう形でやっていただきたいと。","respondent":"片田都市環境事業部長","answer":"ただ、誤解されては困るのは、この１４０メートルという建物は、いわゆる街並みの方針の中で、区のほうとしては、それぞれの地域の権利者が自分たちのまちをどういうふうに考えていこうかということで、アッパーを規制しているということはありません。","voiceIndex":168,"id":"exchange-062"}]},{"id":"topic-04","title":"大井一丁目南地区第一地区再開発計画に関する都市計画案","agenda":"大井一丁目南地区第一地区再開発計画に関する都市計画案","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この１枚目の３番の説明会のところで、この計画に参加できない場合には強制執行で立ち退きを要求されるのかというものに対しては、全員合意ができるように進めていきたいという答弁をしたということなんですけれども、賛成者がどれぐらいいるのか、この計画に対して反対をしている、反対、賛成の数をちょっと教えていただきたいと思います。","respondent":"溝口都市開発課長","answer":"本都市計画案に関する賛否ですが、必ずしも一致しないところもありますが、準備組合の参加加入率としては８１％の方が加入されています。全員が賛成という形ではありませんが、そういったところでおおむねの合意が得られているというふうに考えております。","voiceIndex":175,"id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"店舗を借りながら営業しているという方はどれぐらいいらっしゃるのかということと、そういう方には説明はされているのかについてもお聞かせいただきたいと思います。","respondent":"溝口都市開発課長","answer":"今回の説明会につきましては、あくまでも土地所有者、借地権者を対象に説明したものであります。","voiceIndex":177,"id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう区民一般ということではなくて、ここで営業されている方が、その後の生活がどうなっていくのかというふうに、それはすごく大事なことなのではないかと思うんですけれど、営業の継続がどういうふうにできていくのか、そこにどう責任が問われ、責任を負う仕組みになっているのか、そこら辺のところをお聞かせいただきたいと思います。","respondent":"溝口都市開発課長","answer":"これにつきましては都市開発法の中でもしっかり権利として守られておりまして、今後、施工者、この場合ですと準備組合から組合に変わった段階で組合のほうでしっかり、例えば借家権者の方がどこか移転したり、ほかに出たいということであれば、必要な補償をしていきますし。","voiceIndex":179,"id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、先ほどの準備組合への加入率は８１％ということですけれど、その中で、この開発に対して賛成をしているかどうかというのはとられていないのか、とられていたら教えていただきたいのと、もう一つは、今回、高さが１０４メートルの容積率が６５０％ということで、かなり大きな建物になっていくわけですけれど、これだけの容積率、高さというのを今回決める基準というのは。","respondent":"溝口都市開発課長","answer":"これにつきましてはオール東京都２０の中で指定基準というものが定まっておりまして、その中で空地にする評価ですとか、住宅に対する評価といったものを勘案して、実際に今回でいきますと、用途地域の変更をしまして４００％に容積率を上げまして。","voiceIndex":181,"id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、例えばこの道路が、幅１５メートルでしたか、それだけの幅がなくて、例えば８メートルとかそういう幅でも、これだけの建物とか容積率というのは関係なく、道路幅とは全然関係なくできるという、そういう基準になっているんでしょうか。基本的なところですが。","respondent":"溝口都市開発課長","answer":"これにつきましては当然周辺基盤の整備、また地区内の道路の整備、そういったものを勘案して４００％に変更しているものです。","voiceIndex":183,"id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"細かくてすみません。ではこの４００％に緩和したというのは、地区内の道路の整理ということで補助１６３号線のことがあるという、そういうことでいいんですか。","respondent":"溝口都市開発課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":185,"id":"exchange-068"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4050#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":49753,"voices":191}},{"id":"h24-20120924-9","meetingId":"h24-cm09","date":"2012年9月24日","dateIso":"2012-09-24","committee":"文教委員会","time":"午前１０時０２分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を81件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第６３号議案 品川区保育の実施等に関する条例の一部を改正する条例（品川区立保育所における延長夜間保育等に関する条例の一部を改正を含む）","agenda":"の第６３号議案 品川区保育の実施等に関する条例の一部を改正する条例（品川区立保育所における延長夜間保育等に関する条例の一部を改正を含む）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そのあたりをちょっと伺いたいと思います。それから、あと値上げは待機児対策で増設してきたために運営費が高くなったからと、本会議でそういうようなご答弁がこの間あったと思うんですけれども、９年前ですか２００４年に値上げをしたときの当時の議事録をちょっと読んでみたら、運営費はその当時８７億１,３００万円かかっていて、区の負担率は７４.７％というふうに説明されているんですね。","respondent":"立川保育課長","answer":"国基準の保育料は区では現在、Ａ階層、Ｂ階層、Ｃ階層が３区分、Ｄ階層が２３区分で、合計２８区分の階層で家計に与える影響等を考慮しまして、きめ細かく実施しております。国は８階層です。","voiceIndex":16,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"所得税のところはちょっと最初の課長さんのご説明自体がちょっと理解できなかったので、申しわけないですけど、もう一度お願いしたいと思ったんですけれども、ちょっとそれは後に回しまして、保育料のＤ１６の部分を伺いたいと思います。こういうところは経済的負担は大きくないのかというと、そうではないというふうに私は思うので、その辺の考え方について改めてちょっと伺いたいと思います。","respondent":"立川保育課長","answer":"６０％を目指す今後の改定ですが、現在のところ改定の予定はございません。保護者への説明会につきましては、今回の改定は比較的所得の高い方にご負担をお願いすることですので、説明会の実施は考えておりません。説明については広報、個別の通知等でお知らせしていく予定です。","voiceIndex":18,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"先ほど質問したところなんですけれども、区の負担というのは７８％でしたっけ、そういう状況なので値上げをするよということなんですけれども、値上げをしてもわずか３,６００万円、負担はなかなか解消というふうには、重たい負担が続くというふうに思うんですけれども、なぜ自治体にそういう負担がどさっとかかってきているかというこの原因は、やはり国が一般財源化してしまって。","respondent":"立川保育課長","answer":"現在、保育園運営費の国の負担につきましては一般財源化。平成１６年まではいわゆる基準額に対しまして国が５０％、都が２５％、区が２５％。区は上乗せの運営費というものを乗せております。平成１５年までです。","voiceIndex":20,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"国が全く保育事業に対して責任を感じないというか、責任をしっかり受け止めずに逃げ続けてきていると私はそういうふうに思うし、区としては特別区長会を通じて負担金の要望をしているというお話ですけれども、現実的には限りなく際限なく負担が区のほうのしわ寄せになっているという状況ですよね。ちょっとその辺の見解を多分議論されてきていることだと思うので、その辺についてとりわけ伺いたいと思います。","respondent":"金子子ども未来事業部長","answer":"南委員のおそらく長期基本計画あるいは総合実施計画における子育て家庭の経済的負担の軽減というところの項目についてのご質問だと思います。","voiceIndex":22,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"そういう方々に社会的な資本を整備するために税金を払っているのに、そこによって払うことが継続できていることによって、あなたは保育園にお金たくさん使っているんだから、いっぱい保育園建てているんだから、お金が足りなくなってきているから負担しろなんて、こういう理論がまかり通るでしょうか。理解できるでしょうか。私はそういうふうに思いますけど、その辺の見解はどうですか。","respondent":"金子子ども未来事業部長","answer":"最前から申し上げているとおり、待機児童対策についてはこれまでも十分充実してまいりましたけれども、今後とも拡充については対応していく考えでおりますので、この段階において負担増をお願いして、引き続き子育て支援、各方面。","voiceIndex":24,"id":"exchange-005"},{"speaker":"南委員","kind":"提案","question":"そこに対して、品川区が国に対して特別区長会を通じて要望しているという、そのことは私たちも大いに後押ししたいですよ。それからさっき言ったように、とっくにそれぞれの家庭での責任というのは税金を払っているという点では貢献しているわけですから、そういうことを見たときに、今回の値上げというのは私はどういうふうに考えても理解できる素地というのは見つけ出せることができません。非常に残念です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"確認","question":"決してこの内容自体を反対するわけではないのだけれども、やはり議会に対して説明するにあたっては、今言ったことの具体的な裏づけ、数字、そういうものがないと、私たちとしてはどうなのかという部分があるので、今わかる範囲で結構ですからどれぐらい具体的な経費が増えて、それから、それを本当に在宅子育て世帯との公平性をどう担保していくのかということ、それからあと確認ですけど。","respondent":"伊崎待機児童対策担当課長、立川保育課長","answer":"これは施設数が平成２０年度は４７園であったところ、２４年度予算では６１園と１４園増えておりますことと、施設整備につきましては。在宅に関しましては所管がまたがるところなんですけれども、保育課としましては、在宅との均衡につきましては、保育料の徴収については、児童福祉法の第５６条第３項に記述されていまして。","voiceIndex":27,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"確認","question":"だから、そういうことをやはり議会ですから、一つの保育園という立場だけ特化していくことではなくて、やはりすべて３５万人余の区民の皆様方の税の使い道、それから公平性、事業の進捗性を担保しながら、するべきだと思いますので、それでそういうことについて、やはり細部の説明が保護者に対する説明を個別の説明とホームページ、それと広報紙だけでやるとおっしゃっているんだけれども、私たち。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"本来でしたら、全体に広く薄くという委員がおっしゃるとおり、改定をすべきところです。今回は経済、社会情勢に鑑みて、この所得の比較的高い方に限ってご負担をお願いするという考え方です。それによりまして、今後の保育施策、また在宅子育て家庭を含めた全体の子育て支援策、また、負担についても当然いろいろな傾向が変わってくるかと思いますので。","voiceIndex":30,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、将来構想も含めた上でこうですよというふうなことを、やはり具体的に説明していただかないと、いくら高所得者層と言ってもさまざま税金を払っているわけですから、やはりそういう感情を少しでも和らげる努力はしていただきたいと思います。こういうことを踏まえた上で３５万人余の区民の税負担、公平性という観点から見ると、どうなんですかということも議論していく必要がある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-009"},{"speaker":"阿部委員","kind":"質問・要望","question":"そういう意味では、最初に課長からのご説明で増えてきたのでとあったんですけれども、多分これ増えてきたからではないのではないでしょうかね。増えてきたなら実数を把握していないというのはおかしなことですから。それを１点確認させてください。子どもが増えているわけですから当然コストがかかるわけですし、それに加えて品川区が積極的に保育園の拡大をしていることでさらに増えている。","respondent":"立川保育課長","answer":"全体負担に対してどう考えるのかということですけれども、６０％に対しまして、今後、段階的に引き上げということを考えまして、それで今回は当初全体４％という考え方をしていたんですけれども。","voiceIndex":34,"id":"exchange-010"},{"speaker":"阿部委員","kind":"質問・要望","question":"伸びているわけですよね、相当な勢いで。もっと、０歳、１歳、２歳あるいは４歳、５歳とそれぞれかかる経費というのは全然違うわけですから、それにもっと見合った形で考えていくべきではないのか。品川区としては、もう１回伺いますけれども、今後の負担増に対してどのように保育料の設定を検討していくのか。どのようにお考えなのか。もう少しわかるように説明していただきたいと思います。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"今後の改定の予定はないということは先ほどもお話ししたところです。次の全体像がはっきりしていないですが、この辺につきましては、今後どういう方向で改定していくのかということは検討してまいりたいと思います。今回、先ほどから課長がるる説明しているとおりの趣旨で改定案を出しています。","voiceIndex":40,"id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"今、調査している。なぜかというと、それは民主的手続というその形の問題だけではなくて、やはりどういうところに公平感があるのか。それは確かに多いとは思います。何で年収が高い家庭だったら、負担を増やすときに説明しないんですか。説明なしというのはないと思いますし、それがどういう家計の実態に影響を与えるかというのは、当然に区として把握しておくべきだと思います。ご説明をお願いしたい。","respondent":"立川保育課長","answer":"説明が足りないところにつきましては大変申しわけありませんでした。","voiceIndex":43,"id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"やろうと思えばできるわけで、そこで広範にいろいろな意見を聞いて、それで、さっきから何度も申し上げているように、保育料のトータルのコストがかかっていくというのはわかっているわけですから、ただただ、一部の層に値上げ分を集中的に転嫁するようなことではもたないわけですよね。例えば今後、そういうことをするお考えがあるかどうかを、まず一つお伺いしたいと思います。できないと思いますよ。","respondent":"立川保育課長","answer":"直接の回答になっていないかもしれません。","voiceIndex":45,"id":"exchange-013"},{"speaker":"阿部委員","kind":"質問・要望","question":"話がかみあっていないんですけれども、現在の社会経済情勢に合わせてという説明であれば、階層を細かく分けることの説明には多少はなるかもしれないですけれども、中間層に手を入れないことの説明には本当はなっていないという理屈はおわかりでしょうか。それで、何度も伺っております。その上で保育料の改定をすべきだと考えていますが、その考えは区には全くないのでしょうか。もう一遍聞きたいと思います。","respondent":"立川保育課長","answer":"保育料の改定につきましては、先ほども説明いたしましたとおり、条例事項でありますので、議会においてご審議をいただくものと考えております。","voiceIndex":47,"id":"exchange-014"},{"speaker":"阿部委員","kind":"質問","question":"今の答弁になっていないですよね。品川区として抜本的に保育料の改定について、設計について見直す考えがあるかどうかということをお聞きしました。","respondent":"立川保育課長","answer":"現在のところ見直す考えはございません。条例事項につきましては議会においてご審議いただくものと考えております。","voiceIndex":49,"id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"その見直す考えがなくて、これからの品川区の保育料、これ、６０％をどうやって目指していくんですか。そういう考えなしに今回、値上げをするということなんですか。","respondent":"金子子ども未来事業部長","answer":"その辺のあたりのお答えというのは、私としては先ほど申し上げたつもりだったので、繰り返しになってしまうかもしれませんけれども、ここから先の子育て支援の状況というのが非常に大きく変わろうとしています。","voiceIndex":51,"id":"exchange-016"},{"speaker":"阿部委員","kind":"質問","question":"根本的に見直していきたいと、調査の結果を踏まえて。逆に言えば、なぜこのタイミングでこの３，６００万円、４％、全体の寄与率から言えば１.１ポイントという小さくてピンポイントな改定をするんですか、このタイミングで。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"先ほどもお話ししているところなんですけれども、本来全体の４％というふうに考えておりましたけれども、所得の低い方、中間所得の方に配慮しまして、そこは改定しないということになりましたので。ただし、先ほどもこれまでも繰り返し申し上げているとおりですが、経済、社会情勢というのを考えなければならないと考えていますので、今回負担増をいただくのは一定の層に限らせていただくというふうな考えに至ったところです。","voiceIndex":53,"id":"exchange-017"},{"speaker":"阿部委員","kind":"質問・要望","question":"そういう層でもあるわけですね。その層に向けて、今度保育園についても、これら最大１０万円を超える負担増を区は求めるということになっているわけです。なぜそういったことも含めて、なぜわざわざこのタイミングで品川区としてもこれだけの負担増を求めるのか。であれば、やはり家計に対する負担あるいは負担感というものを勘案してタイミングというのも図るべきではないかと思いますが、いかがでしょうか。","respondent":"立川保育課長","answer":"年少扶養控除に関しましては、高額所得の方だけではなく全体の問題と考えております。児童手当に関しましては、ちょっと所管が違うんですけれども、旧児童手当制度はたしかこの層はまるっきり交付がなかった層というふうに認識しております。","voiceIndex":56,"id":"exchange-018"},{"speaker":"阿部委員","kind":"提案","question":"ということで、この層というのはこの国の制度改正と言っていいんですかね。非常に負担がことし大きくなっているというのは現実として起こっているわけですから、それは行政として把握をしていただきたいと考えています。どうですか。国基準によらない条件設定だって現実に長年やっているわけですから、そこだって考えてもいい話だし、それから、品川区で言えば、民間との整合性はどうするのか。いかがですか。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"全体の改定につきましては、現在、私からお答えするような内容ではないと考えています。こういう枠組みの中にあるというふうに考えているところです。","voiceIndex":58,"id":"exchange-019"},{"speaker":"阿部委員","kind":"意見","question":"わかりました。ただ、一つの家庭に対して区に対する負担１０万円を超えるようなそういった議案に対して、１時間やそこらの議論で済ませていいのか。改めて申し上げます。だから、抜本的に考える必要があり、それに基づいた改定をすべきではないかと再三申し上げているわけで、区としてはそういうことではないのだと。そういう発想で値上げをされるという区の姿勢に対して怒りを持っています。","respondent":"立川保育課長","answer":"私の先ほどのご説明については、いわゆる対象の方々に対してどう周知していくかということに対して、広報や個別にご通知申し上げるということをお話ししました。ここで説明は要らないというふうなことは発言しておりません。","voiceIndex":62,"id":"exchange-020"},{"speaker":"阿部委員","kind":"質問","question":"区としてのお考えはわかりました。私からの質問はとりあえず以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-021"},{"speaker":"鶴委員","kind":"質問・要望","question":"保育料の制度の話もありましたけれども、これ、改定部分の話云々がありましたけれども、やはり精査していく必要があるかなというところで、そこをきちっと、これは要望も含めてお願いしたい。その上で、ちょっとお聞きします。私、不勉強で大変恐縮なんですけど、今回加わる（５）と（６）ありますね。これは品川区の区の施設で言うとどこに当たるのかというのをまず一つ教えていただきたい。","respondent":"立川保育課長","answer":"ここですけれども、具体的には知的障害支援の品川児童学園という施設があります。医療発達支援ですとかほかのものでは大体都立の都の所管のものなんですけれども、品川区内では代表的なものとしましては、品川児童学園が中心となります。","voiceIndex":65,"id":"exchange-022"},{"speaker":"鶴委員","kind":"提案","question":"私も児童福祉法をずっと読んでいろいろな施設を含めてとおっしゃっている。この場合の言葉の整理というので、事前に調べたら特段違いがないので同じ意味なのかなと思っているんですけれども、やはり出てくる書類の中に二つ言葉があると、何か違うのかなと私はそういうところに気になってしまうので、先ほどの整理の話になりますけれども、ここら辺、まずちょっと同じ意味かどうかだけ確認させてください。","respondent":"立川保育課長","answer":"保育料に関しましては一家で合計で幾らかかっているかということがまず、それで軽減、いわゆる減額制度というものにつながっておりますので、１人目は減額なし、２人目は５割減額、３人目は９割減額、一家でトータルで保育料がどれぐらいかかるというか。","voiceIndex":67,"id":"exchange-023"},{"speaker":"鶴委員","kind":"確認","question":"２カ所言葉として「入所している」という言葉だけですね、それがそれぞれ変わるんだなと理解しました。ここについては、同じ第４条第２項各号と続いている「入所している」とありますけれども、同じくここも本来は「入所し、通園し、または通所している」に変える必要があるのではないのかなとちょっと思っていたんですが、確認の意味で教えていただければと思います。","respondent":"立川保育課長","answer":"ちょっとこの部分につきましては所管が総務の文書係というところがありますので。済みません、ちょっと訂正させてください。条文につきましては確認いたしまして、また後ほどお答えしたいと思います。","voiceIndex":69,"id":"exchange-024"},{"speaker":"鶴委員","kind":"質問・要望","question":"先ほどの誠意という部分では大事なところかなと、ちょっと気づいたものですから、それで、ここは、本条を変えればここはこういうふうに当然変わるんですよなんていうルールがあるんだったら、その辺も不勉強なので、後ほど教えていただきたいと思います。１個漏れてしまってごめんない。先ほどの多子軽減ないし減額の範疇なんですけれど、この裁量みたいな部分というのは自治体によって任されているんですか。","respondent":"立川保育課長","answer":"本区の場合の条例で定めるということになっておりますので、本区においては条例での判断ということになります。","voiceIndex":71,"id":"exchange-025"},{"speaker":"高橋委員","kind":"質問・要望","question":"保育料のいろいろな議論があったので、お尋ねしたいことも少々あって、区のほうのお考えやこうしていただきたいというのも出たので、それ以外の話で、負担を区民からお願いするということですので、運営経費の約１００億円のところで、一つは人件費がどれぐらいで、保育士の方々一人どれぐらいになっているのかということ。","respondent":"立川保育課長","answer":"運営費全体に対して人件費がどれぐらいかというところにつきましては、全体につきましては大体６０％台が人件費となっております。","voiceIndex":73,"id":"exchange-026"},{"speaker":"高橋委員","kind":"質問","question":"大体７００万円ぐらいということなんですけど、そういった非常に用務の方、保育士の方が今回報告書にも入れられて保育サービスの充実をしているんですが、その一方で運営経費が増えているのは当然ですけど、運営形態の見直し等も含めて今後の運営費の圧縮、そういう方向性については区としてはどうお考えなんでしょうか。","respondent":"立川保育課長","answer":"今後の運営形態と運営経費の圧縮ですけれども、先ほど部長から答弁がありましたように、これから品川の保育をどうしていくのかという、その辺の全体の議論の中で考えていきたいと考えております。","voiceIndex":75,"id":"exchange-027"},{"speaker":"高橋委員","kind":"質問・要望","question":"今後の先ほどの調査の結果等も含めて根本的に見直していくというお話の中で可能性があるということですので、そこのときに運営形態の見直し等も含めて経費の削減、圧縮を、もちろんサービスを維持するというのが大前提ですので、経費の圧縮も運営形態の見直しも含めて抜本的な縮減、見直しを調査の結果に基づいて行っていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-028"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"１回、そういった正確な数字を区民の皆様に見てもらうことによって、どういうふうな考えなのか。それはうその数字ではないですから、事実としてお示しするのは何ら悪いことはないと思いますので、ちょっとその辺の説明というんでしょうか、１回このタイミングですから長期基本計画でこれから調べていかれるということなんですけど、なさってみたらどうだろうと思ったんですが、その辺の考え方をひとつ。","respondent":"立川保育課長","answer":"実は、保育園入園の方に関しましてはこのご案内というので、丁寧なご説明をしまして、実際年齢ごとに幾らかかっているのかということはまず図を交えてお知らせしているところなんですけど、今回、広報紙で保育料改定について紙面の大きさの都合もあるんですけど。","voiceIndex":78,"id":"exchange-029"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"ただ、例えばＣ階層だったら１％で、Ｄ階層では１０％だよという、そういう開きがあるにせよ、そのほうがよかったのかなと思う半面、相当それは考えて今回のこの条例改正が出されていると思いますので、そこのことはいいんですが、実際保育を受ける方だけではなくて、区民全体にこれだけかかっているんだよというのをどこかのタイミングで知っていただきたいと思いますので、ぜひきっと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"私、先ほどちょっと質問したところの答弁がなかったので確認させていただきたいと思って、よろしくお願いします。私は先ほど自分の質問のところでこういう内容の部分を言ったときに、前回９年前の数字も決算額で答弁があったので、今日的な数字を決算額で、ちょうど決算書が出されていましたので、それを見て紹介したんですけど、大分開きがあるので、その辺伺いたいと思います。","respondent":"立川保育課長","answer":"先ほどの運営経費ということでお話をさせていただいた１００億３,７００万円なんですけれども、これは平成２３年の運営経費のみの決算です。新規開設とかそういう経費は含まれていないという部分で１００億３,７００万円をお示ししました。","voiceIndex":85,"id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"ちょっと１００億円の運営経費の部分ですけれども、決算額ということなんですが、それは公私立合わせた決算額というふうな認識でいいんですか。公立保育園のところの数字でちょっと見ると、公立と私立どういうふうにここがなっているのかを詳しく知りたいと思います。それと、年齢ごとの人数なんですけれども、なぜ紹介できないのか。それをお知らせできない理由はないというふうに思うので教えてください。","respondent":"立川保育課長","answer":"数字については、ちょっと足し込んでいなかったので即答ができないというお話です。運営費につきましては、私立、公立合計の金額です。","voiceIndex":89,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"それぞれの階層ごとの人数ですけども、トータルがなっていないからということではちょっとよくわからないので、私はこれは大事な部分だと思うので、ぜひ教えていただきたいと思います。","respondent":"立川保育課長","answer":"ちょっと足し込みながらですけれども、まず３歳未満ですけれども、Ｄの１６につきましては６２名、Ｄの１７が５１名、Ｄの１８が２５２名、Ｄの１９が１２３名、Ｄの２０が１００名、Ｄの２１が９０名、Ｄ２２が５３名、Ｄの２３が３３名、Ｄの２４が２７名、Ｄの２５が３２名。","voiceIndex":91,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"採決にやはりこれだけの方々がというところもちょっと知りたいところなので、教えていただきたいということと同時に、いつの時期に出していただけるか、委員会の後すぐ、あるいは休憩時間に出していただくとか、そういうことであればありがたいけども、ちょっとその辺どういうふうに考えていいんでしょうか。","respondent":"立川保育課長","answer":"３歳がＤ１６から順次数字を申し上げますと、２９人、１９人、９７人、５５人、３９人、３０人、３０人、１５人、２０人、２０人です。４歳以上につきましては、Ｄ１６から３８人、４２人、１６４人、９９人、６１人、７８人、６１人、２７人、２６人、４３人です。","voiceIndex":96,"id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"区の中でこの値上げの考え方自体はいつごろ俎上に上がって、その後どのような形態で事業を進められたのか。その事実関係だけ教えていただければと思います。中で検討委員会などがあったのかどうかも含めてお願いします。","respondent":"立川保育課長","answer":"前回、平成１６年改定以来、毎年のように改定をしておりまして、その間、税法改正に伴っての改正とか若干の足伸ばしをしたとか、保育料に関しましては毎年改定ということを検討しています。","voiceIndex":99,"id":"exchange-035"},{"speaker":"阿部委員","kind":"質問","question":"ずっとそれはテーマとして保育課の中で、あるいは事業部の中でそれは当然だと思います。そのあたり、今回、制度改正にまでつくり込んでいるわけですから、その議論をいつから始めて、どういう検討を通して今に至ったかというのを伺っているので、お答えください。","respondent":"立川保育課長","answer":"具体的な中身につきましては、昨年度の改定後から、検討を始めました。","voiceIndex":101,"id":"exchange-036"},{"speaker":"阿部委員","kind":"質問","question":"１回しか聞いてないので、全部答えてください。いつから検討を始めてどういう検討組織があったのであれば、それについても答えてくださいと最初の質問から言っているので、１回で答えてください。","respondent":"金子子ども未来事業部長","answer":"今、課長からご答弁申し上げたとおり、ことしの１定、もしくは去年の４定でもこの条例関係に関しては改正の年少扶養控除のかかる部分が主たるところですけれども、改正をお願いしたところで、いつからというのはなかなか明言できないものがありますし。","voiceIndex":103,"id":"exchange-037"},{"speaker":"伊藤委員","kind":"質問・要望","question":"意見表明をしてもいいですか。今、条例議案としてこういう内容を審議することを議会に求めるのであれば、繰り返しになりますけれども、理由が必要です。つまり、合理的な数字を示していただいて、これこれこうでこうだからこうなんだというふうに、それが今回全くないではないですか。やはりこれだけ大きなことを変えていくにあたっては、もっと理事者の積極的な対応を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-038"},{"speaker":"鶴委員","kind":"質問・要望","question":"公明党も皆、賛成ということで、その理由についても先ほど質問させていただいた部分に含まれます。それから、在宅子育て世帯との負担の公平性とありますけれども、この辺についても誤解を生まないようなきちっとした説明をというようなことも大事なのかなと思いますので、そうしたところもきちっと手を尽くしていただきたいということも要望して、賛成ということにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-039"},{"speaker":"高橋委員","kind":"提案","question":"賛成です。もう一つは、これからも１００億円かかっていくんだから、保育料を上げてほしいという単純な説明では済まないので、やはり先ほどお話ししましたけれども、経費に関してこういう努力をこれからもしていく。そういった先ほどからお話ししていますけれども、全体の運営や特に大きなパーセントを占めている人件費を含めて、区として提案をする、あるいは改善していく。これは意見です。賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-040"},{"speaker":"阿部委員","kind":"提案","question":"この議案には幾つかのものが入っていて、多子世帯に対する軽減、これについては私どものほうでもこういったことをいろいろな形で提案してきたこともありまして、これについてはいいことだなと考えています。保育料についてですね。ただ、先ほどから再三申し上げていますように、やはりそれは全体の見直しの中で行われるべきものであろうと。年間１０万円を超える負担になる。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"私もまず反対だということを最初に申し上げたいと思います。そういう中で先に決めて保護者に押しつけるというこういうやり方、手続はいかがなものかと思いますので、きちんとこれからの改定もいずれ６０％を目指すという点でしていくだろうと予想されるわけですから、そういうときに今回の各会派から出された意見は十分に勘案していただいて、齟齬のないようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-042"}]},{"id":"topic-02","title":"第６９号議案 品川区立学校設置条例の一部を改正する条例","agenda":"第６９号議案 品川区立学校設置条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"そういうことが聞こえてくるのは事実です。ちょっとその辺の考え方を伺いたいと思いますのが一つ。今までは四つの学校がそれぞれ特別教室だとかプールだとか体育館だとか、学校にかかわるさまざまな施設を整備してありますよね。物理的に子ども一人当たりに対して広さは確保できている状況ではないけれども、全体的にその辺についてどういうふうに現状がなるのかという点について伺いたいと思います。","respondent":"和氣学務課長","answer":"８０名近い委員で協議をしながら進めてきておりますので、そういうご心配は、そういう方もいらっしゃるのかもしれませんが、十分議論した上での結果です。","voiceIndex":117,"id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"そのことは承知しています。私、質問中ですから。それから、設備の使い回しについても、どのくらい、それは設備的にはプールのない学校で、あるいは体育館のない学校でいいわけではないわけですから、つくるわけですよね、当然設置はするわけです。その辺をちょっと教えていただかないと、大丈夫ですというふうに言われたってわからないわけですから、そういう具体的な説明をしていただきたいと思います。","respondent":"和氣学務課長","answer":"そういうお声も聞いているのかもしれませんが、直接は私どもには届いていません。もし、そういうものがあれば、もちろん対応してまいりますけれども、特に聞いてございません。","voiceIndex":119,"id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、四つの学校が二つの小学校と、もう既に中学校は一つになっているけれども、もともと二つの中学校があわせて一つの学校になるという点では、やはり今まで心配されてきたことがどうなるのかということを、そこはきちんと確認しておかないといけないというふうに思いましたので、それで質問していますので、長々やるつもりは全然ないんですけども。","respondent":"田村教育次長","answer":"工事ももう説明会も無事終わって竣工の時点ですから、もう３月に竣工して荏原第五中学校はもうばさっと切っていますから、そこの時点でもう１回ぶり返してその議論をされても、私どもも今まで議会にかけてご審議いただいてご了承いただいた内容に。","voiceIndex":122,"id":"exchange-045"},{"speaker":"伊藤委員","kind":"質問","question":"今、教育次長から話があったとおり、私はこのことについては議会で十分説明を全部聞いております。ですから、きょうの議案はあくまで住所変更だけの話であって、内容について議論するわけではないと思いますので、そういう意味も含めて委員長においては議事進行を進めていただきますようお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"１年生にしてみれば９年間、そういう生活になるにあたって、本当にいいのかどうかということをやはりしっかりと質疑してから進めていただきたいと思うわけです。そうすれば私だって確認できることですから。その確認ができないから再度重なった部分はあるかもしれないけれども質問させていただいているんです。そういうことをやはり受けとめるそういうキャパがあっていいと思いますよ、私は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"そうしましたら、質問の趣旨を変えろというふうに言われても、私は先ほどから申し上げているように、今までの質疑も含めてやはり不十分な部分をそういうところを最終的に確認をしたいというふうに思って準備をしてきたつもりなんですね。","respondent":"和氣学務課長","answer":"そういうことについては、もう既に今、両方の学校の先生たちが集まって、そういう具体的な運用についてもずっとつくっておりますので、それについては具体的、ここにいつ何時間どうのというご説明はできませんけれども。","voiceIndex":128,"id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"具体的に豊葉の杜学園が４月から小学校の子どもさんたちも含めてスタートしていくというふうになるにあたって、やはり今、学務課長がご答弁されたように心配をなくしていくのは当然のことですからしていただきたいわけですけども、いろいろな不満あるいは説明が不十分なために父母の皆さんから教育にかかわるいろいろな意見がもし出たときには、きちんとした対応を説明も含めて必要な改善があるとしたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-049"},{"speaker":"渡部副委員長","kind":"確認","question":"南委員、過去において豊葉の杜学園ができるということを過去の文教委員会でずっと議論されてきて、もうでき上がった。今回、正式に移ってくるということで住所を変えるという段階のことですので、その内容ですとか、でき上がりの設備の話はさんざん委員会で確認をされてきていると思いますので、住所を変えるか変えないかの議論であれば続けてください。この議案のとおり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどから申し上げているように、住所を変えることについていいのかどうかということも含めて検証を最終的にチェックしたいから聞いているということですから、長時間にわたって妨害するつもりも何もありませんから、そこの質問だけさせていただいているわけですから、お許しいただきたいというふうに思うんですね。ブレーキかけられる理由なんて全然ないというふうに思うんですけど。ぜひ答弁お願いします。","respondent":"和氣学務課長","answer":"そういうノウハウはすべての学校で共有していますので、その共有したものをしっかり生かしていくということについては、委員ご指摘のとおり全くして変わりませんし、いろいろな保護者の方にもさまざまな意見がありますので、それも学校はしっかり受けとめ。","voiceIndex":132,"id":"exchange-051"},{"speaker":"南委員","kind":"意見","question":"私は反対です。理由を言います。それと、一貫校は行事のところでも、いろいろな問題があってきているという個々の不満も結構な数あるという現実を見たときに、また、教育内容的には競争教育を強いているという現実がある中では、やはりここは残念ですけれども、賛成はし得ません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":140,"id":"exchange-052"}]},{"id":"topic-03","title":"の第７０号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"の第７０号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"これ、公務災害補償の金額が下がるということで判断していいんですかというのが一つと。それから、なぜ下がるんですかということが二つと。それから、毎年改定と言っていましたけど、これは例えば国の基準が改定したことを受けてそれと同じく変わっていくんでしょうか。その三つをお伺いしたい。","respondent":"和氣学務課長","answer":"公務災害の補償が下がるです。これは東京都の給与改定を毎年していますけれども、その人事院勧告がありますが、それに対応する根拠になっております。","voiceIndex":146,"id":"exchange-053"},{"speaker":"伊藤委員","kind":"確認","question":"確認ですけど、民間のそういう方々のところと学校薬剤師との間の場合の公務の補償の金額があい差があるので、それは毎年見直していきますという考えでいいんでしょうか。","respondent":"和氣学務課長","answer":"委員ご指摘のとおりです。","voiceIndex":148,"id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"全然不勉強なので教えていただきたいんですけど、学校医とか歯科医とかそういうのは職はわかるんですけども、学校薬剤師というと具体的に学校の中でどんな仕事をしていただいているのか。職の中身を教えていただきたいのが一つと。障害者自立支援法の改正というふうにあるんですけど、障害者自立支援法について何回か改定されているけれども、直近の部分を当然言うわけですよね。二つお願いします。","respondent":"和氣学務課長","answer":"薬剤師の方には主に学校の環境の関係をやっていただいております。水質であるとか空気であるとか、そういうところについてお願いをしています。それから、改定は平成２３年１０月の改定です。これに伴っての改定です。","voiceIndex":150,"id":"exchange-055"}]},{"id":"topic-04","title":"の第５９号議案 平成２４年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"の第５９号議案 平成２４年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"南委員","kind":"意見","question":"今の学校の６校の部分の説明、この間もずっと精査して検討してこられた、調査してこられたということはわかったし、必要な許可なんだろうということでやっていただいてることを了解するところですけど、要するにこれだけでなく、これからも必要な改築はまだ残っているというふうな認識を私は持つんですけれども、その辺はどういうふうになっているのか。","respondent":"齋藤庶務課長","answer":"昨年の３．１１以降、随時学校も見ておりますので、かなりの割合で補修は進んでおりますが、専門家の目で見ていただくのは今回初めてですので、成果物を見て危険箇所については適切に対応していきたい、補修もしていきたいというふうに考えております。","voiceIndex":165,"id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"この間もずっと構造部材も含めて対応していただいているということは承知しているつもりなんですけども、要するにまだまだ細かい目で専門家の目で見たときには、まだまだやらなければいけない箇所というのは幾つかあると思うんですね。その辺の計画をこれからどういうふうに考えているのかというあたりも、ちょっとこの際教えていただきたいというふうに思います。","respondent":"齋藤庶務課長","answer":"成果物をまだ見ておりませんので、見てからということになります。予算のこともありますので、来年度中にできるか。あるいはものによっては２カ年かけるかというのはこれからの成果物をみてからということになります。","voiceIndex":167,"id":"exchange-057"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。当然だと思うんです。保育園とか幼稚園等々については、この耐震対策ですね、それが学校と同じように計画を持って対応していく必要があると思うんですけど、今回の補正のときから全部それで一通りのところは終わりましたよというふうな認識を持っていいのかどうか。必要なところがどういうところなのかいうことがもしあれば、教えていただきたいと思います。","respondent":"立川保育課長","answer":"中身につきましては、主なところですけれども、穴ですとか、ガラスですとか、その辺の割合が多くなってあります。細かいところですと、ロッカーであるとか、水槽であるとか、廊下、掲示板、額縁、時計、天井、機器、レンジ等になります。","voiceIndex":169,"id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"学校もそうですけれども、保育園、特に小さな子どもたちを預かる施設ですので、やはりきちんと細かいところもあるかもしれないけれども、それはそれでしっかりやらなければいけないという施設の性格上、そういうことが求められると思うんですけども、ぜひ、今回のこの措置で全部終わったというふうに認識していいのかどうか。ちょっとわからなかったので、そこを最後に伺いたいのと。","respondent":"立川保育課長","answer":"今回の点検には含まれておりませんが、ブロック等の壁等につきましては、３年に１回定期的に点検し、安全性の確認をしています。今回の耐震対策で非構造部材については幼稚園、保育園につきましてはすべて終了しております。","voiceIndex":171,"id":"exchange-059"},{"speaker":"阿部委員","kind":"質問","question":"幾つかお伺いします。１９ページの子ども手当なんですけれども、未申請の世帯がどのくらいなのかというのは多分把握されているのではないかと思うんですけれども、現段階でどの程度なんでしょうか。あわせて、今まだ未申請の方、いつまでなら間に合うのか。そのための周知をどのようになさっているかということをお聞きします。","respondent":"梶青少年育成課長","answer":"未申請分がどのぐらいかということなんですが、前回、調べたところが大体細かい数字、転出したりとかそういうこともありますので、細かくはないですが、２０件前後あったということを記憶しています。そして、申請自体はことしの９月の末で終了になります。","voiceIndex":173,"id":"exchange-060"},{"speaker":"阿部委員","kind":"質問","question":"２０件ということで丁寧にやっていただければと思います。それから、非構造部材なんですけれども、１施設当たり幼稚園、保育園等と学校というのは、１施設当たりの部材の違いがあるわけですけど、当然規模の違いがあるからだと思うんですが、体育館が大きいんでしょうかね。足場とかそういう話で金額が大きくなってくるのか。それとも、全体の工事の関係でしょうか。","respondent":"齋藤庶務課長","answer":"一番大きいのは強化ガラスの交換でございまして、例えば山中小学校であれば、７９８万円ぐらいの費用になります。","voiceIndex":175,"id":"exchange-061"},{"speaker":"阿部委員","kind":"質問","question":"ご説明の中でのグランド側でない側の強化ガラスというご説明が何度か出てきたと思うんですけれども、済みません、私、もの知らなくて、これはどういう理屈になるんでしょうか。","respondent":"齋藤庶務課長","answer":"グランド面は子どもがいてボールを投げたりして割れやすい。したがって強化ガラスに既にしてあります。裏道だとか人が通らないところは強化ガラスにしていないところがあるので、今回強化ガラスにするです。","voiceIndex":177,"id":"exchange-062"},{"speaker":"阿部委員","kind":"質問・要望","question":"なるほどわかりました。ここで対象になっている６校について、できれば別紙で書かれている資料があればなおよかったかなと、一生懸命皆でメモしていたものですから、そういう資料もあわせてあるとわりやすいかなと思ったので、それは加えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":179,"id":"exchange-063"},{"speaker":"高橋委員","kind":"質問","question":"非構造部材のところで、文部科学省のほうから非構造部材というのはこういうところだと、これについてチェックしてみたいな指針が出ていると思うんですが、それを例えば文部科学省に報告、かなり安全を重視してやっているので、そうなってくると、どこまでやっていいかというのは非常に難しい問題があると思うんですけど、もちろん安全のために万全を尽くさなければいけないんですけど。","respondent":"齋藤庶務課長","answer":"大規模改修、耐震補強でおおよそ２分の１の補助金がありますが、１,０００万円以上の工事をしなければもらえないといったようなものがありまして、なかなか１点１カ所あたりしていますが、なかなか厳しい状況で。","voiceIndex":181,"id":"exchange-064"},{"speaker":"阿部委員","kind":"質問","question":"今のやりとりの中で補助金があるとおっしゃっていたのは、あれはきのうの大規模改修のものの話も、非構造部材の指針が出たことに伴っての補助金計上というわけではないという解釈でよろしいんですか。","respondent":"齋藤庶務課長","answer":"非構造部材のための国庫補助金はできました。ただ、使い勝手が悪いということです。","voiceIndex":184,"id":"exchange-065"},{"speaker":"渡部副委員長","kind":"質問","question":"済みません、１点だけ教えてください。２３ページのプラン２１推進事業追加分の合同部活動実施経費で、例えば顧問の先生がいないところで外部の方にお手伝いいただくと思うんですが、これは今回の補正分に限らずですね、今どれぐらいの方にお願いしているのか。一つちょっと気になって教えてほしいのが、例えば中学校の部活になりますと、何らかの形で遠征というものが発生すると思うんですね。","respondent":"太田指導課長、和氣学務課長","answer":"今、遠征の際の責任の所在ということがありましたけれども、それにつきましては必ず指導者がいても学校の教員が顧問として引率をし、そういった責任を持つということになっております。共同校というのは荏原平塚中学校、八潮学園、豊葉の杜中学校ですが、こちらについては増額をいたしまして１５０日、１５０人分ということで、こちらのほうは措置しています。","voiceIndex":187,"id":"exchange-066"},{"speaker":"渡部副委員長","kind":"質問","question":"移動の際というのは、顧問でなくても必ず学校の先生が見ているということですね。逆にその指導者がいないところに補助にいく。顧問は必ずいるということですか。僕、ちょっと認識違いをしていたのかもしれないんですけど。","respondent":"太田指導課長","answer":"移動のときには必ず学校の教員が顧問として付き添います。ただ、顧問がその競技の専門的な知識がない場合に外部指導員の方に指導をお願いして、子どもの管理等は必ず教員がするということになっております。","voiceIndex":190,"id":"exchange-067"},{"speaker":"鶴委員","kind":"質問・要望","question":"２５ページの学校と家庭の連携推進事業なんですが、先ほどいじめに関するスーパーバイザーというのがありましたけれども、社会的に何かの委員とか決まっていらっしゃるんでしょうか。はどういう形で入れるものなのか。この辺が粗々でももし決まっているのであれば、教えていただきたいのです。どういう形で改選するんですか。","respondent":"太田指導課長","answer":"この方はスクールカウンセラーとして八潮学園にも務めているので教員とも連携をしていただく。そのほかに、その大学の心理学部の大学院生を支援員として配置し、子どもたちの学校におけるさまざまな対応に使う。そういったような形の事業です。","voiceIndex":193,"id":"exchange-068"},{"speaker":"南委員","kind":"質問","question":"どの５項目についても私はかなり差別感をひどく感じて、非常に何と言うんでしょうか、不愉快というか、そういう印象を持って読みました。国旗、国歌についてはそれぞれ内心の自由があるところだと思うし、この１０・２３通達そのものが国の見解を越えているものだというふうに思うんですけれども、そのあたりは品川区の教育委員会でそれはどのように見ているんでしょうか。","respondent":"太田指導課長","answer":"今回の陳情のご判断ということにつきましてご説明申し上げいるところですし、その内容につきましても、先ほど申し上げたように、全くの事実の誤認を前提としてお話しいただいているところですので、それについて私のほうで申し上げることはございません。","voiceIndex":207,"id":"exchange-069"},{"speaker":"南委員","kind":"質問","question":"学習指導要領に基づいて徹底しているというここの中身そのものが、事前にいろいろ調べたら私自身よくわからなかったので、あえてちょっと伺いたいんですけれども、どういうことを指しているんでしょうか。どういうふうに理解したらいいんですか。","respondent":"太田指導課長","answer":"学習指導要領において、例えば小学校においては、社会において例えば我が国や外国には国旗があることを理解させ、それを尊重する態度をとらせるように配慮することとか、我が国の国旗と国歌の意義を理解させ、それを尊重する態度をとらせるとともに。","voiceIndex":209,"id":"exchange-070"},{"speaker":"南委員","kind":"意見","question":"とりあえずその程度にさせていただければと思います。私としては、この陳情については先ほども申し上げたように、品川区の教育委員会の説明では、事実誤認だということだし、事実はないということだし、陳情内容そのものが全く差別そのものを強いるような、そんな内容なので、とても認めるわけにはいかないというふうに思いますので、態度としては反対だということを表明して終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":211,"id":"exchange-071"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、何回も繰り返したように、品川区の教員のことではありませんから、そういうことを前提にしていく上で、ここに書かれている自分たちの国旗に対する意思、思いは理解できるなと私たちは思っていますので、これは一方的な意見になってしまいますけど、あくまで品川区としての立場ではないんだけれども、私たちとしてはここに書かれているこの趣旨については。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-072"},{"speaker":"阿部委員","kind":"提案","question":"非常に微妙な問題である。ここで提案をされているのはちょっとバランスが悪いなというふうには感じております。それはいろいろなことがあって、それに対して教育委員会としてもいろいろな面でいろいろな認識をもとに調整されていると思いますので、そちらの陳情が提案されていることは、少々ほかの議案と比べてみれば、バランスが悪いのかなと思います。ただ、一般論です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":214,"id":"exchange-073"},{"speaker":"伊藤委員","kind":"意見","question":"きょう、結論出すことがいいと思います。それから、このことについて私たち会派で議論します。繰り返しますけど、品川区の教員のことではありません。ここだけはお話します。ただ、ここに書かれているように、自分たちの国旗に対する思い、姿勢については共感できる部分があるという理由でぜひ趣旨採択としてお願いしたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":216,"id":"exchange-074"},{"speaker":"高橋委員","kind":"質問","question":"結論を出すということで、陳情にその前提が今、説明がありましたように異なっているわけですから、これは不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-075"},{"speaker":"阿部委員","kind":"提案","question":"本日、結論を出していただければと思います。区内で前提となる事実がないというのは不採択と思う最大の理由ではありますけれども、先ほども申し上げたように、いろいろな考え方の方がいらっしゃって、それはそれでいいと思うのですけれども、客観的に行政機関としてやはりバランスを欠いたことを提案されても、現状では賛同しかねるという部分でもあるかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":219,"id":"exchange-076"},{"speaker":"南委員","kind":"意見","question":"私も先ほど申し上げましたけれども、不採択にしたいと思います。そこのところは個人の内面の自由というところはやはり尊重されるべき問題だというふうに思いますので、それはこの議論では場面は譲らなくてはいけないと思っていますけれども、そこは教育として、やはりきちんと見ていただく不動の部分だというふうに思います。この陳情については、冒頭も申し上げたように不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":220,"id":"exchange-077"}]},{"id":"topic-05","title":"の３ その他","agenda":"の３ その他","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"なので、その教育委員会としての学校事故の把握の基準といったものを知りたい。ただ、やはり学校にいるときには何もなかったけど、家に帰って一応病院に行こうかとか、そういうケースもいろいろあると思うんですが、そういったことも含めて把握はしていってほしいですし、そのためにどのような方策があり得るのか。そこら辺をちょっと整理して教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-078"},{"speaker":"阿部委員","kind":"質問","question":"所管質問というもののとらえ方ですので、それは委員長に仕切っていただいて構わないんですけど、気持ちとしては事故全般について伺いたい。","respondent":"田村教育次長","answer":"はい、了解しました。","voiceIndex":230,"id":"exchange-079"},{"speaker":"金野委員長","kind":"質問","question":"よろしいでしょうか。ではそれでよろしくお願いいたします。そのほか何かありますでしょうか。よろしいでしょうか。私のほうから、前回の委員会の所管事務調査の中で南委員および高橋委員からの質問に対する答弁が保留になっている件につきまして、次回以降の委員会の中で所管事務調査で調整します。これでその他を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-080"},{"speaker":"南委員","kind":"提案","question":"今の件ですけれども、本来だったら私のイメージは、きょうの委員会でご報告いただきたかったんですけれども、議題がいっぱいあるということと、所管事務調査の中での提案だったので、初所管事務調査ができるときにご答弁、その後の質疑ができるようにというようなご配慮があるんだと思うんですけれども、できるだけ早い時期に実態をつかみたかったというのがあって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":233,"id":"exchange-081"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4770#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":65862,"voices":234}},{"id":"h24-20120924-5","meetingId":"h24-cm09","date":"2012年9月24日","dateIso":"2012-09-24","committee":"総務委員会","time":"午前１０時００分～午前１１時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに(1)第７１号議案「旧荏原平塚中学校跡地多目的広場整備工事請負契約」","agenda":"はじめに(1)第７１号議案「旧荏原平塚中学校跡地多目的広場整備工事請負契約」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"契約の中身に入る前に、多目的広場ということで、この間、ここの学校がなくなることに当たって、どういう広場にしてほしいかということで、地域からたくさん声が上がっていて、特にこの地域は公園などの緑が少ないので、緑とか憩いの場所をつくってほしいという意見がかなり出ていて、私、図面を見せていただいて、かなりそういう要求が入っていて、当初の案は本当に広場ばっかりなので。","respondent":"多並公園課長、平澤経理課長","answer":"あわせましてその横に防災の井戸、今回は下水道に直結しているもので、そこに流すための井戸ということで、その横にもう１井戸設置している、それが主な防災機能ということで設置しているものです。地域からの意見をどのようにですが、まずはじめに、平成２０年当時ですが、地元町会等から要望を受けたところです。それに合わせまして平成２０年１１月には利用計画のパブコメを実施したところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味では、防災機能をというところではかなり期待があると思うので、そこで煮炊きできるとか、トイレも大事です、防災の貯水槽も大事なのですが、そういうご意見があったかと思うのですけれども、その辺も取り入れていただけたらと思うので、その辺が１点と、あと、契約のところなのですけれども、この間、予定価格のことがなかなかわからなくて、教えていただきたいのは。","respondent":"多並公園課長","answer":"１点目のかまどベンチの設置についてのご質問ですが、今回のこの整備につきましては４基のかまどベンチを設置する予定です。","voiceIndex":8,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これから勉強させていただきたいところの契約なので、予定価格を積算していく過程の中身を知るためには、どういうところを調べたらいいのか教えてください。労務管理のところの１つの項目ですよね。どういった項目があるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"最後ですけれども、この広場は多目的広場というところがついていますけれども、ここは公園という位置づけになるのでしょうか。でき上がった後、どういう位置づけになるのか。多分この周りは誰でも入れると思うのですが、この防球ネットの中のグラウンド自体という取り扱いは、誰でも使えるのか、有料なのか、無料なのか、その辺の位置づけがどういう方向になるのかも教えてください。","respondent":"多並公園課長","answer":"位置づけについてのお尋ねですが、ここにつきましては公園の児童遊園という条例に基づく管理で現在予定しています。利用につきましては、児童遊園、公園ですので、誰でも２４時間使えることが原則となっています。","voiceIndex":17,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"少年野球、少年サッカーの方、たくさん請願を出されて、願いがいっぱいこの議会に届きましたけれども、利用者の方々と十分協議をして、そのあたりは決めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-005"},{"speaker":"阿久津委員","kind":"質問・要望","question":"私からは何点かお伺いしたいのですが、先ほど委員長からも現在解体工事をしていて危険だというので視察ができなかったというお話があったのですけれども、その解体に関係する話で、地域の方から、やはり解体工事についていろいろなお声が上がっているということを聞いたのですけれども、振動とかですね、それについて何か区にそういうお声が入っているのかどうかを確認させていただきたいのです。","respondent":"小林施設整備課長","answer":"土曜日に大型の重機を入れる予定です。来週から本格的に建物を解体し始めますので、重機が動く来週あたりぐらいからは振動、騒音、粉じんが出てきますので、適切な処理をして、なるべく最小限に抑える形で進めていきたいと思います。","voiceIndex":21,"id":"exchange-006"},{"speaker":"阿久津委員","kind":"質問・要望","question":"直接今回の契約には関係なかったのですけれども、その前段階の話として聞かせていただきました。鮫洲の運動公園なんかはそういういろいろなお声があって、人工芝になった経緯があったと思うのですけれども、これは予算的なこともいろいろあると思うのですが、そういったことも検討に上がったのかどうか、そこのところをお聞かせいただきたいと思います。","respondent":"多並公園課長","answer":"そこに防砂林とでもいいましょうか、高木を配置いたしまして、また、あとは先ほどの防球ネットに下から２ｍですけれども、いわゆるほこりよけのネットを張る形で、今回、そのような形でほこりの対策を工事として行う予定です。","voiceIndex":23,"id":"exchange-007"},{"speaker":"阿久津委員","kind":"質問・要望","question":"近隣の方からはやっぱり砂の掃除とか落ち葉の掃除を、前の中学校のときは非常にやられていたという話もございましたので、今後、また先ほどの解体工事の振動等とあわせて、近隣の方のご意見、ご要望とかをいろいろいただいて、できるだけそういうのを対応願いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-008"}]},{"id":"topic-02","title":"第７２号議案「会議用テーブル他の買入れ」","agenda":"第７２号議案「会議用テーブル他の買入れ」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"備品と一般需用費ということなのですけれども、この間、あちこちで改築になったり、備品を新しく購入されて、とても使い勝手がいいものとか、椅子なんかもテーブルも軽くて、移動がすごくしやすくなったと喜ばれている声もたくさん届いているのですけれども、具体的にこういった備品なんかを選ぶときに、ここには体育館を参考にしたり。","respondent":"平澤経理課長","answer":"今回につきましては、先ほどの会議用テーブルほかについての８ページにありますとおり、品川区立総合区民会館の新しい施設に大きな集会場がありますので、そちらに当たるようなものはきゅりあんが一番使われているということで。","voiceIndex":38,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"立ち上がりが早かったのでというあたり、そこら辺で具体的に誰が選定をするのかという質問をさせていただいたので、そこのところをお願いします。","respondent":"平澤経理課長","answer":"主管課において選定するところです。","voiceIndex":40,"id":"exchange-010"},{"speaker":"石田（慎）委員","kind":"意見","question":"これは契約として区から、例えば机だったらこの机を購入してくださいと、全部物品ごとに注文しての全体の契約になるのか、そのことの１点と、あと、これは基本的に新品なのかなと思うのですが、こういった購入される際に、最近、中古品もいろいろとある中で、たしか八潮のところでは基本的に購入をしないで、いろいろなところから持ってきたと聞いたのですけれども、その辺の考え方はどうなっているのか。","respondent":"平澤経理課長","answer":"そういったところです。もう１つ、リサイクル品ですが、やはり施設の性格によって異なるのではないかと考えています。今回の施設につきましては、区民の方に貸し出しということで、これが第一要件となっていますので、新品でそろえさせていただいたところです。","voiceIndex":44,"id":"exchange-011"},{"speaker":"石田（慎）委員","kind":"質問","question":"新品でというのは理解しているのですが、そういったことを検討するのかどうかというのをお聞きさせていただいたので、例えば新しい施設だから新しい物を入れるという考えなのか、それともいろいろ検討した中で新品の物がいいという判断をしたのか、その辺、検討されたのかどうかをお知らせください。","respondent":"平澤経理課長","answer":"こちらにつきましては、リサイクルということが言われてきているわけですけれども、安定的な供給とかそういったところで、なかなか難しい部分があるのかというところがあります。","voiceIndex":46,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"ということは、小売業者ということになるならば、ほとんどメーカーの仕入れ値は確定している中で、小売がどれだけの管理費、利幅をつける云々ということで、それを低くするかというところで落札できる形になると思うので、かなりシビアな入札だったのかなと思うのですが、区としても物の原価が決まっていて、仕入れ値が決まっている中で競争させるというのは。","respondent":"平澤経理課長","answer":"しかしながら、区の税金で購入するものですので、こういったものにつきましてはきちんとした競争行為をやっていただきまして、その中で工夫していただける部分、例えば販路や何かがあると思うのですけれども、得意の部分からやっていただくことが考えられますので。","voiceIndex":49,"id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"区としては皆さんの税金をお預かりして、地元の業者に何とか入札してほしいと。ですが、なかなかこういう入札する、また、入札結果になると、逆にそれが業者につらい、利幅を削って、いろいろな工夫もあるのだと思うのですけれども、逆に出すことによってそれはもうかるのかもうからないのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-014"}]},{"id":"topic-03","title":"平成２４年請願第９号および(2)平成２４年請願第１０号「固定資産税及び都市計画税の軽減措置の継続」","agenda":"平成２４年請願第９号および(2)平成２４年請願第１０号「固定資産税及び都市計画税の軽減措置の継続」","exchanges":[{"speaker":"阿久津委員","kind":"質問・要望","question":"１つだけ教えてください。先ほど参考資料で配られた「あなたと都税」の抜粋なのですけれども、毎年、同じ請願が出て採択がされているということで、品川区への影響、件数と金額が載っているのですが、これは例えば経年で見て増えているのか減っているのか、そこら辺の分析等をされているのかどうか。もしわかれば教えていただきたいと思います。","respondent":"高森税務課長","answer":"土地の価格に対して東京都の固定資産税等の基準額があるので、これはほぼ変わっていない。ちょっと減っているかなという状況で、影響としては増えてもいないし、減ってもいないという、ぼちぼちというか、同じくらいの状態にあるとご理解いただければと。","voiceIndex":65,"id":"exchange-015"},{"speaker":"大沢委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。なお、結論につきましては、採択ということで取り計らいをお願いしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-016"}]},{"id":"topic-04","title":"」を聴取いたします。「平成２４年度 事務事業評価の実施概要","agenda":"」を聴取いたします。「平成２４年度 事務事業評価の実施概要","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"事業数ということで、本年度９９４対象事業、前年度８７５事業、１４％増ですけれども、これはやはり３.１１を受けて防災関係の事業が増えた割合がかなり、防災関係が多いということなのでしょうか。どこの部分、どういう事業部の事業が増えたのか。予測されることは私にはそう思うのですけれども、それでいいのかどうかお話しください。","respondent":"柏原行財政改革担当課長","answer":"確かに防災関係等々、事業が増えている部分はありますけれども、例えば前回の図書館の事業は１つのくくりでやっていたのですが、１つずつ細かい事業に分けたといったところがございましたので、その関係で数が増えているところです。","voiceIndex":82,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"もう１点が、平成２３年度は区民参加の委員会が開かれましたけれども、このところの評価というか、あまりきちんと把握していないので、平成２３年度の区民が参加した委員会での評価の問題はその後どうなっているのかというのと、ここの新たなところに平成２３年度が反映される部分があるのかどうか、その辺をお伺いします。","respondent":"柏原行財政改革担当課長","answer":"それで、この事務事業評価を今回やる中で、そういったところも含めて、どういった進捗になっているであるとか、どういった評価をするかというところで評価を行うところです。そういったところを含めて平成２５年度の予算に盛り込んでいくという流れになってあります。","voiceIndex":85,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"重点評価のところは分析シートが出るので、それは議会のところでは提示をされるということですか。会議のところは、どういうふうに評価した云々かんぬんのところは、中だけでなく外に、こういった中身でしましたというご提示があるのかとか、そこを教えてください。","respondent":"柏原行財政改革担当課長","answer":"最終的な出し方につきましては、どういった出し方がよろしいかというのは内容を検討しているところなのですけれども、数字として出せる部分、出せない部分があり、出せないというのは簡易評価の部分で出ていない部分もありますので。","voiceIndex":87,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ検討内容がわかるような出し方をしていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-020"},{"speaker":"阿久津委員","kind":"質問","question":"昨年の議事録を読ませていただいて、区民参加の部分なのですけれども、次回、区議会議員が参加することについてということが話題になりまして、そのときに、当時の行革担当課長が、次はどうしていくのかという中で、評価委員会、区民参加の方たちにもアンケートをとって、その結果をまた反映させていきたい、それは全部ではないかと思うのですけれども、そういうご答弁のことでもあったのですが。","respondent":"柏原行財政改革担当課長","answer":"ただ、今後の評価のやり方については、いろいろやり方が考えられますので、そういったところで、例えば今回事務事業評価全事業をまとめますので、こういったやり方については例えば区民の方に入っていただくとか、そういったところは数的な。","voiceIndex":91,"id":"exchange-021"},{"speaker":"石田（慎）委員","kind":"意見","question":"以前やられた区民参加の事務事業評価、今回内部的な事務事業評価、両方ともメリット・デメリットがあると思うのですけれども、区として内部評価での事務事業評価と、外部評価が入った事務事業評価のメリット・デメリットを、お考えがあれば、少しお話をいただければと思います。","respondent":"柏原行財政改革担当課長","answer":"ただ、先ほども申し上げたのですが、数をどの事業をということで、１００本、２００本というようなことは時間的な制約もありますし、その辺は難しい部分がありますので、その評価のメリットを活かすような形で、評価はやっていくべきものだと思ってあります。","voiceIndex":94,"id":"exchange-022"},{"speaker":"石田（慎）委員","kind":"質問","question":"今回平成２４年度は内部での評価に戻すような形になったと思うのですが、その点は区としてメリットの部分が大きいのかなと思うのですが、一度区民の方に参加してもらっているのを、事務事業の評価をやった後に、今回内部的な事務事業評価に戻す経緯と、区としての考え方を教えてください。","respondent":"柏原行財政改革担当課長","answer":"今回、平成２４年度行っておりますのは、結果的には戻したという形にはなるのですけれども、平成２２年度の全事業を評価した際に、先ほども申し上げた大きなくくりでやっているような事業については、例えば拡大のものもあれば見直しのものもあるにもかかわらず。","voiceIndex":96,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"４番の重点的に見直しを行う事業の抽出の中で、上の２つ、評価がＣ（見直し）となった事業、それと新規事業というのはわかるのですが、一番下の特に見直しの必要性が高いと判断した事業、この高いという判断の理由、そこら辺はどう考えたらいいのか、その辺を教えてください。","respondent":"柏原行財政改革担当課長","answer":"事業を全体で抽出した際に、重点等を分ける際に、企画部で、例えばこの事業は今まで先ほどのこれまでの経緯の中で、継続性といいますか、見直しをしなくてはいけないという、例えば予算削減の中でこういう問題があったとか、いろいろな問題があった、企画部のまず考え方で。","voiceIndex":99,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"来年度予算に向けてだから、予算から入っていくのかなという中で、その辺が自分の中でわかりにくいかなと。予算が先なのか、事業が先なのかというところの考え方。それだからこそ、チェックしたととればいいのかなというのが１点と、それから、特に必要性が高いことというのは、一覧表の中で特別にわかる、それとも全くほかのものと同じような表現で出てしまうのかなというのは、その辺はどうですか。","respondent":"柏原行財政改革担当課長","answer":"ただ、その中でこの３種類がわかるかどうかは今回の資料では多分わからない形で、全部まとめた形の印で出することで考えています。","voiceIndex":101,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今現在だとそういう形かもしれないけれども、我々の中でも新規事業とかＣになったものは自分で見つければいいのだけれども、逆に言うと区がどう考えているのかなというのが早くわかりやすいというと変な言い方だけれども、いろいろなところに出る資料の中でも、議会だけとなると表にも出てきたときに、区が何を重点的に考えているのかなというのが出るかなという。","respondent":"柏原行財政改革担当課長","answer":"今回の決算委員会の資料でどこまでできるかどうかということはあるのですけれども。","voiceIndex":103,"id":"exchange-026"},{"speaker":"大沢委員","kind":"質問","question":"今、議長から予算への対応、区の考え方ということで、さらに行財政改革担当課長から中間・最終報告という中で、４番の平成２３年度新規事業ということ、５番の各事業部長によるということ、それと平成２５年予算編成の対応ということで、この中で、新規事業ということで先ほどもお話というか質問させていただいたのですけれども、防災ということ、要は３.１１という、いわゆる事象・事故がありまして。","respondent":"柏原行財政改革担当課長","answer":"防災対策云々というのはありますけれども、我々は一定の基準に沿った形で防災対策であろうが何であろうが同じ基準で同じチェックをして、同じような判断を、中には防災対策であっても見直しをするという判断が出ているところもありますので。","voiceIndex":108,"id":"exchange-027"},{"speaker":"大沢委員","kind":"意見","question":"何かここのところ、いろいろな部分で防災対策の文言を聞くと、すぐにこれが必要性がやはり高い部分が去年の３.１１からあるやに思われてしようがないので、そこのところの考え方を聞かせていただいたところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"１点だけお聞きしたいのですが、重点的な見直しということで、事業実績、コストなどのデータに基づきということで書いてあります。ですが、それは逆に区民の肉体的に健康増進につながって、医療の削減、介護費の削減とか、そういうふうにつながるという事例があった場合に、そのときの評価はどういうふうに考えられるのでしょうか。","respondent":"柏原行財政改革担当課長","answer":"ただ、副次的な効果でいろいろなものがあるというような場合は、このＡ、Ｂ、Ｃ、Ｄの評価以外にもコメントを書かせていただくところがありますので、このことについてはこういう見直しが必要なのではないか、こういうことではないかというのは。","voiceIndex":114,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1924#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":22781,"voices":120}}]);
